window.CATALOGOS={"usos":[["AgR","agrícola de riego y protegida"],["AgT","agrícola de temporal"],["CS","agroecosistemas de café"],["Cac","agroecosistemas de cacao"],["Agi","agroindustria"],["Api","apicola"],["Acua","acuícola"],["AshR","asentamientos humanos rurales"],["AshU","asentamientos humanos urbanos"],["Cons","conservación"],["Com","comercio"],["Ecog","equipamiento comercial de gran escala"],["FoM","forestal maderable"],["FnM","forestal no maderable"],["PIn","ganadería intensiva"],["PEx","ganadería extensiva"],["InL","industria de bajo impacto o industria ligera"],["Iaz","infraestructura azul"],["lazr","infraestructura azul restringida"],["Ivd","infraestructura verde"],["Ivi","infraestructura vial"],["Imi","infraestructura turistica de miradores"],["Ide","infraestructura de distribución eléctrica"],["Iserv","infraestructura de servicios (drenaje y agua potable)"],["Itar","infraestructura de aguas residuales"],["Ice","infraestructura de control de erosión"],["Isñ","infraestructura de señaletica ecológica"],["Ihi","infraestructura de distribución y expendio de hidrocarburos"],["Irsu","infraestructura de residuos sólidos urbanos"],["Icah","infraestructura complementaria a asentamientos humanos"],["Plan","plantaciones de frutales"],["Pal","plantaciones de palmeras"],["PGS","proyectos de generación de energía solar"],["PGE","proyectos de generación de energía eólica"],["Sfc","sistemas fotovoltaicos complementarios"],["MnM","minería no metálica"],["Pes","pesca ribereña"],["Esc","escombrera"],["TAl","turismo alternativo"],["Tur","turismo convencional"],["Tru","turismo rural o agroturismo"]],"crit":{"AgR01":{"d":"Ejercer agricultura de riego únicamente en zonas delimitadas con infraestructura hidráulica funcional, fuera de zonas de recarga prioritaria, barrancas y áreas naturales protegidas","s":"Agricultura de riego"},"AgR02":{"d":"Evitar la expansión de riego en suelos agrícolas de temporal sin estudios de factibilidad hídrica, disponibilidad de volumen concesionado y plan técnico de manejo","s":"Agricultura de riego"},"AgR03":{"d":"Establecer perímetros agrícolas de riego en polígonos aptos con pendiente menor a 8%, suelos de profundidad media o alta, y sin evidencia de sobreexplotación del acuífero","s":"Agricultura de riego"},"AgR04":{"d":"Instalar sistemas de riego tecnificado (goteo, aspersión de baja presión o microaspersión) en todas las unidades agrícolas de riego nuevas o rehabilitadas","s":"Agricultura de riego"},"AgR05":{"d":"Evitar la infiltración de aguas residuales no tratadas en predios de riego, y condicionar el uso de aguas residuales tratadas a análisis de calidad y cumplimiento de NOMs","s":"Agricultura de riego"},"AgR06":{"d":"Mantener barreras vivas o franjas de amortiguamiento de 10 metros alrededor de cuerpos de agua o drenajes agrícolas, con vegetación nativa o de uso forrajero no fertilizado","s":"Agricultura de riego"},"AgR07":{"d":"Construir áreas de resguardo seguras para agroquímicos y fertilizantes, con piso impermeable y techado, fuera de zonas de escurrimiento o cercanas a pozos","s":"Agricultura de riego"},"AgR08":{"d":"Separar y almacenar los envases vacíos de plaguicidas y herbicidas en centros de acopio autorizados o programas de recolección temporal, como requisito de permanencia del uso agrícola","s":"Agricultura de riego"},"AgR09":{"d":"Incorporar prácticas de labranza mínima, acolchado vegetal y mantenimiento de materia orgánica en suelos de riego con tendencia a compactación","s":"Agricultura de riego"},"AgR10":{"d":"Todo proyecto agrícola que contemple el uso de sistemas de riego deberá presentar, previo al inicio de actividades o ampliación de superficie, un estudio de factibilidad hídrica que incluya el balance entre disponibilidad y demanda de agua, evaluación del impacto sobre acuíferos o cuerpos superficiales, eficiencia del sistema de riego propuesto y riesgo de salinización o degradación del suelo. Dicho estudio deberá ser validado por la autoridad competente en materia hídrica y ambiental, y en caso de zonas con estrés hídrico o acuíferos sobreexplotados, se deberán integrar medidas de gestión eficiente, tecnologías de riego presurizado o localizado, y, si aplica, acciones de compensación ambiental o recarga inducida. Asimismo, en regiones con antecedentes de conflicto por agua o presión sobre ecosistemas ribereños o humedales, el estudio deberá contemplar el posible impacto socioambiental a escala de cuenca.","s":"Agricultura de riego"},"AgR11":{"d":"El desarrollo de actividades de agricultura de riego estará condicionado a que se cuenten con los títulos de concesión correspondientes en materia de agua. Así como un dictamen de factibilidad de la autoridad competente.","s":"Agricultura de riego"},"AgR12":{"d":"Las actividades agrícolas estarán condicionadas a la tecnificación de los sistemas de riego en al menos el 25 % de la superficie total a mediano plazo y el 50 % a largo plazo.","s":"Agricultura de riego"},"AgT01":{"d":"El uso, aplicación, almacenamiento y disposición final de agroquímicos (insecticidas, herbicidas, fertilizantes y plaguicidas) se realizará de acuerdo con las Normas Oficiales Mexicanas vigentes y las disposiciones de la CICOPLAFEST (Comisión Intersecretarial para el Control del Proceso y Uso de Plaguicidas, Fertilizantes y Sustancias Tóxicas), utilizando únicamente productos autorizados y vigentes; queda estrictamente prohibido el uso de productos caducos, de procedencia ilegal, transgénicos no autorizados, o la aplicación de herbicidas químicos en suelos porosos o márgenes de lagunas y cuerpos de agua. Se fomentará la transición hacia cultivos orgánicos y el uso de métodos naturales que reduzcan la dependencia de insumos químicos, dando énfasis a la fertilidad del suelo y la actividad biológica.","s":"Agricultura de temporal"},"AgT02":{"d":"El uso de agroquímicos inorgánicos en zonas adyacentes a ecosistemas naturales o a Unidades de Gestión Ambiental de protección deberá considerar una franja de amortiguamiento mínima de 50 metros, libre de la aplicación de productos químicos, ocupada preferentemente con vegetación establecida por siembra o regeneración natural entre áreas de diferentes cultivos permanentes o semipermanentes.","s":"Agricultura de temporal"},"AgT03":{"d":"El área de cultivo deberá mantener una franja de amortiguamiento boscosa de al menos 30 metros geodésicos de ancho respecto a ríos y cuerpos de agua, contados desde el borde de la zona federal. Se protegerán y preservarán los cauces naturales y los patrones geohidrológicos de la zona, quedando prohibida su desviación o modificación hacia nuevos canales de drenaje o riego.","s":"Agricultura de temporal"},"AgT04":{"d":"Se prohíbe la expansión de la superficie agrícola a costa del aprovechamiento forestal mediante el desmonte, el cinchamiento o muerte de la vegetación forestal por cualquier vía o procedimiento, así como la afectación al paisaje, la quema, remoción o barbecho de ecosistemas de pastizales naturales, bosques templados, selva baja caducifolia o matorrales. Las zonas donde se remueva la vegetación natural se considerarán sujetas a restauración ecológica y no podrán destinarse a fines productivos.","s":"Agricultura de temporal"},"AgT05":{"d":"El cambio de uso de suelo a agricultura de temporal, así como la expansión de la superficie agrícola, solo podrá autorizarse en predios que no contengan ecosistemas frágiles, especies raras o en peligro de extinción, corredores biológicos o vegetación original en buen estado, y que no estén sujetos a programas de restauración ecológica, quedando excluidas las zonas de sierras, cañones y suelos no aptos; en todo caso, las actividades agrícolas se sujetarán a estrictas medidas de control para no generar efectos negativos sobre los ecosistemas.","s":"Agricultura de temporal"},"AgT06":{"d":"En terrenos agrícolas con pendiente se aplicarán prácticas de conservación de suelo según su grado de inclinación: en pendientes de hasta 10% se utilizarán canales de desvío y surcado en contorno para reducir la escorrentía superficial y la erosión; en pendientes mayores al 8% los cultivos se realizarán mediante terrazas y franjas siguiendo las curvas de nivel; en pendientes mayores al 10% las prácticas de barbecho, surcado y terraceo se realizarán en sentido perpendicular a la pendiente.","s":"Agricultura de temporal"},"AgT07":{"d":"Se excluye el establecimiento de cualquier tipo de agricultura en laderas o zonas de deslizamiento, en suelos poco profundos con pendientes mayores a 20 grados y alta susceptibilidad a la erosión, así como en áreas con pendientes mayores al 30%, las cuales se considerarán preferentemente forestales y sujetas a proyectos de restauración ecológica. En las áreas preferentemente forestales con pendientes mayores al 35% que se encuentren sujetas a aprovechamiento agropecuario, se llevarán a cabo acciones de restauración de la cobertura vegetal natural con especies nativas.","s":"Agricultura de temporal"},"AgT08":{"d":"Las unidades de producción agrícola establecerán sitios especiales para la disposición de envases y residuos de agroquímicos, agroplásticos y materiales de empaque (cintillas, cañerías, cubiertas de invernadero, semilleros, entre otros), manejándolos conforme a las etapas de manejo integral de residuos de manejo especial y priorizando su valorización sobre la disposición final, a fin de evitar la contaminación de aguas superficiales y subterráneas por el uso inadecuado, la mala disposición de envases, la escorrentía de plaguicidas y fertilizantes, o la lixiviación de nitrógeno, fósforo y nitratos.","s":"Agricultura de temporal"},"AgT09":{"d":"Cuando se incorporen desechos biológicos u orgánicos al terreno de cultivo que representen un riesgo de contaminación al producto, se aplicarán tratamientos fitosanitarios, ya sean químicos o naturales (como la solarización o la desinfección por vapor de agua).","s":"Agricultura de temporal"},"AgT10":{"d":"Se fomentará la agricultura de conservación mediante labranza cero o de conservación, sembrando sobre la cobertura de residuos del cultivo anterior para incrementar la infiltración de agua y la retención de materia orgánica. Para reducir el lavado de nitratos se mantendrá la máxima cobertura vegetal posible, se reducirá el laboreo en otoño, se evitará la quema de rastrojos y esquilmos, se enterrarán las pajas y se limitará la carga de ganado en praderas fertilizadas. En todo caso, la agricultura deberá realizarse evitando la degradación de los suelos por erosión o por modificación de sus características fisicoquímicas, sin afectar la biodiversidad de los ecosistemas de la UGA.","s":"Agricultura de temporal"},"AgT11":{"d":"Se emplearán métodos culturales, biológicos, mecánicos y físicos para el control de plagas y roedores (rotación de cultivos, control biológico, trampeo, entre otros), privilegiando métodos no químicos que no afecten el equilibrio del ecosistema.","s":"Agricultura de temporal"},"AgT12":{"d":"En todas las áreas de agricultura de temporal se establecerá un sistema de captación y almacenamiento de agua de lluvia, y se fomentará la instalación de sistemas de riego de bajo consumo de agua. Cuando se aproveche el recurso hídrico, se deberá contar con la autorización de la Comisión Nacional del Agua o el organismo competente, y estar registrado en el Registro Público de Derechos del Agua (REPDA).","s":"Agricultura de temporal"},"AgT13":{"d":"Las quemas agrícolas en terrenos abiertos se realizará bajo las disposiciones de la Norma Oficial Mexicana vigente que establece las especificaciones técnicas de métodos de uso del fuego en los terrenos forestales y en los terrenos de uso agropecuario.","s":"Agricultura de temporal"},"AgT14":{"d":"Se implementará el uso de cercas vivas con especies arbóreas nativas.","s":"Agricultura de temporal"},"AgT15":{"d":"Se fomentará el uso múltiple del suelo en traspatio (hortalizas biodinámicas, manejo de aves de corral, árboles frutales, cunicultura, porcicultura, apicultura, acuacultura), para favorecer el auto abasto, incrementar la disponibilidad de productos para la dieta familiar y asegurar mayores excedentes comercializables y retornos monetarios al trabajo familiar.","s":"Agricultura de temporal"},"AgT16":{"d":"Se prohíbe el almacenamiento, uso alimentario y siembra de semillas y material vegetal transgénico para fines agrícolas, hortícolas, y pecuarios, a menos de que exista un estudio técnico y científico que demuestre que el material no afecta a los ecosistemas naturales, la salud humana y la del ganado.","s":"Agricultura de temporal"},"AgT17":{"d":"En las unidades de producción donde se cultiven especies anuales se establecerá un cultivo de cobertura al final de cada ciclo del cultivo que será incorporado como abono verde o bien utilizado como forraje para el ciclo siguiente. Estas especies podrán ser leguminosas como garbanzo, chícharo, trébol dulce o frijol terciopelo; cereales como trigo, centeno, avena, o bien podrá aplicarse alguna mezcla como avena más trébol.","s":"Agricultura de temporal"},"AgT18":{"d":"Se prohíbe el uso del fuego en predios y terrenos agrícolas, priorizando la incorporación de los residuos orgánicos al suelo y su empacado para reutilización.","s":"Agricultura de temporal"},"AgT19":{"d":"Las áreas agrícolas de alta productividad se considerarán espacios de recursos estratégicos; por lo tanto, no podrán ser sustituidos por desarrollos urbanos o industriales bajo ningún procedimiento alternativo a las disposiciones del presente programa.","s":"Agricultura de temporal"},"AgT20":{"d":"En áreas agrícolas cercanas a centros de población y/o hábitats de fauna silvestre, la aplicación de agroquímicos deberá considerar una distancia de por lo menos 30 metros y se hará de forma cuidadosa y localizada, a fin de evitar la dispersión.","s":"Agricultura de temporal"},"AgT21":{"d":"En las zonas de uso agrícola que formen o pasen a formar parte de los cinturones verdes de carácter forestal se realizarán prácticas de reforestación únicamente con especies nativas.","s":"Agricultura de temporal"},"AgT22":{"d":"La disposición de desperdicios de cosechas deberá ser composteados para su reúso agrícola.","s":"Agricultura de temporal"},"AgT23":{"d":"Para reducir la pérdida de suelo se establece que las actividades de laboreo agrícola en suelos profundos bien drenados y permeables no se permitan cuando el valor de erosión supere las 1.8 ton/ha/año y tampoco en suelos poco profundos y de permeabilidad reducida cuando el valor de erosión supere las 0.4 ton/ha/año.","s":"Agricultura de temporal"},"Caf01":{"d":"Establecer las plantaciones de café preferentemente bajo sombra (sistema agroforestal), conservando al menos el 40% de cobertura arbórea nativa dentro del cafetal.","s":"Agroecosistemas de café bajo sombra"},"Caf02":{"d":"Integrar las unidades de producción a la Campaña Nacional contra la Broca del Café, aplicando monitoreo y manejo integrado de plagas.","s":"Agroecosistemas de café bajo sombra"},"Caf03":{"d":"Prohibir el establecimiento de cafetales mediante el desmonte de vegetación forestal primaria; solo se permitirá la reconversión de acahuales o zonas ya perturbadas.","s":"Agroecosistemas de café bajo sombra"},"Caf04":{"d":"Manejar los residuos del beneficio húmedo del café (pulpa, mucílago, aguas mieles) mediante fosas de oxidación, compostaje o biodigestión, quedando prohibido su vertido directo a cuerpos de agua.","s":"Agroecosistemas de café bajo sombra"},"Caf05":{"d":"Establecer una franja de amortiguamiento de al menos 20 metros entre las plantaciones de café y cuerpos de agua o cauces.","s":"Agroecosistemas de café bajo sombra"},"Caf06":{"d":"Limitar el uso de agroquímicos inorgánicos en cafetales colindantes con áreas de conservación, aplicando una franja libre mínima de 30 metros.","s":"Agroecosistemas de café bajo sombra"},"Caf07":{"d":"Fomentar la certificación agroecológica u orgánica del café como condición de permanencia en zonas de alta fragilidad ecológica.","s":"Agroecosistemas de café bajo sombra"},"Caf08":{"d":"Conservar los árboles de sombra de especies nativas (maderables, frutales o de uso múltiple) como corredores de conectividad biológica dentro del paisaje cafetalero.","s":"Agroecosistemas de café bajo sombra"},"Caf09":{"d":"En los sitios con café bajo sombra se realizará manejo agroecológico de plagas y enfermedades, reduciendo paulatinamente el uso agroquímicos hasta lograr su eliminación.","s":"Agroecosistemas de café bajo sombra"},"Caf10":{"d":"En paisajes con café de sombra se realizará el monitoreo de fauna de grupos como aves, mariposas, mamíferos, entre otros.","s":"Agroecosistemas de café bajo sombra"},"Caf11":{"d":"En paisajes con cafetales bajo sombra se promoverá el establecimiento de corredores biológicos con la vegetación natural adyacente.","s":"Agroecosistemas de café bajo sombra"},"Caf12":{"d":"Los productores de café de sombra son compensados económicamente por los servicios hidrológicos y ecosistémicos con los que contribuye la actividad.","s":"Agroecosistemas de café bajo sombra"},"Caf13":{"d":"En la producción de café bajo sombra, se da prioridad al uso de mejoradores del suelo y bio insumos agroecológicos","s":"Agroecosistemas de café bajo sombra"},"Caf14":{"d":"El uso de agroquímicos para el control de plagas y enfermedades en el cultivo de café de sombra, se deberá reducir al mínimo, privilegiando el uso de insumos orgánicos.","s":"Agroecosistemas de café bajo sombra"},"Caf15":{"d":"Con la finalidad de alcanzar el manejo agroecológico se implementará un periodo de transición de tres a cinco años para la sustitución del uso de agroquímicos.","s":"Agroecosistemas de café bajo sombra"},"Caf16":{"d":"En los cafetales de sombra, se implementarán obras para la retención de agua, suelo y la preservación de hábitat para especies emblemáticas de la región.","s":"Agroecosistemas de café bajo sombra"},"Caf17":{"d":"Se realizará la integración y actualización continua, del padrón de agricultores que adoptan los criterios ecológicos en las prácticas de cultivo, para darles prioridad de acceder a los incentivos agrícolas.","s":"Agroecosistemas de café bajo sombra"},"Caf18":{"d":"Los productores cumplen con los mecanismos y requerimientos para la verificación establecida para la producción de café orgánico y otras etiquetas.","s":"Agroecosistemas de café bajo sombra"},"Caf19":{"d":"La explotación de recursos naturales renovables en los cafetales de sombra, es igual o menor a sus tasas de regeneración, para garantizar que cumplan su funciones ecológicas.","s":"Agroecosistemas de café bajo sombra"},"Caf20":{"d":"La reconversión productiva de los cafetales de sombra, por café de sol u otra actividad agrícola o agropecuaria que altere la conectividad del paisaje no podrá realizarse en las UGA de Preservación o Restauración ecológica.","s":"Agroecosistemas de café bajo sombra"},"Caf21":{"d":"Las preparación de terrenos para la siembra se lleva a cabo mediante la realización de labores culturales, minimizando la erosión del suelo y la emisión de partículas.","s":"Agroecosistemas de café bajo sombra"},"Caf22":{"d":"Todos los residuos de la cafeticultura, como residuos de cosecha y otros deben ser preferentemente sometidos a procesos de composteo.","s":"Agroecosistemas de café bajo sombra"},"Caf23":{"d":"La implementación y mantenimiento de cercas vivas utilizarán especies nativas.","s":"Agroecosistemas de café bajo sombra"},"Caf24":{"d":"Se apoya técnica y financieramente los esfuerzos comunitarios de conservación y rescate de fauna y flora silvestre.","s":"Agroecosistemas de café bajo sombra"},"Caf25":{"d":"Los proyectos de agroturismo contarán con un reglamento que minimice impactos ambientales hacia la flora, fauna y formaciones geológicas, producto de las actividades turísticas y recreativas.","s":"Agroecosistemas de café bajo sombra"},"Caf26":{"d":"No se hará uso de cebos con veneno para el control de plagas en áreas de cafeticultura que pongan en riesgo a la fauna nativa.","s":"Agroecosistemas de café bajo sombra"},"Caf27":{"d":"La recolección de hongos, frutos, semillas, partes vegetativas y especímenes completos no maderables para fines de autoconsumo y en concordancia con los usos y costumbres de la población rural, podrá llevarse a cabo siempre y cuando no pongan en riesgo a la flora y fauna.","s":"Agroecosistemas de café bajo sombra"},"Caf28":{"d":"La entrega de plaguicidas de síntesis química, tales como herbicidas, insecticidas o fungicidas, por cualquier dependencia de los tres órganos de gobierno (federal, estatal y municipal) no podrá realizarse en las áreas de café de sombra, por lo que todo paquete tecnológico promovido por los diferentes programas de gobierno estará integrado por tecnologías acordes a un manejo agroecológico, dando prioridad al uso de insumos biorganico.","s":"Agroecosistemas de café bajo sombra"},"Cac01":{"d":"Establecer las plantaciones de cacao bajo sistemas agroforestales que conserven la cobertura arbórea nativa, evitando el monocultivo a libre exposición.","s":"Agroecosistemas de cacao"},"Cac02":{"d":"Aplicar las medidas fitosanitarias de manejo y eliminación de focos de infestación de plagas.","s":"Agroecosistemas de cacao"},"Cac03":{"d":"Prohibir el establecimiento de plantaciones de cacao mediante el desmonte de selva o bosque tropical primario.","s":"Agroecosistemas de cacao"},"Cac04":{"d":"Establecer una franja de amortiguamiento de al menos 20 metros entre las plantaciones y cuerpos de agua o humedales.","s":"Agroecosistemas de cacao"},"Cac05":{"d":"Conservar y diversificar el dosel arbóreo del cacaotal con especies maderables y frutales nativas que brinden servicios de polinización y sombra.","s":"Agroecosistemas de cacao"},"Cac06":{"d":"Manejar los residuos de poscosecha (cáscara, mucílago) mediante compostaje in situ, quedando prohibida su quema a cielo abierto.","s":"Agroecosistemas de cacao"},"Cac07":{"d":"Fomentar la certificación agroforestal u orgánica del cacao en zonas colindantes con áreas naturales protegidas o corredores biológicos.","s":"Agroecosistemas de cacao"},"Cac08":{"d":"Limitar la apertura de caminos de acceso a plantaciones de cacao en zonas con pendiente mayor al 15%, aplicando obras de conservación de suelo.","s":"Agroecosistemas de cacao"},"Agi01":{"d":"Ubicar las unidades agroindustriales únicamente en zonas agropecuarias o industriales fuera de Áreas Naturales Protegidas, zonas de recarga hídrica, cauces, barrancas, humedales, sitios prioritarios para la conservación y corredores ecológicos.","s":"Agroindustria"},"Agi02":{"d":"Garantizar que las agroindustrias cuenten con infraestructura adecuada para el tratamiento de aguas residuales, priorizando el reúso para riego agrícola o industrial, conforme a la NOM-001-SEMARNAT-2021.","s":"Agroindustria"},"Agi03":{"d":"Establecer zonas de amortiguamiento ecológico (≥10 m) con barreras vegetales nativas entre la infraestructura agroindustrial y caminos rurales y viviendas, para mitigar emisiones, escurrimientos y dispersión de partículas.","s":"Agroindustria"},"Agi04":{"d":"Fomentar el uso de energías renovables (solar, biomasa o eólica) y tecnologías de bajo impacto en los procesos de transformación, empaque y almacenamiento, reduciendo el consumo energético y la huella de carbono.","s":"Agroindustria"},"Agi05":{"d":"Promover la gestión integral de residuos sólidos y subproductos agroindustriales (como bagazo, cáscaras, residuos orgánicos), incentivando su aprovechamiento como insumos para composta, biogás o alimento animal.","s":"Agroindustria"},"Agi06":{"d":"Priorizar materias primas provenientes de unidades productivas con prácticas agrícolas sustentables, con certificaciones como Buenas Prácticas Agrícolas (BPA), Sistemas de Reducción de Riesgos de Contaminación (SRRC) o similares.","s":"Agroindustria"},"Agi07":{"d":"Exigir la presentación de instrumentos de regulación ambiental (MIA, Cédula de Operación Anual, Programa de Manejo Ambiental) para nuevos desarrollos agroindustriales, conforme a su nivel de impacto.","s":"Agroindustria"},"Agi08":{"d":"Fomentar la capacitación continua de los trabajadores en prácticas de producción limpia, gestión ambiental y adaptación al cambio climático.","s":"Agroindustria"},"Agi09":{"d":"Integrar criterios de resiliencia y adaptación climática en el diseño de las agroindustrias (captación pluvial, techos verdes, zonas de sombra), minimizando su vulnerabilidad ante eventos extremos como sequías o inundaciones.","s":"Agroindustria"},"Agi10":{"d":"Se implementará un manejo integral de residuos y subproductos de origen animal, asegurando su almacenamiento temporal seguro, transporte y disposición final autorizada, quedando prohibida su quema, vertido o disposición a cielo abierto.","s":"Agroindustria"},"Agi11":{"d":"La agroindustria deberá incorporar medidas de control sanitario, control de olores, emisiones y fauna nociva, así como programas permanentes de limpieza, desinfección y monitoreo ambiental, en cumplimiento de la normatividad sanitaria y ambiental vigente.","s":"Agroindustria"},"Agi12":{"d":"Los rastros e industria deberán implementar planes de contingencia para derrames, fallas en el tratamiento de aguas, emergencias sanitarias y eventos extremos, a fin de prevenir impactos ambientales y riesgos a la población.","s":"Agroindustria"},"Agi13":{"d":"Se deberá evitar la impermeabilización innecesaria del suelo, promoviendo superficies permeables, sistemas de captación pluvial y obras de infiltración que reduzcan escurrimientos y riesgos de contaminación.","s":"Agroindustria"},"Agi14":{"d":"Las actividades de carga, descarga y transporte asociadas a la agroindustria de origen animal deberán organizarse de forma que minimicen afectaciones por ruido, tráfico y emisiones, especialmente en horarios cercanos a zonas habitacionales.","s":"Agroindustria"},"Agi15":{"d":"Los proyectos agroindustriales que se promuevan en la UGA deberán desarrollarse evitando las zonas identificadas como de riesgo muy alto y alto","s":"Agroindustria"},"Agi16":{"d":"Las actividades agroindustriales deberán contar con un proyecto integral hídrico que contemple el reúso de al menos el 50 % y el tratamiento del total de sus aguas residuales.","s":"Agroindustria"},"Agi17":{"d":"Las actividades agroindustriales deberán prevenir y reducir la generación de residuos, dando un manejo integral adecuado y privilegiando la valorización sobre su disposición final.","s":"Agroindustria"},"Agi18":{"d":"Se prohíbe el depósito de residuos sólidos, así como las descargas industriales sin tratamiento a cuerpos de agua y escurrimientos permanentes o temporales. Las empresan que hagan caso omiso a esta disposición seran acreedoras a la sanción que determine la autoridad competente en la materia.","s":"Agroindustria"},"Agi19":{"d":"Las actividades agroindustriales que requieran de un alto consumo de agua deberán contar con sistemas de captación de agua de lluvia que subministren al menos el 15 % del agua requerida.","s":"Agroindustria"},"Agi20":{"d":"Se permitirá únicamente la instalación de agroindustrias que formen parte de la cadena productiva agroalimentaria regional.","s":"Agroindustria"},"Agi21":{"d":"En zonas de alta productividad agrícola se limitará la instalación de agroindustrias a aquellas que brinden valor agregado a los cultivos locales.","s":"Agroindustria"},"Agi22":{"d":"El desarrollo de proyectos agroindustriales estará condicionado a que se cuenten con los títulos de concesión correspondientes en materia de agua. Así como un dictamen de factibilidad hídrica emitido por la autoridad competente.","s":"Agroindustria"},"Api01":{"d":"La distancia mínima para la instalación de apiarios será de 200 y 500 metros de distancia de vías públicas, casas de vecinos y animales (excepto de los dueños). La consideración más importante para apiarios localizados en ciudades y pueblos son los vecinos.","s":"Apicultura"},"Api02":{"d":"La utilización de ahumadores se realizará con combustibles de productos orgánicos no contaminados por productos químicos, evitando la utilización de hidrocarburos, plásticos y/o excretas de animales que expongan a contaminación y/o alteren la miel.","s":"Apicultura"},"Api03":{"d":"Los apiarios se ubicarán a una distancia no menor a tres kilómetros de posibles fuentes de contaminación como basureros a cielo abierto, centros industriales, entre otros.","s":"Apicultura"},"Api04":{"d":"El uso de repelentes químicos para el manejo de abejas, insecticidas, así como productos químicos y/o derivados del petróleo queda excluido para el control de plagas en los apiarios.","s":"Apicultura"},"Api05":{"d":"La reforestación de las áreas apícolas se llevará a cabo con especies melíferas nativas para la conservación de los bienes y servicios ecosistémicos.","s":"Apicultura"},"Api06":{"d":"Los apicultores manejarán y diversificarán la vegetación productora de flora nectifera y polinífera en la proximidad de los apiarios de acuerdo la vegetación nativa.","s":"Apicultura"},"Api07":{"d":"Se reducirá el uso de agroquímicos, durante la implementación de proyectos apícolas, agroquímicos ya que dichos productos causan mortandad en las abejas.","s":"Apicultura"},"Api08":{"d":"Todos los productos que se utilicen en las colmenas deberán ser naturales como el propóleo, la cera y los aceites vegetales, quedando prohibido el uso de repelentes químicos, durante las operaciones de recolección de la miel.","s":"Apicultura"},"Api09":{"d":"Quedan prohibidas las prácticas como mutilación, cortar la punta de las alas de las abejas reinas, y la recolección de miel en panales y/o núcleos con crías, lo cual también se encuentra en apego con las Buenas Practicas Pecuarias.","s":"Apicultura"},"Api10":{"d":"La alimentación artificial de las colonias de abejas sólo estará permitida cuando la supervivencia de las colmenas esté comprometida por condiciones meteorológicas excepcionales o una catástrofe que impida la producción de néctar o mielada.","s":"Apicultura"},"Api11":{"d":"Los apiarios y/o meliponarios en los que se emplee la alimentación artificial deberán tener disponibles los registros indicando: Tipo de insumo utilizado, fechas de suministro, cantidades utilizadas y colmenas en las que se utilizó alimentación artificial.","s":"Apicultura"},"Api12":{"d":"Las actividades de apicultura se realizarán con especies nativas y sin afectar el ecosistema.","s":"Apicultura"},"Api13":{"d":"Las cajas de las colmenas son hechas de materiales naturales que no porten riesgos de contaminación para las abejas, el medio ambiente ni para los productos de la apicultura.","s":"Apicultura"},"Api14":{"d":"Se considera ambientalmente prioritario el aprovechamiento de la abeja nativa, por encima del de la abeja euroafricana.","s":"Apicultura"},"Api15":{"d":"En el caso de nuevos apiarios y meliponarios o cajas de colmenas, se puede utilizarse cera de abeja no orgánica únicamente cuando se demuestre que está libre de contaminación con sustancias no permitidas, para la cera de los nuevos cuadros deberá proceder de unidades de producción orgánica o bien estar libre de sustancias no aptas.","s":"Apicultura"},"Api16":{"d":"Son prioritarios los estudios de la flora apícola para contribuir a que el productor tome decisiones en torno a la polinización y el aprovechamiento múltiple de los recursos.","s":"Apicultura"},"Api17":{"d":"Se otorgará apoyo técnico y financiero de instituciones públicas y privadas para la creación de agroindustrias para el desarrollo de la cadena de valor apícola, observando todas las medidas anticontaminantes de agua, suelo, subsuelo, y el resto del entorno ambiental.","s":"Apicultura"},"Acui01":{"d":"Las actividades acuícolas deberán prevenir cualquier forma de contaminación del recurso hídrico mediante el tratamiento adecuado de aguas residuales, evitando descargas directas a cuerpos de agua naturales y respetando una franja de protección de al menos 200 metros respecto a escurrimientos y canales de infiltración.","s":"Acuícola"},"Acui02":{"d":"Se prohíbe la modificación de cauces naturales, el desvío de escurrimientos y la alteración del caudal ecológico; cualquier infraestructura acuícola deberá mantener los flujos naturales de agua sin afectar obras hidráulicas.","s":"Acuícola"},"Acui03":{"d":"Las unidades acuícolas no podrán utilizar fuentes de agua concesionadas para consumo humano y deberán drenar sus aguas tratadas preferentemente hacia áreas agropecuarias, asegurando el menor impacto ambiental posible.","s":"Acuícola"},"Acui04":{"d":"Toda unidad de producción acuícola deberá contar con un plan de manejo ambiental que considere el diseño, operación, monitoreo y cierre de actividades, priorizando tecnologías limpias y compatibles con el medio ambiente.","s":"Acuícola"},"Acui05":{"d":"En el abandono de proyectos acuícolas se deberá retirar la infraestructura instalada, restaurar los flujos de agua originales y reforestar con especies nativas; además, se deberán retirar y manejar correctamente los residuos generados.","s":"Acuícola"},"Acui06":{"d":"Solo se permitirá la acuicultura con especies nativas en cuerpos de agua naturales; se prohíbe el uso de especies transgénicas o exóticas, así como cualquier práctica que facilite escapes al medio natural.","s":"Acuícola"},"Acui07":{"d":"La infraestructura terrestre para actividades pesqueras (bodegas, embarcaderos, zonas de almacenamiento y procesamiento) deberá cumplir con la normativa ambiental vigente, incluyendo el manejo adecuado de residuos sólidos, aguas servidas y materiales peligrosos.","s":"Acuícola"},"Acui08":{"d":"Las actividades pesqueras como la limpieza de organismos, el mantenimiento de embarcaciones y la operación en atracaderos deberán realizarse en sitios adecuados, con señalética ambiental, medidas de seguridad y prevención de impactos.","s":"Acuícola"},"Acui09":{"d":"Durante los periodos de veda establecidos por la autoridad competente, queda estrictamente prohibida la realización de actividades de pesca en cuerpos de agua superficiales del municipio, con el fin de permitir la reproducción, recuperación y conservación de las poblaciones acuáticas y mantener el equilibrio ecológico de los ecosistemas asociados.","s":"Acuícola"},"Acui10":{"d":"Las actividades de acuacultura que se realicen dentro o en las riberas de ecosistemas acuáticos se efectuarán con especies nativas y sin afectar negativamente estos ecosistemas.","s":"Acuícola"},"Acui11":{"d":"Se prohíbe la contaminación genética de las poblaciones locales de fauna y flora derivada de la introducción de individuos con genes que no han sido seleccionados naturalmente.","s":"Acuícola"},"Acui12":{"d":"Las unidades de producción acuícola deberán contar con un sistema de tratamiento primario de las aguas residuales.","s":"Acuícola"},"Acui13":{"d":"Se prohíbe la descarga directa de aguas residuales derivadas de las unidades de producción acuícola en cuerpos de agua, a fin de evitar la contaminación y eutrofización.","s":"Acuícola"},"Acui14":{"d":"En la acuacultura con fines de producción alimenticia se prohíbe el uso de especies transgénicas.","s":"Acuícola"},"Acui15":{"d":"No se permite el desvío y/o modificación de cauces de ríos para actividades acuícolas.","s":"Acuícola"},"Acui16":{"d":"En el proceso de abandono de cualquier proyecto acuícola, se deberá efectuar una restauración del sitio consistente en el retiro de la infraestructura, el restablecimiento de los flujos de agua originales y una reforestación con especies nativas, si aplica.","s":"Acuícola"},"Acui17":{"d":"El desarrollo de actividades de acuacultura estará condicionado a que se cuenten con los títulos de concesión correspondientes en materia de agua. Así como un dictamen de factibilidad hídrica emitido por la autoridad competente.","s":"Acuícola"},"AshR01":{"d":"Los generadores de residuos sólidos deberán separarlos para su manejo diferenciado (reutilización, reciclaje o disposición final), quedando prohibida su quema a cielo abierto o su disposición en barrancas, escurrimientos, predios baldíos o tiraderos clandestinos. Los residuos comerciales y de servicios deberán recolectarse al 100% y manejarse de forma integral priorizando la valorización. Los centros de población con más de 1,500 habitantes y los proyectos habitacionales de más de 50 viviendas deberán contar con equipamiento o protocolo de gestión integral de residuos sólidos, con opciones de compostaje, acopio y transporte autorizado.","s":"Asentamientos humanos rurales"},"AshR02":{"d":"Todo proyecto deberá contar con infraestructura separada para el desalojo de agua pluvial y agua residual, favoreciendo la infiltración pluvial en obras nuevas; el drenaje de talleres mecánicos deberá contar con sistemas de retención de grasas y aceites. En zonas carentes de infraestructura de drenaje se implementarán ecotecnias (fosas sépticas comunitarias, humedales artificiales, biodigestorios) y en construcciones nuevas fuera de zonas de alto crecimiento se favorecerá la incorporación a biodigestores particulares o comunitarias. Se fomentará la captación y reúso de agua pluvial. Queda prohibida la disposición de aguas residuales no tratadas y de residuos sólidos, corrosivos, reactivos, explosivos, tóxicos o biológico-infecciosos en ríos, canales, barrancas o cualquier cuerpo de agua natural. El crecimiento de las comunidades rurales deberá mitigar sus impactos en descargas, emisiones y manejo de residuos, evitando disturbios a la fauna de los ecosistemas aledaños.","s":"Asentamientos humanos rurales"},"AshR03":{"d":"Se respetará la vegetación nativa dentro del asentamiento y en una franja de amortiguamiento de 20 metros en su periferia, permitiéndose el derribo solo con justificación técnica autorizada. Se conservarán los bosques urbanos, parques y áreas verdes naturales por sus servicios ambientales, y se promoverá la reforestación con especies nativas en áreas desprovistas de vegetación o con riesgo de erosión y deslave. Los residuos vegetales del desmonte se triturarán y reincorporarán como cobertura de áreas verdes, o se sujetarán al plan de manejo de residuos correspondiente si se desechan.","s":"Asentamientos humanos rurales"},"AshR04":{"d":"No se permitirá la construcción, ampliación o licencia de construcción de asentamientos humanos en zonas de riesgo geológico o hidrometeorológico muy alto o alto (deslizamientos, inundación) o en zonas de peligro o amenaza; en cualquier procedimiento de cambio de uso de suelo, la Coordinación Municipal de Protección Civil determinará la factibilidad según el riesgo potencial de cada caso.","s":"Asentamientos humanos rurales"},"AshR05":{"d":"Queda excluida la desecación de cuerpos de agua y la obstrucción de escurrimientos fluviales. En obras y actividades cercanas a cauces de ríos y arroyos (ribera o zona federal) se evitará la afectación del lecho, de las corrientes y de los procesos de recarga de acuíferos.","s":"Asentamientos humanos rurales"},"AshR06":{"d":"Las zonas de crecimiento existentes en suelo de uso común deberán incorporarse al régimen de Zona de Asentamiento Humano ante las autoridades pertinentes, de preferencia antes de iniciar su construcción, como requisito para acceder a los servicios municipales de agua potable y alcantarillado; la autoridad municipal realizará el análisis de factibilidad correspondiente, considerando la incorporación de ecotecnias, y podrá apoyar a los núcleos agrarios que decidan proceder con dichos trámites.","s":"Asentamientos humanos rurales"},"AshR07":{"d":"El crecimiento de las comunidades rurales deberá desarrollarse dentro de los territorios definidos para tal fin, sin superar 1.5 veces el incremento natural de su población; solo en casos excepcionales, y a una distancia no mayor a 200 metros, podrán ocuparse predios contiguos. Queda prohibido utilizar el espacio de crecimiento de las localidades rurales para fraccionamientos residenciales, unidades habitacionales, conjuntos urbanos o desarrollos inmobiliarios o campestres, y los nuevos asentamientos no deberán desarrollarse en terrenos forestales.","s":"Asentamientos humanos rurales"},"AshR08":{"d":"El crecimiento de las comunidades rurales deberá evitar impactos sobre recursos patrimoniales, históricos, arqueológicos, paleontológicos y culturales, aplicando las normas del INAH o INBAL donde existan vestigios prehispánicos o elementos de valor histórico. En caso de hallazgos durante la construcción, la obra deberá detenerse hasta que la autoridad competente determine las acciones de salvaguarda.","s":"Asentamientos humanos rurales"},"AshR09":{"d":"El alumbrado público y las nuevas construcciones dentro del asentamiento deberán incorporar medidas de ahorro de energía y fuentes alternativas (paneles solares, calentadores solares), así como sistemas de captación y conducción de agua de lluvia interconectados con plantas de tratamiento y potabilización cuando aplique.","s":"Asentamientos humanos rurales"},"AshR10":{"d":"Los establos y corrales pecuarios dentro de los asentamientos humanos deberán cumplir con las disposiciones sanitarias establecidas por las Normas Oficiales Mexicanas en materia ambiental, en particular con los aspectos de uso del agua, disposición de desechos y aguas residuales, ruido y contaminación atmosférica.","s":"Asentamientos humanos rurales"},"AshR11":{"d":"En la creación de nuevos asentamientos humanos se considerará la capacidad del área para proveer agua potable","s":"Asentamientos humanos rurales"},"AshR12":{"d":"La construcción de nuevos caminos que conecten los asentamientos humanos rurales se realizará cubriendo los requisitos ambientales, de riesgo e ingenieriles correspondientes, en particular asegurando que no aceleren procesos de erosión, afecten cuerpos de agua, hábitat de especies en riesgo y/o protección y deberán realizarse con pertinencia cultural y con una amplia participación social en todas las fases de construcción y mantenimiento","s":"Asentamientos humanos rurales"},"AshR13":{"d":"Durante la implementación de los programas de educación ambiental por parte del sector público y privado, se deberán realizar talleres participativos donde se aborden temas de rescate de áreas verdes, zonas de relevancia ambiental del municipio, elaboración de prácticas agroecológicas como compostas y huertos familiares e instalación de paneles y calentadores solares entre otros.","s":"Asentamientos humanos rurales"},"AshR14":{"d":"En el caso de existir algún derrame de aceites, grasas y combustibles, se procederá a restaurar o restablecer las condiciones físico químicas del suelo, conforme a las Normas Oficiales Mexicanas, lo cual aplicará también en las etapas de construcción, operación y abandono del sitio.","s":"Asentamientos humanos rurales"},"AshR15":{"d":"La instalación de sistemas de generación de energía solar fotovoltaica y energía eólica de pequeña escala en viviendas, definida como aquella con capacidad menor a 50 kW conforme al esquema de Generación Distribuida, se permitirá en el municipio siempre que su diseño, ubicación y operación no generen impactos negativos sobre el paisaje, los ecosistemas ni la infraestructura circundante. Los equipos deberán colocarse dentro del predio del usuario, preferentemente sobre azoteas, patios o estructuras propias, evitando desmontes, afectación de vegetación nativa, excavaciones innecesarias o alteraciones del entorno natural. En áreas de protección, preservación o zonas con valor ambiental, la instalación sólo procederá si no modifica la estructura y función ecológica del sitio, no afecta a la fauna sensible ni interfiere con corredores biológicos. Las torres o aerogeneradores domésticos deberán tener alturas reducidas, cumplir estándares de seguridad estructural, garantizar niveles mínimos de ruido y respetar distancias de seguridad respecto de viviendas vecinas. Tanto los sistemas solares como los eólicos deberán cumplir con las Normas Oficiales Mexicanas aplicables, los lineamientos de interconexión con la Comisión Federal de Electricidad y el dictamen de compatibilidad con la Unidad de Gestión Ambiental correspondiente. La autoridad municipal será responsable de verificar que el proyecto no supere la capacidad máxima permitida, que su instalación sea segura y que no represente riesgos para terceros ni para el medio ambiente. En todos los casos, la autorización estará condicionada a que la infraestructura no modifique la vocación del suelo ni contravenga los objetivos de conservación del área donde se ubique.","s":"Asentamientos humanos rurales"},"AshR16":{"d":"Se permitirá únicamente el desarrollo de fraccionamientos de baja densidad, priorizando esquemas eco-residenciales y de turismo de naturaleza.","s":"Asentamientos humanos rurales"},"AshU01":{"d":"Los residuos deberán separarse en orgánicos, inorgánicos reciclables, no reciclables y especiales, y todos los generadores dentro de la zona urbana deberán participar en la estrategia municipal de manejo, acopio y disposición final, mediante sistemas de compostaje in situ, acopio móvil y transporte autorizado. Queda prohibida la disposición de residuos y descargas en barrancas, escurrimientos, predios baldíos, minas inactivas o tiraderos a cielo abierto, así como su quema. Los desarrollos habitacionales de más de 20 viviendas deberán contar con un proyecto de manejo integral de residuos sólidos.","s":"Asentamientos humanos urbanos"},"AshU02":{"d":"Los desarrollos que incluyan clínicas, hospitales o centros médicos deberán contar con un sistema integral para el manejo y disposición de residuos biológico-infecciosos. Los sitios de confinamiento, almacenamiento, recolección, transporte y disposición final de residuos peligrosos deberán evitar la generación de focos de infección, fauna nociva y malos olores. Toda obra mayor a 1,000 m² deberá separar y acopiar sus residuos de construcción y demolición en centros de transferencia autorizados.","s":"Asentamientos humanos urbanos"},"AshU03":{"d":"Las descargas de agua residual de zonas urbanas y de actividades productivas deberán cumplir la calidad establecida en la normatividad vigente, contando con tratamiento primario y secundario suficiente previo a su descarga a cualquier cuerpo receptor. Los centros de población con más de 2,500 habitantes deberán contar con plantas de tratamiento de aguas residuales conforme a la NOM-003-SEMARNAT-1996, y los desarrollos habitacionales de más de 20 viviendas deberán contar con sistema propio de tratamiento para el uso y reúso eficiente del agua (no se permiten fosas sépticas en este tipo de desarrollos); en caso contrario, el desarrollador cubrirá los gastos de conexión a la red de drenaje más cercana.","s":"Asentamientos humanos urbanos"},"AshU04":{"d":"Todo proyecto deberá contar con infraestructura separada para el manejo de agua pluvial y agua residual; el drenaje de estacionamientos y talleres mecánicos deberá incluir sistemas de retención de grasas y aceites. Los proyectos de construcción deberán incorporar en su diseño la captación de agua de lluvia y el reúso de aguas residuales tratadas para reducir el consumo de agua de primer uso, y en zonas carentes de infraestructura de drenaje se implementarán ecotecnias (fosas sépticas comunitarias, humedales artificiales). Se fomentará la captación y uso de aguas pluviales para riego de áreas verdes, llenado de albercas y uso doméstico.","s":"Asentamientos humanos urbanos"},"AshU05":{"d":"Las construcciones nuevas, en particular en zonas de expansión y consolidación, requerirán como requisito de permiso la factibilidad de suministro de agua potable y conexión al drenaje, permitiéndose construir únicamente en polígonos con infraestructura básica instalada de agua potable, drenaje sanitario y red eléctrica. La ejecución de obras de urbanización estará condicionada a contar con los títulos de concesión de Aguas Nacionales y el dictamen de factibilidad hídrica correspondiente; cuando el predio carezca de cobertura de servicios públicos, el desarrollador será responsable de las obras de conexión a la red municipal. Para acceder a los servicios de agua potable, alcantarillado y saneamiento, las zonas de crecimiento deberán incorporarse al catastro municipal, debiendo el Ayuntamiento realizar el análisis de factibilidad correspondiente, considerando la posibilidad de ecotecnias.","s":"Asentamientos humanos urbanos"},"AshU06":{"d":"La planeación del asentamiento urbano deberá contemplar áreas verdes con una superficie mínima de 12 m² por habitante, preferentemente con especies nativas, protegiendo y preservando las zonas de conservación ecológica, parques urbanos, jardines públicos y demás bienes de uso común con cubierta vegetal. Los estacionamientos al aire libre deberán utilizar materiales permeables, reduciendo el asfalto y cemento, y destinar áreas verdes con al menos un árbol por cada cuatro cajones. No se autorizará el corte de árboles en predios o vía pública sin razón justificada conforme a la normatividad municipal aplicable.","s":"Asentamientos humanos urbanos"},"AshU07":{"d":"Los residuos vegetales generados por actividades de desmonte se triturarán y reincorporarán como cobertura de áreas verdes, o se sujetarán al plan de manejo de residuos si se desechan. La restauración de vegetación utilizará especies propias del sitio, conforme a la descripción ambiental aprobada.","s":"Asentamientos humanos urbanos"},"AshU08":{"d":"Los predios colindantes con zonas federales de corrientes de agua o barrancas se sujetarán a la legislación federal y al alineamiento de la CONAGUA, requiriendo dictamen de Protección Civil; no se otorgará permiso de construcción en Zonas Federales sin los dictámenes favorables de CONAGUA, CFE y SICT, según corresponda. En el cauce y hasta la mitad de la longitud de cada ladera solo se permitirán actividades de saneamiento y restauración, quedando prohibida cualquier otra construcción; deberá dejarse libre de construcción una distancia mínima de 10 metros a partir del lindero de la barranca o de la corona del talud.","s":"Asentamientos humanos urbanos"},"AshU09":{"d":"No se expedirán licencias de construcción en zonas de peligro o amenaza, ni se permitirá el crecimiento urbano en zonas de riesgo muy alto o alto, considerando una franja de amortiguamiento de al menos 200 metros respecto a desarrollos industriales; en zonas de riesgo alto ya urbanizadas se ejecutarán obras de mitigación. Se excluirá de cualquier proceso de urbanización a los terrenos en zonas de recarga hídrica, pendientes mayores al 15% (12% para trazado de calles), riesgo de inundación o movimiento de laderas, y áreas de conservación ecológica. Todo desarrollo urbano mayor a 5,000 m² deberá incluir un análisis de riesgo por inundación, subsidencia y sismo en su estudio técnico justificativo, e implementar barreras físicas o sistemas de drenaje pluvial conforme al Atlas de Riesgos Municipal cuando se ubique en zona de riesgo hidrometeorológico. En cualquier procedimiento de cambio de uso de suelo, la Coordinación Municipal de Protección Civil determinará la factibilidad según el riesgo potencial de cada caso.","s":"Asentamientos humanos urbanos"},"AshU10":{"d":"El crecimiento de los asentamientos urbanos deberá evitar impactos sobre recursos patrimoniales, históricos, arqueológicos, paleontológicos y culturales, aplicando las normas del INAH donde existan vestigios prehispánicos o elementos de valor histórico; los propietarios de inmuebles colindantes a un monumento que pretendan excavar, cimentar, demoler o construir deberán obtener permiso del INAH. En caso de hallazgos durante la construcción, la obra deberá detenerse hasta que la autoridad competente determine las acciones de salvaguarda.","s":"Asentamientos humanos urbanos"},"AshU11":{"d":"Los proyectos de construcción deberán desarrollarse fuera de las zonas prioritarias para la conservación de ecosistemas, biodiversidad, bienes y servicios ambientales y patrimonio histórico-arqueológico. Todo desarrollo mayor a 1 hectárea deberá incluir corredores ecológicos urbanos conectados con barrancas, cuerpos de agua y Áreas Naturales Protegidas, estableciendo una franja de amortiguamiento con vegetación nativa de al menos 10 metros lineales entre la zona urbana y dichas áreas.","s":"Asentamientos humanos urbanos"},"AshU12":{"d":"Los nuevos asentamientos humanos urbanos se ubicarán únicamente dentro de los polígonos definidos por los programas de desarrollo urbano vigentes, priorizando la ocupación de espacios intraurbanos o predios contiguos a la zona urbana (con un costo predial al menos del doble en espacios subutilizados con otro uso de suelo). No se permitirá la ocupación de zonas de crecimiento a mediano plazo hasta consolidar al menos el 50% de los espacios intraurbanos disponibles, ni las de largo plazo hasta consolidar el 70% de las de mediano plazo. Los predios estratégicos para la consolidación urbana serán priorizados para su urbanización por la autoridad, o en su defecto considerados como áreas verdes. La expansión deberá mantener al menos la densidad media del centro de población, permitiéndose solo el desarrollo resultante del crecimiento natural que conserve su morfología urbana.","s":"Asentamientos humanos urbanos"},"AshU13":{"d":"Las nuevas áreas de crecimiento urbano en suelo ejidal o de uso común deberán desincorporarse del régimen ejidal ante las autoridades pertinentes conforme a la Ley Agraria, registrándose ante el Registro Público de la Propiedad o el catastro municipal, como requisito para la emisión de licencias de construcción; para obras de urbanización se priorizarán las colonias con propiedad privada.","s":"Asentamientos humanos urbanos"},"AshU14":{"d":"Todo predio construido en su totalidad (100% COS) será acreedor a un pago por servicios ambientales establecido por el municipio e integrado en la Ley de Ingresos, según el tamaño del predio y la construcción. Los predios baldíos o suelo ocioso con abundante vegetación cuyos propietarios conserven el mayor porcentaje de coeficiente de absorción del suelo o el 100% de la vegetación arbórea existente podrán acceder a un incentivo de pago por servicios ambientales urbanos, mayor para propietarios de menores recursos.","s":"Asentamientos humanos urbanos"},"AshU15":{"d":"El alumbrado público incorporará medidas de ahorro de energía y tecnologías sustentables. En zonas carentes de infraestructura eléctrica o con déficit en el servicio se implementarán ecotecnias de generación de energía con fuentes renovables. La construcción y operación de proyectos en zonas urbanas deberá contar con un Programa de Emisiones a la Atmósfera validado por la autoridad municipal competente.","s":"Asentamientos humanos urbanos"},"AshU16":{"d":"Colocar sistemas de infiltración pluvial (cunetas verdes, pozos de absorción, pavimentos permeables) en calles nuevas o rehabilitadas con longitud superior a 100 metros","s":"Asentamientos humanos urbanos"},"AshU17":{"d":"La instalación de sistemas de generación de energía solar fotovoltaica y energía eólica de pequeña escala en viviendas, definida como aquella con capacidad menor a 50 kW conforme al esquema de Generación Distribuida, se permitirá en el municipio siempre que su diseño, ubicación y operación no generen impactos negativos sobre el paisaje, los ecosistemas ni la infraestructura circundante. Los equipos deberán colocarse dentro del predio del usuario, preferentemente sobre azoteas, patios o estructuras propias, evitando desmontes, afectación de vegetación nativa, excavaciones innecesarias o alteraciones del entorno natural. En áreas de protección, preservación o zonas con valor ambiental, la instalación sólo procederá si no modifica la estructura y función ecológica del sitio, no afecta a la fauna sensible ni interfiere con corredores biológicos. Las torres o aerogeneradores domésticos deberán tener alturas reducidas, cumplir estándares de seguridad estructural, garantizar niveles mínimos de ruido y respetar distancias de seguridad respecto de viviendas vecinas. Tanto los sistemas solares como los eólicos deberán cumplir con las Normas Oficiales Mexicanas aplicables, los lineamientos de interconexión con la Comisión Federal de Electricidad y el dictamen de compatibilidad con la Unidad de Gestión Ambiental correspondiente. La autoridad municipal será responsable de verificar que el proyecto no supere la capacidad máxima permitida, que su instalación sea segura y que no represente riesgos para terceros ni para el medio ambiente. En todos los casos, la autorización estará condicionada a que la infraestructura no modifique la vocación del suelo ni contravenga los objetivos de conservación del área donde se ubique.","s":"Asentamientos humanos urbanos"},"AshU18":{"d":"Los fraccionamientos o desarrollos habitacionales propuestos deberán brindar la superficie de donación que marca la ley en una sola área. La dirección de desarrollo urbano podrá autorizar a los desarrolladores a donar en predios dispersos, siempre y cuando estos brinden una función de recreación a los pobladores locales y en caso que no exista la necesidad de instalar equipamientos urbanos por falta de cobertura.","s":"Asentamientos humanos urbanos"},"AshU19":{"d":"Se deberán mantener pasos de libre tránsito de 5 m de ancho entre la línea de costa, playa y zona federal marítimo terrestre, y la vialidad más cercana y paralela al mar, en dirección transversal u ortogonal al eje longitudinal de la barra que delimita a la Laguna de Mitla, debiendo haber un paso de libre tránsito al menos cada 300 m","s":"Asentamientos humanos urbanos"},"Co01":{"d":"Se establecerá una franja de amortiguamiento ripario de al menos 20 metros en las riberas de corrientes y cuerpos de agua, ocupada por vegetación nativa (se exceptúan las granjas acuícolas); en general, es prioridad mantener la vegetación natural en las áreas adyacentes a cuerpos de agua, barrancas y zona federal, restaurándola cuando sea necesario. Se mantendrán inalterados los cauces y escurrimientos naturales: la modificación de cauces, flujos perennes o temporales, u obras hidráulicas de regulación requerirá permisos específicos; queda prohibida la desecación, el dragado o el relleno de cuerpos de agua y lagunas. El uso de humedales estará sujeto a autorización de impacto ambiental que garantice el mantenimiento de los procesos geohidrológicos, la calidad del agua, el flujo de nutrientes y la diversidad biológica.","s":"Conservación"},"Co02":{"d":"Las actividades que se lleven a cabo en las UGA no deberán limitar la función de corredor biológico; su efectividad se monitoreará y evaluará regularmente mediante indicadores de movilidad de la fauna, regeneración natural del bosque y presencia de especies invasoras.","s":"Conservación"},"Co03":{"d":"La restauración se realizará de preferencia con especies nativas para la recuperación y restablecimiento de las condiciones que propician la evolución y continuidad de los procesos naturales; en las áreas reforestadas solo se permitirá el uso de fertilizantes de origen orgánico.","s":"Conservación"},"Co04":{"d":"Se prohíbe la extracción, captura o comercialización de especies de flora y fauna silvestre, salvo autorización expresa para pie de cría. La extracción de ejemplares y otros recursos biológicos, así como la colecta con fines de propagación científica, solo se permitirá con fines de educación o investigación y con los permisos vigentes de la Dirección General de Vida Silvestre de la SEMARNAT, garantizando en todo caso que el aprovechamiento no comprometa los procesos de restauración ecológica.","s":"Conservación"},"Co05":{"d":"El manejo de especies exóticas solo podrá realizarse conforme a la Ley General de Vida Silvestre, a fin de prevenir el desplazamiento de poblaciones nativas, y deberá adoptar medidas de trato digno que eviten o disminuyan la tensión, sufrimiento o dolor de los ejemplares durante su aprovechamiento, traslado, exhibición o sacrificio. Los propietarios o poseedores de predios donde se realicen actividades de conservación o aprovechamiento de vida silvestre deberán darse de alta ante la SEMARNAT e incorporarse al Sistema de Unidades de Manejo para la Conservación de la Vida Silvestre (UMA).","s":"Conservación"},"Co06":{"d":"Se preservarán las especies arbóreas endémicas en peligro o amenazadas. El traslado de ejemplares, partes y derivados de especies silvestres deberá contar con los registros y autorizaciones legales conforme a la Ley General de Vida Silvestre, la Ley Federal sobre Metrología y Normalización y la Convención CITES.","s":"Conservación"},"Co07":{"d":"En los polígonos definidos como prioritarios, los predios públicos y privados estarán sujetos a programas de restauración obligatoria conforme a metas anuales del Programa de Restauración Municipal derivado del POEL (superficie mínima a restaurar, especies nativas a introducir, cobertura objetivo y control de invasoras). En predios privados dentro de estos polígonos, cualquier cambio de uso de suelo, construcción o actividad productiva deberá acompañarse de un Plan de Restauración Ecológica validado por la Dirección de Ecología, y sus resultados se incorporarán anualmente al sistema de monitoreo del POEL como condición para la emisión de autorizaciones municipales, bajo responsabilidad del COET y la Dirección de Ecología.","s":"Conservación"},"Co08":{"d":"Toda reforestación derivada de obras de mitigación, compensación o restauración ecológica requerirá un plan de seguimiento y mantenimiento de al menos tres años, con bitácora técnica que documente fechas de plantación, especies utilizadas, ubicación georreferenciada, responsables e indicadores de supervivencia y crecimiento. El incumplimiento del seguimiento post-reforestación en proyectos públicos o privados será sancionable, incluyendo la replantación con recursos propios; se promoverá además la vigilancia comunitaria y la socialización del proceso con ejidos, escuelas, brigadas y asociaciones locales.","s":"Conservación"},"Co09":{"d":"La Dirección de Ecología Municipal mantendrá actualizada una cartografía oficial de zonas de recarga hídrica (CONAGUA, INEGI, SEMARNAT), pública y disponible en el Sistema de Información Geográfico Municipal. En dichas zonas queda prohibida la autorización de actividades de alta impermeabilización del suelo (fraccionamientos cerrados o comerciales, parques industriales, vialidades pavimentadas, relleno con residuos de construcción); solo se permitirá agricultura de temporal, prácticas agroforestales o ganadería extensiva con carga no mayor a 1.0 UGM/ha, sin desmonte, quemas ni uso intensivo de agroquímicos, priorizando tecnologías de infiltración controlada y la conservación de vegetación. Toda solicitud de cambio de uso de suelo o desarrollo en estas zonas deberá presentar un Informe de Compatibilidad Hídrica (caracterización del sitio, tasa de infiltración, impacto sobre el ciclo hidrológico y medidas de mitigación) como condición para la autorización municipal.","s":"Conservación"},"Co10":{"d":"El desarrollo urbano, industrial o de infraestructura queda restringido en zonas inundables, salvo que se cuente con estudio de factibilidad hidráulica, análisis de vulnerabilidad, plan de manejo hidráulico (control de escurrimientos, drenaje pluvial, protección estructural) y autorización de CONAGUA. Se dará prioridad al uso de zonas inundables como espacios de amortiguamiento natural, humedales artificiales, áreas de retención temporal o corredores ecológicos, conservando sus drenajes naturales principales y limitando cualquier actividad que altere las dinámicas hidrológicas.","s":"Conservación"},"Co11":{"d":"Se establecerán corredores de vegetación (barreras naturales) en zonas industriales o de producción animal intensiva como medida de dispersión y mitigación de contaminantes atmosféricos, y se fomentará la transición a energías limpias en instalaciones municipales, comerciales e industriales, priorizando la sustitución de combustibles fósiles y leña.","s":"Conservación"},"Co12":{"d":"Queda estrictamente prohibido el uso de redes de arrastre, sustancias químicas, explosivos o cualquier otro método de captura que altere el lecho del río o afecte especies no objetivo. La caza únicamente podrá realizarse durante las temporadas oficialmente establecidas, quedando absolutamente prohibida en periodos de apareamiento, gestación, crianza o durante las migraciones reproductivas de aves silvestres.","s":"Conservación"},"Co13":{"d":"Cualquier actividad productiva que se realice al interior de la UGA, garantizará el mantenimiento de los bienes y servicios ambientales, así como la conservación de los ecosistemas y la biodiversidad.","s":"Conservación"},"Co14":{"d":"Para las cortas de saneamiento, si el material resultante de la corta se desrama y se abandona en la zona, deberá ser trozado en fracciones pequeñas y mezclado con el terreno para facilitar su descomposición, reduciendo el riesgo de incendios.","s":"Conservación"},"Co15":{"d":"Los residuos de la cosecha forestal (material leñoso no comercializable como ramas, fustes delgados, copas y tocones que permanecen en el terreno post-aprovechamiento) deben cumplir con las metas de carga de combustible recomendable (mínima 5 ton/ha, máxima 60 ton/ha). Para lograrlo se implementarán las siguientes acciones","s":"Conservación"},"Co16":{"d":"Evitar la circulación de vehículos y los trabajos de aprovechamiento forestal durante los meses de anidación de especies identificadas.","s":"Conservación"},"Co17":{"d":"Proteger de la ganadería los sitios de importancia crítica para especies vegetales arbustivas y herbáceas o anidación de especies de fauna que requieren dicha estructura y composición del rodal.","s":"Conservación"},"Co18":{"d":"Se llevará a cabo un diagnóstico completo que determine la factibilidad, magnitud y limitaciones de las especies de fauna silvestre, para desarrollar actividades de manejo en semi cautiverio dentro de la zona de amortiguamiento.","s":"Conservación"},"Co19":{"d":"Se fomentará la creación de un área natural protegida municipal, estatal o federal.","s":"Conservación"},"Co20":{"d":"En las unidades de protección ecológica se prohíbe la construcción o permanencia de cualquier tipo de equipamiento o infraestructura (turística, de servicios, etc.), a menos que sea para la protección de los ecosistemas.","s":"Conservación"},"Co21":{"d":"A partir de la entrada en vigor del presente POEL, en todas las Unidades de Gestión Ambiental (UGAs) que presenten pendientes superiores al 15 % y cobertura vegetal media o baja, se aplicarán las siguientes restricciones: Se prohíbe expresamente el cambio de uso de suelo para actividades urbanas, infraestructura vial o industrial en terrenos con pendientes mayores al 30 %, salvo en casos de interés público justificado y con medidas de estabilización certificadas. En pendientes entre el 15 % y el 30 %, toda intervención deberá garantizar al menos un 60 % de cobertura vegetal permanente con especies nativas. Para los predios con cobertura vegetal alterada o suelos expuestos en laderas, será obligatorio incorporar prácticas de conservación de suelo y agua, tales como terrazas, barreras vivas, zanjas de infiltración, y revegetación con especies de rápido establecimiento. Estas medidas deberán ser incluidas en el proyecto ejecutivo y supervisadas por la autoridad competente. No se autorizarán desarrollos urbanos o fraccionamientos residenciales en UGAs con riesgo alto de erosión sin la presentación de un estudio de geotecnia y vulnerabilidad, el cual deberá ser validado por el órgano técnico del COE. Este estudio deberá incluir: análisis de pendientes, escurrimientos superficiales, cobertura vegetal actual, y propuesta de medidas estructurales y vegetativas para mitigar el riesgo. Asimismo, las UGAs con riesgo de erosión deberán ser delimitadas cartográficamente en una capa temática específica del SIG Municipal, actualizada al menos cada cinco años con base en análisis de pendientes, erosión potencial y cambios de cobertura vegetal. Esta cartografía deberá ser pública y vinculante para las decisiones sobre usos del suelo y autorizaciones de obras.","s":"Conservación"},"Co22":{"d":"Los espacios que hayan sido ocupados por jagüeyes, incluyendo aquellos que actualmente se encuentran secos, deberán ser preservados exclusivamente como áreas de regulación hídrica, zonas de recarga o espacios con función ambiental. No se permitirá su uso para asentamientos humanos, infraestructura ni actividades agrícolas permanentes. Cualquier intervención en estas áreas quedará prohibida, salvo aquellas orientadas a su conservación o restauración. Esto se debe a su alto potencial de reactivación hidrológica, su función en la captación de escurrimientos y el riesgo que representan por encharcamientos, subsidencias o inundaciones locales. Antes de considerar cualquier modificación en su uso, deberá realizarse una evaluación hidrogeomorfológica especializada que determine su función ecosistémica residual y su capacidad de reactivación natural ante eventos de lluvia intensa o cambios en el régimen hídrico.","s":"Conservación"},"Co23":{"d":"Las barrancas deberán ser reconocidas como elementos territoriales estratégicos de conservación ecológica, regulación hídrica y prevención de riesgos, por lo que su gestión territorial deberá garantizar la preservación de su estructura geomorfológica, cobertura vegetal nativa y funcionalidad hidrológica. Toda intervención en barrancas —incluyendo limpieza, estabilización de taludes, rehabilitación de cauces, o instalación de infraestructura ligera— deberá sujetarse a: • Delimitación física y legal de la barranca con base en criterios hidrológicos, geotécnicos y de biodiversidad. • Restauración ecológica con especies nativas en zonas degradadas. • Conservación de un ancho mínimo de zona de protección a cada lado del cauce (por ejemplo, de 10 a 30 metros, ajustado al tipo de barranca y grado de pendiente). • Restricción de actividades que impliquen alteración de escurrimientos naturales, cortes de talud, movimientos de tierra o remoción de vegetación permanente. • Inclusión de las barrancas como corredores ecológicos, zonas de amortiguamiento o áreas verdes protegidas en los instrumentos de planeación urbana y ecológica. En zonas donde existan asentamientos colindantes o infraestructura construida, se deberán aplicar medidas de contención, reforestación, manejo de escorrentías y vigilancia comunitaria, promoviendo su incorporación como espacios públicos verdes, bajo un esquema de corresponsabilidad social y ambiental.","s":"Conservación"},"Co24":{"d":"La presencia de asentamientos humanos fuera de los límites autorizados de crecimiento urbano y en zonas no aptas según los instrumentos de planeación debido a la presencia de riesgo geológico, hidrológico, zonas de valor ambiental, escasez hídrica o fragilidad ecosistémica, sobre vías ferroviarias, barrancas y áreas naturales protegidas, deberá ser objeto de atención interinstitucional. Se promoverá su regularización únicamente cuando exista viabilidad ambiental, disponibilidad de servicios urbanos y compatibilidad con el ordenamiento ecológico y urbano. En caso de que el sitio no cumpla con estas condiciones, las autoridades competentes deberán establecer medidas de contención, no expansión, y diseñar programas de reubicación progresiva y restauración ambiental del territorio afectado. La identificación y monitoreo de estos asentamientos deberá integrarse en los sistemas de información territorial y actualizarse de manera periódica para orientar la gestión del suelo y prevenir su consolidación en zonas no aptas.","s":"Conservación"},"Co25":{"d":"Establecer pasos de fauna obligatorios en proyectos de infraestructura que crucen corredores biológicos, áreas naturales protegidas, cuerpos de agua o zonas de alta biodiversidad.","s":"Conservación"},"Co26":{"d":"La remoción de la vegetación primaria queda excluida en las UGA de Protección y Preservación.","s":"Conservación"},"Com01":{"d":"Establecer actividades comerciales únicamente en zonas con uso de suelo compatible según el POEL, dentro de los centros de población y en vialidades primarias o corredores urbanos consolidados","s":"Comercio"},"Com02":{"d":"Evitar la instalación de zonas comerciales en barrancas, zonas de recarga hídrica, áreas naturales protegidas, áreas de conservación prioritaria o suelos con aptitud agrícola alta","s":"Comercio"},"Com03":{"d":"Condicionar el desarrollo de nuevas plazas, mercados o centros comerciales a estudios de factibilidad hídrica y manejo integral de residuos","s":"Comercio"},"Com04":{"d":"Diseñar espacios comerciales con al menos 25% de superficie permeable, zonas arboladas con especies nativas y mecanismos de captación pluvial","s":"Comercio"},"Com05":{"d":"Incorporar separación de residuos sólidos en origen (orgánicos, inorgánicos reciclables y especiales) en todos los establecimientos comerciales nuevos o remodelados","s":"Comercio"},"Com06":{"d":"Instalar sistemas de eficiencia hídrica en sanitarios, lavamanos y servicios dentro de comercios con afluencia media o alta de clientes","s":"Comercio"},"Com07":{"d":"Condicionar el funcionamiento de tianguis o comercio semifijo a la existencia de un plan de recolección diaria de residuos y limpieza del espacio público","s":"Comercio"},"Com08":{"d":"Exigir licencias de funcionamiento condicionadas al cumplimiento de medidas ambientales básicas, incluyendo disposición adecuada de residuos y control de emisiones atmosféricas o acústicas","s":"Comercio"},"Com09":{"d":"Ubicar centros logísticos, almacenes y plataformas de distribución únicamente en zonas industriales o de servicios especiales delimitadas por el POEL, con conectividad directa a vialidades primarias","s":"Comercio"},"Com10":{"d":"Excluir el establecimiento de infraestructura logística en zonas habitacionales, áreas naturales protegidas, barrancas, corredores ecológicos, zonas de recarga hídrica o suelos agrícolas activos","s":"Comercio"},"Com11":{"d":"Condicionar la construcción de plataformas logísticas de más de 1 hectárea a estudios de tráfico, dispersión de contaminantes y evaluación de impactos acumulativos","s":"Comercio"},"Com12":{"d":"Diseñar los patios de maniobras, estacionamientos y zonas de carga con al menos 20% de superficie permeable o infraestructura verde (jardines de lluvia, franjas filtrantes, árboles nativos)","s":"Comercio"},"Com13":{"d":"Incorporar sistemas de captación de agua pluvial, drenaje pluvial con tratamiento primario y dispositivos de retención de hidrocarburos en zonas de tránsito pesado","s":"Comercio"},"Com14":{"d":"Separar las áreas operativas de los cuerpos de agua y pozos con una franja de amortiguamiento de al menos 30 metros con vegetación nativa o sistemas de biofiltración","s":"Comercio"},"Com15":{"d":"Evitar el uso de luminarias de alta intensidad sin control direccional, e instalar tecnologías LED con temporizador para reducir la contaminación lumínica","s":"Comercio"},"Com16":{"d":"Establecer horarios obligatorios de operación para carga y descarga de mercancías, preferentemente fuera de horas pico y evitando afectaciones a escuelas, zonas habitacionales y espacios públicos","s":"Comercio"},"Com17":{"d":"Condicionar la operación de centros logísticos al cumplimiento de un plan de manejo ambiental, incluyendo disposición de residuos sólidos, control de ruido, aguas residuales y emisiones","s":"Comercio"},"Com18":{"d":"Incluir un sistema de monitoreo semestral de calidad del aire (partículas y NOx) y ruido perimetral en plataformas de más de 10,000 m²","s":"Comercio"},"Com19":{"d":"Los corredores comerciales deberán localizarse en zonas urbanas con infraestructura instalada y capacidad de soporte. Todo proyecto debe presentar estudios de consumo de agua y energía, generación y manejo de residuos, movilidad peatonal y vehicular, así como medidas de eficiencia energética y tratamiento de aguas residuales. Se deben incluir techos verdes o superficies permeables donde sea posible, evitar el uso de materiales reflectantes o que generen efecto isla de calor, y promover el transporte público, bicicletas y rutas peatonales seguras. El diseño debe priorizar la integración urbana y la mitigación de impactos paisajísticos, acústicos y de tránsito.","s":"Comercio"},"Com20":{"d":"Cuando los corredores comerciales se propongan en zonas naturales, áreas de transición rural-urbana sin infraestructura básica, en cuerpos de agua o en suelos de conservación ecológica, deberá aplicarse un análisis integral de impacto territorial. El proyecto deberá demostrar viabilidad en términos de agua potable, drenaje sanitario, tratamiento de aguas, electricidad, movilidad y disposición final de residuos. Será indispensable el análisis de impactos acumulativos, generación de tráfico, modificación del uso del suelo, impermeabilización masiva y pérdida de hábitat. Se deberá integrar un plan de mitigación y adaptación urbana y ambiental con monitoreo a largo plazo.","s":"Comercio"},"Fom01":{"d":"Los aprovechamientos forestales maderables requerirán de un Programa de Manejo Forestal autorizado por la autoridad competente. En las Unidades de Gestión Ambiental de conservación, protección o restauración no se autorizarán nuevos aprovechamientos forestales maderables, limitándose a la continuidad de los ya autorizados previo a la publicación del presente instrumento. [Nota: armoniza la contradicción entre FM01 y FM40 detectada previamente; confirmar si la moratoria debe acotarse a estas UGA o aplicar de forma general.]","s":"Manejo forestal maderable"},"Fom02":{"d":"Como requisito para cualquier aprovechamiento forestal maderable, el beneficiario deberá ejecutar acciones de restauración que garanticen la recuperación de la biomasa y la diversidad biológica en una magnitud equiparable a la pérdida generada por el aprovechamiento.","s":"Manejo forestal maderable"},"Fom03":{"d":"Las operaciones de abastecimiento forestal se apegarán a la prescripción silvícola definida, independientemente del método de manejo utilizado; previo al marqueo de los árboles a extraer, se identificará la composición y estructura deseada de la masa residual conforme al tratamiento silvícola prescrito.","s":"Manejo forestal maderable"},"Fom04":{"d":"Se aplicará derribo direccional para minimizar daños a la vegetación residual y asegurar los valores de biodiversidad del sitio, tomando las previsiones necesarias (incluyendo dispositivos de protección o anclaje múltiple) para reducir el daño a los árboles remanentes dentro del rodal.","s":"Manejo forestal maderable"},"Fom05":{"d":"Los carriles de arrastre se cerrarán y restaurarán, cuando sea necesario, una vez finalizada la extracción. No se permitirá el uso de maquinaria pesada ni la apertura de caminos dentro de las zonas de amortiguamiento de caminos y cuerpos de agua, ni dentro de las áreas de protección de sitios de anidación, reproducción o alimentación de fauna silvestre y demás sitios de importancia para la biodiversidad. [Nota: acota el alcance de la prohibición de maquinaria (antes FM44, redactada como prohibición absoluta) a estas zonas sensibles, para no contradecir las operaciones de extracción reguladas en el resto de la categoría; confirmar si se desea una restricción más amplia.]","s":"Manejo forestal maderable"},"Fom06":{"d":"Durante la planificación del Programa de Manejo Forestal se definirán las áreas de corta concentradas, así como las áreas de valor para la protección o conservación de flora y fauna, evitando la construcción de caminos dentro de estas últimas.","s":"Manejo forestal maderable"},"Fom07":{"d":"La construcción o rehabilitación de caminos forestales respetará los cuerpos de agua y sus cauces (salvo vados), siendo de mínima afectación y eficiencia. Se controlarán los procesos erosivos derivados de la construcción de caminos y del derribo de árboles mediante obras de drenaje adecuadas, minimizando el uso de caminos en época de lluvias, particularmente en suelos arcillosos y pendientes pronunciadas. Los caminos deberán señalizarse indicando si son de paso restringido o prohibido.","s":"Manejo forestal maderable"},"Fom08":{"d":"Para la selección y delimitación de los sitios a conservar dentro del rodal se mantendrá la estructura vertical y horizontal del bosque (amplia variedad de estratos y coberturas), así como grupos de árboles representativos de la composición de especies y distribución de diámetros originales del rodal; se conservarán en pie los árboles superiores, en especial los muertos, despuntados, defectuosos o de especies no comerciales (salvo que sean fuente de plagas o enfermedades). Se aplicarán aclareos suaves y frecuentes, y cuando se utilice el método de manejo regular, se mantendrán árboles progenitores durante la corta de liberación para conservar al menos dos estratos, así como la composición de especies apropiada a la etapa de sucesión del rodal.","s":"Manejo forestal maderable"},"Fom09":{"d":"Se mantendrá el material leñoso grueso en el sitio para crear condiciones de microhábitat, conservando piezas mayores a 30 cm de diámetro y 4 m de longitud, así como entre 5 y 10 árboles muertos o con huecos en pie por hectárea (preferentemente agrupados, con diámetro mayor a 40 cm y altura mínima de 6 m, marcados con pintura permanente en un lugar visible). Durante el marqueo se preseleccionarán árboles mal conformados o dañados que, una vez caídos, brinden cobertura, alimento y protección a la fauna silvestre, así como árboles vivos, en ausencia de árboles secos en el rodal, cuando tengan diámetros mayores a 50 cm o probabilidad de formar huecos o morir en el corto plazo, estableciendo una zona de protección de dimensiones variables en torno a los árboles secos o con cavidades.","s":"Manejo forestal maderable"},"Fom10":{"d":"Los residuos generados en las operaciones forestales (cables, filtros, neumáticos, restos de herramientas, envases) se dispondrán en relleno sanitario o se reciclarán; los materiales orgánicos se separarán y, de ser posible, se composteará. Los depósitos de residuos y basura del campamento se ubicarán a una distancia mínima de 40 m de los cuerpos de agua, y los desechos de alimentos se colocarán en recipientes cerrados hasta su traslado a sitios de disposición final o reciclaje autorizados. El transporte de combustibles, aceites y lubricantes se realizará conforme a la normatividad vigente, quedando prohibida la quema de residuos a cielo abierto.","s":"Manejo forestal maderable"},"Fom11":{"d":"Las plantaciones forestales comerciales no sustituirán la vegetación natural, debiendo favorecer la diversidad biológica, la variabilidad genética y la preservación de la estructura y función de los ecosistemas naturales; en su establecimiento se conservará la vegetación original, minimizando el derribo de árboles, y contarán con brechas cortafuego en la periferia del predio. Solo se autorizarán plantaciones forestales comerciales hasta en el 30% de la superficie de la UGA, a fin de mantener la integridad funcional del ecosistema.","s":"Manejo forestal maderable"},"Fom12":{"d":"Los aprovechamientos forestales deberán garantizar la permanencia de corredores biológicos y zonas de reproducción de fauna silvestre, definiendo las áreas de vegetación forestal que no podrán aprovecharse. Las zonas sujetas a restauración ecológica (ecosistemas forestales perturbados y terrenos preferentemente forestales) se mantendrán excluidas del aprovechamiento forestal maderable hasta su restauración.","s":"Manejo forestal maderable"},"Fom13":{"d":"No se permitirán aprovechamientos forestales maderables en zonas con pendientes mayores al 45%, a fin de no incrementar la erosión del suelo; en estas áreas se conservará la vegetación forestal existente y, en su caso, se restaurará con especies nativas, implementando medidas de prevención y control de la erosión.","s":"Manejo forestal maderable"},"Fom14":{"d":"Los tocones resultado de la tala deberán ser conservados, en especial aquellos que contengan nidos o madrigueras, independientemente del tratamiento silvícola de que se trate.","s":"Manejo forestal maderable"},"Fom15":{"d":"Las medidas de prevención de incendios forestales, tales como brechas cortafuego, barreras vivas retardantes de fuego con plantas suculentas endémicas y líneas negras, quemas prescritas y controladas, deberán realizarse siempre bajo autorización y supervisión de las autoridades competentes y de la NOM-015-SEMARNAT/SAGARPA-1997 o su actualización o equivalente en su caso, además deberán garantizar el mantenimiento constante mediante técnicas de chaponeo, deshierbe y cajeteo, en coordinación con el Centro Estatal de Manejo del Fuego","s":"Manejo forestal maderable"},"Fom16":{"d":"El control y combate de plagas y enfermedades forestales debe realizarse a través de métodos mecánicos y físicos como: derribo, descortezado de árboles, enterramiento y quema de material contaminado, así como otro tipo de técnicas dependiendo de la enfermedad o plaga de que se trate, en coordinación con la Comisión Nacional Forestal (CONAFOR). El último recurso por utilizar será el uso de químicos, y el control biológico de plagas forestales necesitará ser sustentado por los estudios técnicos y científicos correspondientes.","s":"Manejo forestal maderable"},"Fom17":{"d":"Los aprovechamientos forestales deberán garantizar la protección de vegetación ribereña conforme a lo establecido en la NOM-152-SEMARNAT-2006 o su correspondiente actualización o modificación (NOM-152-SEMARNAT-2021)","s":"Manejo forestal maderable"},"FnM01":{"d":"Se permitirá la recolección de hongos, frutos, semillas, partes vegetativas y especímenes completos no maderables únicamente en temporada adecuada y con fines de autoconsumo o investigación, restringida a los dueños o poseedores de los predios donde se localicen estos recursos o, en su caso, a las comunidades que se rigen por usos y costumbres, bajo supervisión de técnicos capacitados para evitar impactos a la biodiversidad.","s":"Manejo forestal no maderable"},"FnM02":{"d":"Los aprovechamientos forestales no maderables se realizarán fuera de las zonas que se encuentren bajo restauración ecológica. Las zonas forestales donde se identifiquen recursos no maderables en estado crítico de desaparecer se considerarán también sujetas a restauración ecológica, limitando cualquier aprovechamiento que pudiera afectar su recuperación.","s":"Manejo forestal no maderable"},"FnM03":{"d":"El aprovechamiento de recursos naturales no maderables podrá desarrollarse siempre que no genere modificaciones a la estructura y funciones de los ecosistemas forestales y respete la capacidad de carga definida mediante un programa de manejo específico del recurso, bajo un esquema de Unidades de Manejo para la Conservación de la Vida Silvestre (UMA), sujetándose a estrictas medidas de control y a la autorización de la instancia competente.","s":"Manejo forestal no maderable"},"FnM04":{"d":"La extracción de productos forestales no maderables, incluidas plantas medicinales y no medicinales (usos alimenticios, rituales, ornamentales, entre otros), con fines de comercialización o de explotación intensiva, deberá desarrollarse únicamente bajo el esquema de Unidades de Manejo de Vida Silvestre (UMA); el aprovechamiento realizado fuera de este esquema se limitará al uso doméstico.","s":"Manejo forestal no maderable"},"FnM05":{"d":"Las acciones de reforestación y restauración para recuperar la pérdida de selvas, bosques y terrenos incendiados o degradados se realizarán preferentemente en terrenos forestales, utilizando vegetación nativa y, cuando sea pertinente, plantaciones multipropósito o sistemas productivos alternos como la apicultura; los productores desarrollarán un programa de restauración participativo a corto, mediano y largo plazo, estableciendo áreas de recuperación que mitiguen los impactos del aprovechamiento y protejan a las especies de flora y fauna silvestre.","s":"Manejo forestal no maderable"},"FnM06":{"d":"El aprovechamiento de suelos forestales se llevará a cabo manteniendo su integridad física y capacidad productiva, controlando los procesos de erosión y degradación; en áreas con pendientes mayores al 45% se conservará o, en su caso, se restaurará la vegetación nativa, quedando excluidas de cualquier aprovechamiento forestal no maderable.","s":"Manejo forestal no maderable"},"FnM07":{"d":"Para el aprovechamiento de hongos se permitirá únicamente la extracción del 30% de la población total del sitio de colecta y se recolectarán únicamente individuos maduros mayores a 7 cm de longitud.","s":"Manejo forestal no maderable"},"FnM08":{"d":"La extracción de tierra de monte o de hoja se realizará en zonas que presenten bajo riesgo de erosión y el ejido otorgara los persmisos de colecta.","s":"Manejo forestal no maderable"},"FnM09":{"d":"Las organizaciones productivas legalmente constituidas llevarán a cabo el proceso para la obtención de certificaciones que garanticen el manejo sustentable de los bosques, a través del Sistema de Certificación Forestal Mexicano.","s":"Manejo forestal no maderable"},"FnM10":{"d":"La habilitación de infraestructura para la extracción de la producción forestal maderable y no maderable se realizará exclusivamente en zonas desprovistas de vegetación de tal forma que la misma no afecte de manera significativa el ecosistema.","s":"Manejo forestal no maderable"},"FnM11":{"d":"Las unidades de producción forestal no maderable deberán contar con un programa de manejo autorizado, el cual será evaluado cada tres años.","s":"Manejo forestal no maderable"},"FnM12":{"d":"La vegetación forestal ribereña será conservada respetando su distribución natural en la orilla de los cuerpos de agua; cuando presente signos de deterioro, su recuperación se realizará mediante reforestación con especies nativas y manejo de suelo para lograr su estabilidad.","s":"Manejo forestal no maderable"},"Pex01":{"d":"Ejercer ganadería extensiva únicamente en zonas con vocación agropecuaria delimitadas en el POEL, excluyendo áreas naturales protegidas, zonas de recarga hídrica, pendientes mayores a 15% y sitios con vegetación nativa en proceso de restauración","s":"Ganadería extensiva"},"Pex02":{"d":"Delimitar zonas de pastoreo extensivo fuera de cuerpos de agua superficiales y establecer franjas de amortiguamiento de al menos 20 metros con cobertura vegetal permanente","s":"Ganadería extensiva"},"Pex03":{"d":"Evitar el uso ganadero de terrenos en proceso de erosión activa o con pérdida de capa vegetal, salvo que se apliquen medidas de rehabilitación del suelo","s":"Ganadería extensiva"},"Pex04":{"d":"Establecer cargas ganaderas compatibles con la capacidad de carga de los pastizales, mediante rotación de potreros, descanso de parcelas y uso de bancos forrajeros","s":"Ganadería extensiva"},"Pex05":{"d":"Evitar el sobrepastoreo en laderas, planicies aluviales y zonas de recarga pluvial, mediante sistemas de pastoreo controlado, cercado y calendarios técnicos","s":"Ganadería extensiva"},"Pex06":{"d":"Instalar bebederos artificiales alejados de cauces y humedales, con sistemas de almacenamiento y captación de agua de lluvia para reducir la presión sobre manantiales y arroyos","s":"Ganadería extensiva"},"Pex07":{"d":"Conservar los árboles aislados, cercas vivas y relictos de vegetación nativa dentro de potreros, como elementos de conectividad biológica y refugio de fauna","s":"Ganadería extensiva"},"Pex08":{"d":"Evitar el uso de fuego como método de renovación de pasto, sustituyéndolo por prácticas mecánicas, pastoreo dirigido o siembra de forrajeras tolerantes a sequía","s":"Ganadería extensiva"},"Pex09":{"d":"Reforestar zonas compactadas, degradadas o con pérdida de cobertura vegetal mediante especies nativas adaptadas al sistema silvopastoril","s":"Ganadería extensiva"},"Pex10":{"d":"Ajustar el número de animales por unidad de superficie en función de las condiciones climáticas estacionales y la disponibilidad de forraje, especialmente durante años secos","s":"Ganadería extensiva"},"Pex11":{"d":"Separar y confinar animales enfermos o en tratamiento veterinario en instalaciones alejadas de cauces, pozos o cuerpos de agua","s":"Ganadería extensiva"},"Pex12":{"d":"Establecer un programa de disposición sanitaria de excretas y aguas de lavado de corrales o instalaciones pecuarias, evitando su descarga directa a cuerpos de agua superficiales o subterráneos, conforme a la NOM-001-SEMARNAT-1996.","s":"Ganadería extensiva"},"Pex13":{"d":"No se permitirá la quema de vegetación para el fomento del crecimiento de renuevos para el consumo del ganado. Aquellas zonas incendiadas se considerarán como espacios sujetos a restauración ecológica, que no podrán ser utilizados con fines pecuarios.","s":"Ganadería extensiva"},"Pex14":{"d":"No se permitirá el cambio de uso del suelo en terrenos forestales para destinarlo o inducirlos a favor de las actividades pecuarias","s":"Ganadería extensiva"},"Pex15":{"d":"Se deberá llevar a cabo una rotación de potreros naturales por cada tipo de ecosistema o praderas establecidas determinando la carga animal adecuada con base en la superficie del agostadero, sus recursos vegetales existentes, los cambios climatológicos y los hábitos de pastoreo de la raza o especie utilizada, mediante los métodos determinados por la Comisión Técnica para el Coeficiente de Agostadero (COTECOCA).","s":"Ganadería extensiva"},"Pex16":{"d":"No se permitirá el pastoreo del ganado en pendientes mayores a 30 %, bordes de cauce y cuerpos de agua.","s":"Ganadería extensiva"},"Pex17":{"d":"Las áreas con vegetación arbustiva y pastizales con pendientes entre 20 % y 30 % sólo podrán utilizarse para el pastoreo en épocas de lluvias.","s":"Ganadería extensiva"},"Pin01":{"d":"Ubicar unidades de producción animal intensiva únicamente en zonas agropecuarias delimitadas en el POEL, fuera de asentamientos humanos, barrancas, áreas de recarga hídrica, humedales y corredores ecológicos","s":"Ganadería intensiva"},"Pin02":{"d":"Establecer una distancia mínima de 500 metros entre las unidades de ganadería intensiva y cuerpos de agua superficiales o pozos, salvo que se implementen barreras físicas y sistemas de contención de lixiviados","s":"Ganadería intensiva"},"Pin03":{"d":"Evitar la instalación de nuevas unidades en zonas con pendientes superiores a 8%, suelos con alta permeabilidad o evidencias de subsidencia o contaminación del acuífero","s":"Ganadería intensiva"},"Pin04":{"d":"Instalar sistemas de biodigestión, lagunas de oxidación o tratamiento anaerobio para el manejo de excretas en todas las unidades con más de 100 animales en confinamiento","s":"Ganadería intensiva"},"Pin05":{"d":"Evitar la descarga de aguas residuales sin tratamiento a cauces, drenes agrícolas o jagüeyes, y mantener un monitoreo semestral de calidad del agua en pozos cercanos a la unidad.","s":"Ganadería intensiva"},"Pin06":{"d":"Controlar las emisiones de gases y olores mediante ventilación cruzada, cubiertas flotantes sobre biodigestores o aspersión de neutralizantes biológicos","s":"Ganadería intensiva"},"Pin07":{"d":"Diseñar corrales, galpones y patios de alimentación con sistemas de recolección de lixiviados y canaletas que eviten la infiltración al suelo","s":"Ganadería intensiva"},"Pin08":{"d":"Establecer unidades de compostaje o lombricultura para reutilizar estiércol tratado como fertilizante agrícola en suelos con aptitud comprobada","s":"Ganadería intensiva"},"Pin09":{"d":"Mantener bitácoras de ingreso de alimentos, uso de medicamentos veterinarios, disposición de residuos y generación de aguas residuales, disponibles para revisión municipal","s":"Ganadería intensiva"},"Pin10":{"d":"Implementar planes de bioseguridad y campañas de vacunación validadas por la autoridad sanitaria, como condición para mantener el registro y autorización de operación","s":"Ganadería intensiva"},"Pin11":{"d":"Proteger las instalaciones de eventos extremos (lluvias intensas, granizadas, vientos) mediante estructuras resistentes, canales pluviales y almacenamiento de agua pluvial","s":"Ganadería intensiva"},"Pin12":{"d":"Establecer programas de monitoreo comunitario y participación social en el seguimiento de impactos sobre el agua, aire y salud pública en el entorno de las granjas","s":"Ganadería intensiva"},"Pin13":{"d":"Localizar las unidades de producción porcícola únicamente en zonas agropecuarias delimitadas en el POEL, a una distancia mínima de 1,000 metros de asentamientos humanos, escuelas, hospitales, cuerpos de agua y zonas de conservación ecológica.","s":"Ganadería intensiva"},"Pin14":{"d":"Prohibir el uso de fosas sépticas sin recubrimiento impermeable o sin sistema de tratamiento primario, especialmente en zonas con alta permeabilidad o cercanas a fuentes de agua subterránea.","s":"Ganadería intensiva"},"Pin15":{"d":"Establecer sistemas de tratamiento de residuos líquidos mediante biodigestores, lagunas anaerobias o filtros verdes, dimensionados según la carga orgánica generada y con mantenimiento periódico obligatorio.","s":"Ganadería intensiva"},"Pin16":{"d":"Prohibir la descarga directa de efluentes no tratados a ríos, jagüeyes, drenes agrícolas o suelo desnudo. Se deberá contar con análisis de laboratorio semestrales de calidad del agua (NOM-001-SEMARNAT-2021).","s":"Ganadería intensiva"},"Pin17":{"d":"Separar y almacenar cadáveres de animales y residuos biológicos en instalaciones cerradas, ventiladas y con piso impermeable, asegurando su disposición en centros autorizados por la SEMARNAT o la SAGARPA.","s":"Ganadería intensiva"},"Pin18":{"d":"Todos los establos, ranchos y granjas deberán dar un manejo adecuado a sus residuos sólidos de acuerdo a las disposiciones de la autoridad competente.","s":"Ganadería intensiva"},"Pin19":{"d":"Los residuos biológico-infecciosos resultado de la matanza y procesamiento de productos o subproductos del ganado, deberán ser sometidos a sistemas de tratamiento y depositados en sitios de disposición final adecuados.","s":"Ganadería intensiva"},"Pin20":{"d":"Los baños garrapaticidas solamente podrán ser ubicados en zonas planas sobre superficies impermeables y alejadas de corrientes superficiales al menos 1 km.","s":"Ganadería intensiva"},"Pin21":{"d":"Se deberán utilizar piensos y forrajes mejorados que reduzcan la producción de metano en los procesos de fermentación entérica del ganado, adicionados con nitratos, ionóforos y compuestos bioactivos de plantas.","s":"Ganadería intensiva"},"Pin22":{"d":"El desarrollo de actividades pecuarias intensivas estará condicionado a que se cuenten con los títulos de concesión correspondientes en materia de agua.","s":"Ganadería intensiva"},"Pin23":{"d":"La ganadería intensiva se encontrará limitada a las unidades de producción existentes, las cuales deberán ser reubicadas de las zonas de reserva o crecimiento urbano, previo a la instalación de vivienda, equipamiento y servicios urbanos.","s":"Ganadería intensiva"},"Pin24":{"d":"Las unidades de producción o procesamiento de ganado, así como productos derivados deberán ser reubicadas fuera de las zonas de asentamientos humanos, en no más de 2 años posteriores a la publicación del presente instrumento. Aquellas unidades de producción que no se reubiquen en el tiempo establecido, no podrán contar con licencias de funcionamiento, y serán susceptibles de las sanciones ambientales que fije la autoridad competente.","s":"Ganadería intensiva"},"Pin25":{"d":"No se permitirá la matanza de ganado al interior de zonas urbanas. La matanza, así como disposición inadecuada de residuos derivados y de aguas rojas será sancionada de acuerdo a las sanciones ambientales que fije la autoridad competente.","s":"Ganadería intensiva"},"InL01":{"d":"Establecer actividades industriales de bajo impacto únicamente en zonas con uso de suelo industrial o mixto definido por el POEL, fuera de áreas naturales protegidas, zonas de recarga hídrica o corredores ecológicos","s":"Industria de bajo impacto o industria ligera"},"InL02":{"d":"Localizar la industria ligera en polígonos con acceso a infraestructura básica (agua, drenaje, electricidad) y conectividad vial, sin afectar suelos agrícolas activos ni áreas de conservación prioritaria","s":"Industria de bajo impacto o industria ligera"},"InL03":{"d":"Evitar la instalación de industrias de bajo impacto en zonas con pendientes mayores a 12%, suelos inestables o zonas con riesgo hidrometeorológico, salvo que cuenten con estudios de factibilidad y medidas de mitigación aprobadas","s":"Industria de bajo impacto o industria ligera"},"InL04":{"d":"Diseñar las instalaciones industriales con superficies permeables en al menos 30% del predio, integrando vegetación nativa en camellones, franjas perimetrales y zonas de acceso","s":"Industria de bajo impacto o industria ligera"},"InL05":{"d":"Instalar sistemas de captación pluvial, tratamiento primario de aguas residuales y mecanismos de separación de residuos en todo establecimiento nuevo o en ampliaciones superiores a 500 m²","s":"Industria de bajo impacto o industria ligera"},"InL06":{"d":"Minimizar el uso de energía mediante la integración de sistemas pasivos de iluminación y ventilación, y priorizar el uso de energías renovables para el funcionamiento general de la planta","s":"Industria de bajo impacto o industria ligera"},"InL07":{"d":"Evitar la emisión directa de contaminantes atmosféricos mediante el uso de tecnologías limpias, sistemas de filtración o encapsulado de procesos que generen polvo o gases","s":"Industria de bajo impacto o industria ligera"},"InL08":{"d":"Establecer rutas de transporte de carga que eviten el paso por zonas habitacionales o escolares, y limitar las operaciones de carga y descarga a horarios definidos por el reglamento municipal","s":"Industria de bajo impacto o industria ligera"},"InL09":{"d":"Presentar un informe técnico ambiental que incluya el tipo de proceso, insumos, residuos generados, consumo de agua y energía, y un plan de manejo ambiental específico","s":"Industria de bajo impacto o industria ligera"},"InL10":{"d":"Registrar trimestralmente ante la autoridad municipal ambiental los volúmenes de producción, consumo de recursos y disposición de residuos, como condición para mantener la licencia de funcionamiento","s":"Industria de bajo impacto o industria ligera"},"InL11":{"d":"Vincular las instalaciones industriales a procesos comunitarios de reciclaje, reúso o compostaje, priorizando la contratación de personal local y el abastecimiento de insumos dentro del municipio","s":"Industria de bajo impacto o industria ligera"},"InL12":{"d":"Controlar los olores ofensivos derivados de actividades mediante aspersión de neutralizantes, biofiltros o confinamiento controlado, conforme a la NOM-043-SEMARNAT-1993.","s":"Industria de bajo impacto o industria ligera"},"InL13":{"d":"Las obras relacionadas con proyectos con industria ligera deberán desarrollarse evitando las zonas identificadas como de riesgo muy alto y alto","s":"Industria de bajo impacto o industria ligera"},"InL14":{"d":"Se aplicarán medidas de prevención y atención de emergencias derivadas de accidentes relacionados con el almacenamiento de combustibles, así como por peligros riesgos naturales (sismos, inundaciones, etc.). Se instrumentará un plan de emergencias para la evacuación de la población en caso de accidentes, así como planes de emergencias en respuesta a derrames o explosiones de combustibles y solventes, de acuerdo con las Normas Oficiales Mexicanas.","s":"Industria de bajo impacto o industria ligera"},"InL15":{"d":"Las actividades industriales estarán restringidas a la instalación de talleres o pequeñas agroindustrias comunitarias para la transformación de productos locales y regionales.","s":"Industria de bajo impacto o industria ligera"},"InL16":{"d":"No se permitirá la instalación al interior de centros de población de industrias que generen residuos peligrosos o contaminantes que afecten la salud de la población.","s":"Industria de bajo impacto o industria ligera"},"InL17":{"d":"Las actividades industriales se realizarán en instalaciones de bajo impacto ambiental y se limitarán a las clasificadas como industria ligera que demanden bajos volúmenes de agua y generen una mínima contaminación al aire y agua.","s":"Industria de bajo impacto o industria ligera"},"InL18":{"d":"Las actividades industriales que se desarrollen en zonas urbanas y urbanizables deberán contar preferentemente con alguna certificación que demuestre un buen desempeño ambiental, emitido por la autoridad local competente.","s":"Industria de bajo impacto o industria ligera"},"InL19":{"d":"No se permitirá la operación de vehículos automotores de seis o más llantas, destinados al transporte de mercancías con peso bruto vehicular mayor de cuatro toneladas, en industrias ligeras dentro de la zona urbana.","s":"Industria de bajo impacto o industria ligera"},"InL20":{"d":"Las actividades industriales deberán prevenir y reducir la generación de residuos dando un manejo integral adecuado y privilegiando la valorización sobre su disposición final.","s":"Industria de bajo impacto o industria ligera"},"InL21":{"d":"Las actividades industriales deberán contar con sistemas de tratamiento de sus aguas residuales previo a su descarga a la red de drenaje municipal, atendiendo a lo dispuesto por la normatividad aplicable en la materia.","s":"Industria de bajo impacto o industria ligera"},"InL22":{"d":"Las actividades industriales que requieran de un alto consumo de agua deberán contar con sistemas de captación de agua de lluvia que suministren al menos el 25 % del agua requerida, así como un dictamen de factibilidad hídrica emitido por la autoridad competente.","s":"Industria de bajo impacto o industria ligera"},"Iaz01":{"d":"Las obras como bordos, humedales artificiales, canales de distribución y sistemas de captación deberán diseñarse considerando la capacidad de retención natural del terreno, su compatibilidad con los escurrimientos estacionales y su integración al régimen hidrológico local. Será necesario establecer drenajes de alivio, revegetación de márgenes con especies nativas y control del azolve. Además, deberá justificarse la no afectación de cuerpos de agua permanentes o flujos naturales y su contribución a la recarga hídrica.","s":"Infraestructura azul"},"Iaz02":{"d":"Las presas de almacenamiento, trasvases, canalizaciones rígidas o bordos construidos en cauces permanentes deberán ser evaluados bajo un enfoque de manejo integral de cuenca, con estudios de impacto acumulativo, análisis hidrogeológico, modelación de escenarios hídricos y revisión de alternativas menos invasivas. La autorización dependerá de su capacidad para mantener el equilibrio ecológico y funcional del ecosistema acuático, e incluirá medidas de restauración de hábitats, reubicación de actividades afectadas y seguimiento comunitario del uso del agua.","s":"Infraestructura azul"},"Iaz03":{"d":"Las obras artificiales de infiltración como zanjas, pozos de absorción y subsistemas de almacenamiento deberán localizarse en suelos con capacidad de retención adecuada y fuera de zonas con riesgo de contaminación del subsuelo. Será necesario presentar estudios hidrogeológicos que respalden su eficacia y seguridad, e incluir filtros de pretratamiento para evitar la infiltración de contaminantes. Su diseño deberá evitar interferencias con cuerpos de agua superficiales y respetar los procesos naturales de recarga.","s":"Infraestructura azul"},"Iaz04":{"d":"Las excavaciones profundas destinadas a infiltración o recarga artificial en zonas con suelos contaminados, alto nivel freático o cercanía a fuentes de riesgo deberán someterse a estudios detallados de factibilidad hidrogeológica y de calidad del agua. Deberán contemplar barreras naturales o artificiales, sistemas de monitoreo permanente y protocolos de mantenimiento. Además, su localización deberá coordinarse con los instrumentos de ordenamiento ecológico para asegurar su compatibilidad funcional con el territorio.","s":"Infraestructura azul"},"Iaz05":{"d":"Los bordos de tierra compactada para captación de agua pluvial deberán ubicarse fuera de cauces permanentes, humedales, barrancas o zonas de recarga hídrica prioritaria. Su diseño deberá incluir taludes estables, vertedores de seguridad y sistemas de protección contra erosión. Deberán ser evaluados en relación con la capacidad de infiltración del sitio, y su operación debe contemplar mantenimiento anual y mecanismos de drenaje de alivio para evitar desbordamientos.","s":"Infraestructura azul"},"Iaz06":{"d":"Los bordos de gran capacidad o aquellos construidos en cauces naturales o zonas de alta pendiente deberán someterse a una evaluación técnica específica en términos de estabilidad estructural, riesgo hidrológico y posible afectación a ecosistemas acuáticos o zonas agrícolas aguas abajo. Será obligatorio incorporar infraestructura de descarga controlada, medidas de restauración ambiental, seguimiento técnico postconstructivo y coordinación con los instrumentos de ordenamiento ecológico local.","s":"Infraestructura azul"},"Iaz07":{"d":"Los bordos deberán de tener una profundidad adecuada que evite láminas de agua someras por periodos prolongados.","s":"Infraestructura azul"},"Iaz08":{"d":"Se establecerá un programa de mantenimiento periódico que incluya desazolve, monitoreo de calidad del agua y control de materia orgánica.","s":"Infraestructura azul"},"Iaz09":{"d":"Las cortinas vegetales de los bordos deberán conformarse con especies nativas, evitando el uso de especies invasoras y aquellas que propicien la proliferación de vectores biológicos.","s":"Infraestructura azul"},"Iaz10":{"d":"Evitar descargas residuales o conexiones que mantengan el cuerpo de agua de forma permanente, cuando su presencia continua no sea necesaria para su función ecológica, hidráulica o productiva.","s":"Infraestructura azul"},"Iaz11":{"d":"Incorporar estrategias de tratamiento primario o natural del agua, como humedales artificiales, si es compatible con el uso del suelo.","s":"Infraestructura azul"},"Iaz12":{"d":"Cuando las lagunas de regulación se propongan en zonas de alta densidad poblacional, con antecedentes de enfermedades transmitidas por vectores, en terrenos con alta carga orgánica o cercanas a cuerpos de agua naturales, se deberá presentar un estudio detallado de riesgo sanitario y ambiental. Se exigirá un diseño que garantice funcionalidad hidrológica sin generar láminas de agua estancadas, así como un plan integral de gestión post-construcción con indicadores de calidad del agua y control de vectores.","s":"Infraestructura azul"},"Iaz13":{"d":"Las lagunas de regulación construidas en zonas periurbanas o agrícolas deberán integrarse a los sistemas de manejo de escurrimientos pluviales mediante diseños que respeten la topografía natural, consideren el uso de vegetación nativa en taludes y bordes, y contemplen medidas de seguridad para evitar erosión o estancamiento de aguas. Será necesario presentar estudios hidrológicos y de capacidad de retención que demuestren su funcionalidad sin generar afectación a los cauces existentes ni a cuerpos de agua conectados.","s":"Infraestructura azul"},"Iaz14":{"d":"Las lagunas de regulación de gran escala que impliquen modificación sustancial del relieve, interceptación de cauces o afectación a zonas con valor ecológico o social deberán contar con una evaluación ambiental específica e incluir un plan de manejo integral que contemple: revegetación, control de mosquitos, monitoreo de calidad del agua, medidas de seguridad estructural y mecanismos de comunicación con las comunidades locales.","s":"Infraestructura azul"},"lazr01":{"d":"Las obras como bordos, humedales artificiales, canales de distribución y sistemas de captación deberán diseñarse considerando la capacidad de retención natural del terreno, su compatibilidad con los escurrimientos estacionales y su integración al régimen hidrológico local. Será necesario establecer drenajes de alivio, revegetación de márgenes con especies nativas y control del azolve. Además, deberá justificarse la no afectación de cuerpos de agua permanentes o flujos naturales y su contribución a la recarga hídrica.","s":"Infraestructura azul restringida"},"Ivd01":{"d":"Cuando se requiera modificar parcialmente el terreno para implementar sistemas como jardines de lluvia, zanjas vegetadas o drenaje urbano sustentable (SUDS), deberá garantizarse la integración ecológica mediante el uso de especies nativas, respeto a los flujos hidrológicos superficiales y compatibilidad con la conectividad ecológica local. Será indispensable contar con un diseño técnico que justifique su funcionalidad ambiental, su mantenimiento y su compatibilidad con los usos del suelo colindantes.","s":"Infraestructura verde"},"Ivd02":{"d":"Proyectos que se presenten como infraestructura verde pero que incluyan urbanización encubierta, introducción de especies exóticas o transformación del suelo natural deberán ser evaluados de forma integral para garantizar que los beneficios ambientales no se vean superados por sus impactos. Deberán incluir una justificación ecológica sólida, un diseño que asegure funcionalidad ecosistémica y medidas de seguimiento que eviten su desnaturalización con el tiempo.","s":"Infraestructura verde"},"Ivi01":{"d":"La infraestructura vial existente deberá ser objeto de evaluación periódica para su adecuación ambiental, funcional y de seguridad, especialmente cuando atraviese áreas de valor ecológico, zonas de recarga hídrica, barrancas, laderas inestables, cuerpos de agua, o comunidades con población vulnerable","s":"Infraestructura vial"},"Ivi02":{"d":"Las actividades de mantenimiento, ampliación o rehabilitación deberán condicionarse a: • El uso de materiales que reduzcan el impacto ecológico y climático (p. ej. pavimentos permeables, vegetación de taludes). • El rediseño de drenajes y cunetas para evitar erosión y escurrimientos contaminantes. • La incorporación de pasos de fauna, señalización ambiental y barreras de contención en zonas sensibles. • El respeto a los anchos de derecho de vía establecidos en el Reglamento de Vialidad o Normas Técnicas Estatales. • La adopción de medidas de movilidad segura y accesible para peatones, ciclistas y transporte público, especialmente en zonas urbanas o escolares.","s":"Infraestructura vial"},"Ivi03":{"d":"Cuando el trazo original de la vía genere impactos graves o ponga en riesgo a comunidades o ecosistemas, se podrán considerar modificaciones de alineamiento o redireccionamiento del flujo vehicular, en coordinación con las autoridades responsables.","s":"Infraestructura vial"},"Ivi04":{"d":"Toda nueva infraestructura vial deberá ser diseñada con base en estudios integrales de impacto ambiental, impacto social, riesgo natural y conectividad ecológica, que justifiquen su trazo, jerarquía funcional, y compatibilidad con los instrumentos de ordenamiento ecológico y desarrollo urbano.","s":"Infraestructura vial"},"Ivi05":{"d":"Los proyectos viales deberán: • Evitar trazos en zonas de alta pendiente, barrancas, cauces, humedales, zonas de recarga hídrica, o áreas de conservación ecológica. • Incluir medidas de mitigación como pasos de fauna, drenajes sostenibles, revegetación de taludes, y control de erosión. • Garantizar que su trazo no induzca la fragmentación del territorio ni la apertura de nuevos frentes de urbanización no planificados. • Ser evaluados en cuanto a su efecto sobre los usos del suelo y no generar contradicciones con los usos establecidos en el ordenamiento ecológico o el PMDU. • Incluir una valoración de alternativas de menor impacto territorial, incluyendo rutas preexistentes o mejoras a caminos actuales.","s":"Infraestructura vial"},"Ivi06":{"d":"Los caminos rurales mejorados con maquinaria o revestimientos ligeros deberán planearse siguiendo curvas de nivel, evitando zonas de recarga hídrica, barrancas, humedales y pendientes mayores al 30%. Su diseño deberá incluir cunetas, pasos de agua, medidas contra la erosión y revegetación de taludes. Será necesario presentar un análisis de conectividad y justificar que la vialidad responde a necesidades comunitarias prioritarias y no induce urbanización no planificada.","s":"Infraestructura vial"},"Ivi07":{"d":"Los caminos rurales que impliquen desmonte de vegetación primaria, apertura de brechas en zonas de conservación, pendientes elevadas o afectación a cuerpos de agua deberán contar con una evaluación ambiental integral. Se requerirá justificar su funcionalidad regional, demostrar que no existen alternativas menos impactantes, e incorporar infraestructura verde, revegetación, control de escurrimientos y monitoreo postconstructivo. Además, deberá evitarse la apertura de acceso a zonas sin planificación territorial aprobada.","s":"Infraestructura vial"},"Ivi08":{"d":"La instalación, modernización o mantenimiento de infraestructura carretera de doble carril pavimentada, clasificada como de impacto medio, solo será permitida en UGAs cuya vocación territorial sea compatible con infraestructura de conexión rural o regional, siempre que no se afecten directamente ecosistemas sensibles, corredores biológicos, cuerpos de agua, ni zonas de alta pendiente o valor ambiental prioritario. Estas carreteras deberán respetar una franja de amortiguamiento ecológico mínima de 10 metros por lado, revegetada con especies nativas, que contribuya a reducir la fragmentación del hábitat, mitigar la escorrentía y mantener la conectividad ecológica del paisaje. Se fomentará el uso de materiales permeables para cunetas, el control de escurrimientos mediante zanjas de infiltración y obras de drenaje sostenible, así como la incorporación de pasos de fauna en tramos donde se identifique tránsito biológico relevante.","s":"Infraestructura vial"},"Ivi09":{"d":"No se permitirá su trazado sobre pendientes mayores al 15% sin justificación técnica ni medidas especiales de estabilización, ni su ampliación en zonas de protección, preservación o restauración ecológica. Toda intervención deberá estar sujeta, en su caso, a una evaluación de impacto ambiental simplificada o específica, conforme al marco normativo aplicable, y a un plan de manejo ambiental que contemple acciones de mitigación y restauración.","s":"Infraestructura vial"},"Ivi10":{"d":"Se promoverá que el diseño de estas carreteras contemple velocidades controladas y señalización ambiental, especialmente en zonas con presencia de fauna silvestre, centros de población o áreas de uso turístico o agroecológico. Asimismo, los proyectos deberán incorporar mecanismos de consulta y participación comunitaria en la definición de tramos, accesos y medidas de protección ambiental, priorizando el beneficio local y la compatibilidad territorial.","s":"Infraestructura vial"},"Ivi11":{"d":"La ampliación de esta infraestructura en zonas clasificadas como de conservación, preservación o alta fragilidad ecológica, incluyendo corredores biológicos, cabeceras de cuenca, manglares y humedales, se tiene que justificar técnicamente como una necesidad estratégica y se implementen medidas de compensación ambiental equivalentes o superiores a los impactos generados.","s":"Infraestructura vial"},"Ivi12":{"d":"Toda intervención que implique ampliación, rectificación de trazo, mantenimiento mayor o modernización de la vía deberá contar con una Manifestación de Impacto Ambiental (MIA), que considere un análisis de alternativas y contemple medidas específicas de mitigación y restauración ambiental, conforme a la legislación vigente.","s":"Infraestructura vial"},"Ivi13":{"d":"En las UGAs donde esta infraestructura ya se encuentra instalada, deberán ejecutarse acciones de restauración y compensación ecológica, como la revegetación de taludes y camellones con especies nativas, la instalación de pasos de fauna (aéreos o subterráneos) en zonas de tránsito biológico, la construcción de barreras acústicas y visuales en tramos cercanos a centros de población, y la restauración de superficies equivalentes al menos al 150% del área impactada por obras de ampliación.","s":"Infraestructura vial"},"Ivi14":{"d":"Todo tramo carretero deberá contar con sistemas adecuados para el control de escurrimientos y la prevención de contaminación difusa, mediante zanjas de infiltración, drenaje sustentable y tanques de sedimentación que eviten la descarga directa de contaminantes a cuerpos de agua, suelos agrícolas o zonas de recarga hídrica","s":"Infraestructura vial"},"Ivi15":{"d":"No se permitirá la apertura de nuevos accesos, caminos secundarios o entronques no planificados desde estas vías hacia zonas rurales de alta sensibilidad ambiental, particularmente aquellas que presenten pendientes naturales mayores al 30%, vegetación bien conservada o cuerpos de agua superficiales.","s":"Infraestructura vial"},"Ivi16":{"d":"La entidad responsable de la carretera deberá implementar un programa de monitoreo ambiental permanente, que incluya indicadores sobre calidad del aire, ruido, escurrimientos contaminantes, fragmentación del hábitat y estado del arbolado, así como acciones correctivas cuando se detecten impactos significativos o incumplimientos de las medidas ambientales autorizadas.","s":"Infraestructura vial"},"Ivi17":{"d":"Las comunidades locales deberán participar activamente en el diseño, seguimiento y evaluación de las medidas de mitigación, especialmente en los tramos que atraviesan sus territorios, a través de mecanismos de participación social informada que aseguren la incorporación de sus conocimientos, preocupaciones y propuestas en los planes de mantenimiento ambiental de la infraestructura carretera.","s":"Infraestructura vial"},"Imi01":{"d":"Los miradores fijos que incluyan servicios básicos (baños secos, áreas de descanso, estacionamientos) deberán ubicarse fuera de zonas con alta fragilidad ecológica, evitando pendientes pronunciadas, áreas de recarga hídrica, corredores biológicos o sitios con especies en categoría de riesgo. Su diseño deberá contemplar materiales de bajo impacto visual y ecológico, integración al paisaje, y gestión de residuos y aguas residuales, todo ello sustentado en un estudio de capacidad de carga turística del sitio.","s":"Infraestructura turística: miradores"},"Imi02":{"d":"Los miradores turísticos de gran escala que incluyan accesos vehiculares, comercio asociado, áreas pavimentadas o urbanización deberán someterse a un análisis de compatibilidad territorial y a una evaluación ambiental integral. Esta deberá contemplar: plan de movilidad, impacto visual, valoración paisajística, sistemas de control de escurrimientos y medidas de mitigación para el manejo de residuos y aguas grises. La operación del sitio deberá estar alineada con la capacidad de carga ambiental, y contar con mecanismos de gobernanza local.","s":"Infraestructura turística: miradores"},"Iel01":{"d":"Las líneas aéreas de media tensión y subestaciones deberán localizarse preferentemente en zonas urbanas o periurbanas previamente intervenidas, evitando áreas de valor ambiental como barrancas, bosques primarios o humedales. Su diseño deberá minimizar el impacto visual y territorial mediante el uso de tecnologías de aislamiento, compatibilidad con corredores de servicios existentes y dispositivos de seguridad para fauna silvestre. Será necesario presentar un análisis técnico de viabilidad territorial, incluyendo medidas de mitigación y mantenimiento.","s":"Infraestructura eléctrica"},"Iel02":{"d":"Las líneas de alta tensión y subestaciones en zonas ecológicamente sensibles deberán contar con un estudio integral de impacto ambiental que justifique su trazo, evalúe alternativas de ubicación y minimice la afectación a corredores biológicos, áreas de recarga hídrica o zonas con especies en riesgo. Se requerirá la implementación de medidas específicas como pasos de fauna, monitoreo de mortalidad de aves, revegetación y coordinación con programas de ordenamiento ecológico y conservación.","s":"Infraestructura eléctrica"},"Ica01":{"d":"Los conjuntos de cabañas turísticas deberán ubicarse en zonas con vocación turística y ecológica compatible, fuera de áreas prioritarias para la conservación, corredores biológicos o zonas de alta pendiente. Su diseño debe limitar la densidad de ocupación, integrar materiales locales, evitar desmontes extensivos, y contar con sistemas de captación pluvial, tratamiento de aguas residuales y manejo de residuos sólidos. Se deberá presentar un plan de manejo que contemple la operación sustentable del conjunto y su relación con la comunidad local.","s":"Infraestructura turística: cabañas"},"Ica02":{"d":"Los complejos turísticos de cabañas de gran escala deberán someterse a una evaluación ambiental integral que analice su impacto acumulativo sobre el paisaje, el suelo, los flujos hídricos y la biodiversidad local. Su viabilidad dependerá de la incorporación de infraestructura ecológica, sistemas de energía renovable, control de acceso, restauración de áreas intervenidas y planes de gobernanza participativa. El número de unidades y su distribución espacial deberá estar alineado con la aptitud ecológica del sitio y su capacidad de carga.","s":"Infraestructura turística: cabañas"},"Ica03":{"d":"Restringir la construcción de cabañas y campamentos en pendientes mayores al 15%, zonas de recarga hídrica o hábitats críticos para especies enlistadas en la NOM-059-SEMARNAT-2010.","s":"Infraestructura turística: cabañas"},"Ica04":{"d":"Utilizar materiales de construcción locales, biodegradables o de bajo impacto ambiental, evitando concreto armado, PVC, pintura industrial y materiales no renovables en zonas naturales sensibles.","s":"Infraestructura turística: cabañas"},"Ica05":{"d":"Las cabañas deberán diseñarse bajo principios de arquitectura bioclimática, respetando la vegetación nativa, con techos inclinados, ventilación natural, captación de agua pluvial y uso eficiente de energía.","s":"Infraestructura turística: cabañas"},"Ica06":{"d":"Limitar la densidad de construcción a un máximo de 5 cabañas por hectárea en zonas de selva baja, bosque templado o pastizales naturales, para minimizar el impacto sobre la biodiversidad y el paisaje.","s":"Infraestructura turística: cabañas"},"Ica07":{"d":"Contar con sistemas individuales o comunales de tratamiento de aguas residuales, como biodigestores, humedales artificiales o biofiltros, evitando descargas directas a suelo o cuerpos de agua.","s":"Infraestructura turística: cabañas"},"Ica08":{"d":"Prohibir la apertura de caminos de acceso o brechas que fragmenten ecosistemas, salvo que se justifique técnica y ambientalmente y se garantice la restauración del entorno afectado.","s":"Infraestructura turística: cabañas"},"Ica09":{"d":"Establecer rutas, senderos y señalética ecológica para las actividades turísticas, delimitando zonas de acceso, áreas restringidas y puntos de observación, con base en un Plan de Manejo Turístico Sustentable.","s":"Infraestructura turística: cabañas"},"Ica10":{"d":"Implementar un programa permanente de educación ambiental, capacitación local y vigilancia comunitaria, que promueva el respeto a la flora, fauna, usos locales y normatividad ambiental.","s":"Infraestructura turística: cabañas"},"Ica11":{"d":"Integrar un protocolo de manejo de residuos sólidos, que incluya separación en sitio, recolección diferenciada y disposición final en sitios autorizados, sin afectaciones a zonas naturales.","s":"Infraestructura turística: cabañas"},"Iserv01":{"d":"Las redes de abastecimiento de agua potable y drenaje sanitario deberán instalarse siguiendo los criterios de trazo eficiente, evitando zonas de conservación, recarga hídrica o suelos con alta vulnerabilidad a la contaminación. Se requerirá que las obras incluyan sistemas de control de fugas, materiales de bajo riesgo sanitario, pozos de visita sellados y dispositivos que eviten descargas cruzadas. Su planificación deberá considerar la densidad del asentamiento y la capacidad de absorción del sistema receptor.","s":"Infraestructura de servicios (drenaje y agua potable)"},"Iserv02":{"d":"La instalación de redes de agua potable o drenaje en zonas de conservación, de recarga de acuíferos, o con ecosistemas sensibles, requerirá estudios técnicos específicos que garanticen la compatibilidad del proyecto con las condiciones del terreno y la hidrología. Será indispensable incorporar tecnologías de mínima invasión, sistemas de tratamiento en sitio, monitoreo permanente de calidad del agua y planes de mantenimiento. La localización de la infraestructura deberá alinearse con el uso de suelo definido en los instrumentos de planeación ecológica.","s":"Infraestructura de servicios (drenaje y agua potable)"},"Itar01":{"d":"Las plantas de tratamiento de aguas residuales de escala media deberán ubicarse fuera de zonas habitadas, cuerpos de agua superficiales y áreas con riesgo geotécnico o de inundación. Será obligatorio demostrar que la tecnología seleccionada es adecuada para el volumen y tipo de aguas a tratar, incluyendo sistemas de pretratamiento, disposición segura de lodos y tratamiento terciario cuando se contemple reúso. Su operación deberá ajustarse a parámetros normativos y contar con monitoreo continuo.","s":"Infraestructura de tratamiento de aguas residuales"},"Itar02":{"d":"Las plantas de tratamiento de gran escala o aquellas que descarguen en cuerpos de agua naturales, deberán contar con una evaluación ambiental integral que contemple el análisis de impactos acumulativos, disposición final de residuos (como lodos), posibles emisiones al aire, y riesgos por operación deficiente. Será necesaria la integración de sistemas de reúso del agua tratada, infraestructura verde de amortiguamiento y participación comunitaria en el monitoreo de calidad del efluente.","s":"Infraestructura de tratamiento de aguas residuales"},"Ice01":{"d":"Las obras de control de erosión como terrazas de mampostería, gaviones o canaletas deberán aplicarse únicamente en zonas con diagnóstico técnico de degradación del suelo y análisis de pendientes, y deberán acompañarse de prácticas de revegetación con especies nativas. Se requerirá justificar su necesidad frente a alternativas de bioingeniería, evitar alteraciones a cauces naturales y asegurar su compatibilidad con la vocación del uso de suelo definida en el ordenamiento ecológico.","s":"Infraestructura de control de erosión"},"Ice02":{"d":"Las obras de gran escala como muros de contención, canalización de cauces o modificación sustancial de pendientes deberán estar sustentadas en estudios geotécnicos, hidrológicos y de riesgo. Su ejecución deberá incluir estrategias de manejo de escurrimientos, revegetación posterior, monitoreo de estabilidad y medidas que aseguren que no se induce degradación aguas abajo. La obra deberá integrarse al paisaje y contemplar coordinación con autoridades locales para su mantenimiento y seguimiento.","s":"Infraestructura de control de erosión"},"Isñ01":{"d":"La señalética ecológica estructurada —como letreros interpretativos, señalización de rutas o accesos a zonas de conservación— deberá ubicarse sin alterar la cobertura vegetal ni generar barreras físicas para la fauna. Deberá utilizar materiales duraderos pero de bajo impacto visual (madera certificada, reciclados, biodegradables) y respetar criterios de integración paisajística. Su diseño deberá evitar iluminación artificial directa o reflejante, y su instalación deberá realizarse manualmente para no alterar el suelo ni inducir compactación.","s":"Infraestructura de señalética ecológica"},"Isñ02":{"d":"Las estructuras publicitarias o de señalización sobredimensionadas en zonas de conservación o paisajes de valor escénico deberán evaluarse bajo criterios de impacto visual, fragmentación del paisaje y posible afectación a la fauna (especialmente aves nocturnas). Se requerirá su rediseño hacia formatos armonizados con el entorno, evitando estructuras metálicas invasivas, luces LED o materiales reflectantes. Toda instalación deberá ser reversible, respetar los principios de mínimo impacto y ajustarse a criterios de carga escénica.","s":"Infraestructura de señalética ecológica"},"Ihi01":{"d":"La instalación de infraestructura de distribución y expendio de hidrocarburos deberá ubicarse en zonas previamente destinadas a uso industrial o de servicios urbanos especializados, donde existan redes de transporte adecuadas, infraestructura de contención de derrames, acceso controlado y separación suficiente respecto a áreas habitacionales, escuelas, hospitales o zonas ecológicas sensibles.","s":"Infraestructura de distribución y expendio de hidrocarburos"},"Ihi02":{"d":"Deberán cumplirse especificaciones técnicas para almacenamiento seguro, sistemas de detección de fugas, control de vapores, manejo de residuos peligrosos y planes de contingencia. El diseño deberá contemplar tanques con contención secundaria, pisos impermeables y canaletas para escurrimientos accidentales.","s":"Infraestructura de distribución y expendio de hidrocarburos"},"Ihi03":{"d":"Cuando se prevea instalar infraestructura de gran escala para distribución o almacenamiento de hidrocarburos en zonas rurales, de conservación ecológica, de recarga hídrica, cerca de cuerpos de agua, centros poblacionales, Áreas Naturales Protegidas, o en áreas con alta vulnerabilidad ambiental o social, será necesario realizar una evaluación detallada de riesgos tecnológicos, vulnerabilidad social y posibles impactos acumulativos.","s":"Infraestructura de distribución y expendio de hidrocarburos"},"Ihi04":{"d":"Deberán establecerse zonas de amortiguamiento con barreras físicas, vegetación perimetral, monitoreo ambiental continuo, simulacros comunitarios de emergencia y esquemas de coordinación con Protección Civil. Toda obra debe contemplar restauración ambiental postoperativa y un sistema de gestión ambiental integral.","s":"Infraestructura de distribución y expendio de hidrocarburos"},"Ihi05":{"d":"Cuando la infraestructura destinada a la distribución y expendio de hidrocarburos (como estaciones de almacenamiento, distribución secundaria, centros de carga o expendio al público) se encuentre en una zona que haya sido urbanizada o que presente asentamientos humanos consolidados, deberá evaluarse su compatibilidad con el entorno habitacional a partir de criterios de riesgo, salud pública, normativa de distancias mínimas y capacidad de respuesta ante emergencias. Si el resultado de esta evaluación indica riesgo alto o muy alto para la población, se deberá diseñar un proceso de reubicación de la infraestructura, incluyendo la modificación del Programa Municipal de Desarrollo Urbano (PMDU) para garantizar su congruencia normativa y territorial.","s":"Infraestructura de distribución y expendio de hidrocarburos"},"Ihi06":{"d":"La determinación de la responsabilidad sobre los costos de reubicación dependerá de: • Si la instalación fue autorizada antes del crecimiento urbano no previsto, se considerará un mecanismo de compensación pública y revisión del modelo urbano. • Si la instalación fue autorizada sin respetar la normativa de distancias, o su operación representa un riesgo no mitigado, la empresa concesionaria será responsable de los costos de reubicación y restauración del sitio anterior. En ambos casos, el municipio deberá gestionar ante las autoridades estatales o federales los apoyos para la modificación del PMDU y posibles fondos de reconversión o remediación ambiental.","s":"Infraestructura de distribución y expendio de hidrocarburos"},"Ihi07":{"d":"Cuando el trazo del gasoducto se ubique en zonas con vocación industrial, corredores logísticos o derechos de vía ya existentes (ferrocarriles, carreteras, líneas eléctricas), deberá contar con estudios de compatibilidad territorial, análisis de riesgos, evaluación de afectaciones temporales durante la obra, y medidas de contención y seguridad. Se deberá asegurar que el diseño contemple zonas de amortiguamiento suficientes respecto a centros de población, cuerpos de agua o infraestructura crítica.","s":"Infraestructura de distribución y expendio de hidrocarburos"},"Ihi08":{"d":"Será indispensable contar con protocolos de mantenimiento, monitoreo de fugas, uso de válvulas de cierre de emergencia, planes de respuesta a contingencias y manuales de seguridad conforme a normativas nacionales.","s":"Infraestructura de distribución y expendio de hidrocarburos"},"Ihi09":{"d":"Cuando el trazo del gasoducto atraviese zonas con fragilidad ecológica (barrancas, zonas forestales, humedales, áreas de recarga hídrica, Áreas Naturales Protegidas, zonas de riesgo geológico o alta densidad poblacional), se requerirá una evaluación técnica rigurosa sobre riesgos, afectaciones a la biodiversidad, seguridad de comunidades cercanas y viabilidad de alternativas de trazado. Deberá garantizarse el aislamiento de ecosistemas, la continuidad de escurrimientos superficiales, y la restauración total de las zonas intervenidas durante la construcción. También deberán contemplarse medidas especiales para evitar filtraciones, explosiones, incendios o afectación a terceros, incluyendo zonas de amortiguamiento reforzadas y un sistema de monitoreo en tiempo real. Las válvulas, estaciones y puntos de control deberán ubicarse lejos de viviendas, escuelas, hospitales o centros de reunión.","s":"Infraestructura de distribución y expendio de hidrocarburos"},"Irsu01":{"d":"Ubicar rellenos sanitarios únicamente en zonas con vocación para infraestructura de manejo de residuos, fuera de áreas de conservación, zonas inundables, barrancas, cuerpos de agua o fallas geológicas.","s":"infraestructura de residuos sólidos urbanos"},"Irsu02":{"d":"Cumplir con los criterios de la NOM-083-SEMARNAT-2003, incluyendo estudios de geología, hidrogeología, compatibilidad de uso del suelo, y distancias mínimas a zonas habitadas (al menos 500 m).","s":"infraestructura de residuos sólidos urbanos"},"Irsu03":{"d":"Diseñar el relleno con sistemas de impermeabilización, captación de lixiviados, manejo de biogás, control de escurrimientos y cercado perimetral, garantizando la protección del suelo y del agua subterránea.","s":"infraestructura de residuos sólidos urbanos"},"Irsu04":{"d":"Integrar una zona de amortiguamiento verde de mínimo 20 metros con vegetación nativa alrededor del sitio, que mitigue impactos visuales, acústicos y atmosféricos.","s":"infraestructura de residuos sólidos urbanos"},"Irsu05":{"d":"Realizar monitoreos semestrales de calidad del agua subterránea, aire y suelo, con resultados disponibles para consulta pública.","s":"infraestructura de residuos sólidos urbanos"},"Irsu06":{"d":"Asegurar que la operación del sitio incluya un programa de cierre, clausura y restauración ambiental, con responsabilidad financiera garantizada para el post-clausura.","s":"infraestructura de residuos sólidos urbanos"},"Irsu07":{"d":"Todas las acciones de tratamiento de la fracción orgánica de los residuos sólidos urbanos y de manejo especial dentro del municipio deben cumplir con los métodos, procedimientos y parámetros de calidad establecidos en la NMX-AA-180-SCFI-2018.","s":"infraestructura de residuos sólidos urbanos"},"Irsu08":{"d":"La instalación y operación de centros de reciclaje y acopio de materiales sólo podrá autorizarse en sitios ambientalmente aptos y compatibles con la Unidad de Gestión Ambiental correspondiente, garantizando que la actividad no genere impactos negativos sobre el suelo, el agua, la calidad del aire ni la salud de la población. Estos centros deberán ubicarse fuera de zonas de recarga hídrica, barrancas, áreas de conservación, zonas de riesgo, asentamientos humanos irregulares y áreas con presencia de vegetación nativa o funciones ecológicas relevantes. La actividad deberá contar con infraestructura adecuada para el manejo seguro de los residuos, incluyendo áreas techadas para materiales susceptibles de dispersión, pisos impermeables, sistemas de control de escurrimientos y mecanismos para evitar polvo, ruido y emisiones fugitivas. Los centros de acopio sólo podrán recibir materiales autorizados y deberán asegurar su separación, almacenamiento temporal y manejo en condiciones que impidan contaminación del entorno o afectación a terceros. La operación estará sujeta a la presentación de un plan de manejo, bitácoras de entrada y salida de materiales y el cumplimiento de las Normas Oficiales Mexicanas aplicables en materia de residuos, seguridad e impacto ambiental. La autoridad municipal podrá establecer medidas adicionales cuando los centros se ubiquen próximos a zonas habitacionales o productivas, y tendrá la facultad de suspender o revocar autorizaciones en caso de incumplimiento, ampliaciones no autorizadas, malas prácticas operativas o riesgos ambientales no previstos. En todos los casos, el promovente deberá demostrar que el proyecto no altera el equilibrio ecológico del sitio ni afecta la calidad de vida de la población.","s":"infraestructura de residuos sólidos urbanos"},"Irsu09":{"d":"La operación deberá apegarse a la normatividad ambiental vigente y considerar medidas de integración paisajística y urbana, como cercos perimetrales y franjas de vegetación, para minimizar impactos visuales y sociales.","s":"infraestructura de residuos sólidos urbanos"},"Irsu10":{"d":"Las áreas de operación deberán contar con superficies impermeables y sistemas de drenaje controlado, evitando escurrimientos contaminantes.","s":"infraestructura de residuos sólidos urbanos"},"Irsu11":{"d":"Se deberán incorporar medidas de control de polvo, ruido, olores y fauna nociva.","s":"infraestructura de residuos sólidos urbanos"},"Icah01":{"d":"La infraestructura deberá ubicarse únicamente en áreas con vocación urbana o rural habitacional, evitando zonas de conservación, recarga de acuíferos, áreas de riesgo o de valor ambiental prioritario.","s":"Infraestructura complementaria a asentamientos humanos"},"Icah02":{"d":"Las obras deberán priorizar tecnologías y materiales que optimicen el uso eficiente de agua y energía, fomenten el ahorro de recursos y minimicen la generación de residuos.","s":"Infraestructura complementaria a asentamientos humanos"},"Icah03":{"d":"El diseño de la infraestructura deberá garantizar la accesibilidad universal (personas con discapacidad, adultos mayores, niños), así como la equidad en el acceso a servicios básicos.","s":"Infraestructura complementaria a asentamientos humanos"},"Icah04":{"d":"Toda obra deberá cumplir con la normatividad ambiental vigente (evaluación de impacto ambiental, normas técnicas), incorporando medidas de mitigación como reforestación, revegetación de taludes, control de polvo y manejo adecuado de residuos de construcción.","s":"Infraestructura complementaria a asentamientos humanos"},"Fru01":{"d":"Ejercer la fruticultura únicamente en polígonos con aptitud agrícola confirmada, fuera de zonas de recarga hídrica prioritaria, barrancas y áreas naturales protegidas.","s":"plantaciones de frutales"},"Fru02":{"d":"La movilización de fruta de aguacate para mercado nacional y exportación deberá cumplir las especificaciones fitosanitarias establecidas en la NOM-066-FITO-2002, incluyendo el manejo integrado de plagas cuarentenarias (barrenadores del hueso y de ramas, entre otras) bajo el esquema de la Campaña de Manejo Fitosanitario del Aguacatero.","s":"plantaciones de frutales"},"Fru03":{"d":"La movilización de mango, cítricos y demás frutos hospederos de moscas de la fruta deberá acreditar su procedencia de huertos registrados en la Campaña Nacional contra Moscas de la Fruta (NOM-023-FITO-1995) y cumplir los requisitos fitosanitarios de movilización establecidos en la NOM-075-FITO-1997, incluyendo, cuando corresponda, el tratamiento hidrotérmico (agua caliente) o cuarentenario según la categoría fitosanitaria de la zona de destino (libre, de baja prevalencia o bajo control fitosanitario).","s":"plantaciones de frutales"},"Fru04":{"d":"El material propagativo de cítricos utilizado en nuevas plantaciones deberá estar libre de virus tristeza y otros patógenos asociados.","s":"plantaciones de frutales"},"Fru05":{"d":"Las plantaciones de plátano y banano deberán sujetarse a las medidas fitosanitarias para combatir el moko del plátano (Ralstonia solanacearum raza 2) y prevenir su diseminación, conforme a la NOM-068-FITO-2000, incluyendo la desinfección de herramientas y equipo entre predios, la restricción de movimiento de material vegetativo (hijuelos, rizomas) proveniente de zonas afectadas, y la eliminación de plantas enfermas mediante los métodos que determine la autoridad fitosanitaria competente.","s":"plantaciones de frutales"},"Fru06":{"d":"Establecer una franja de amortiguamiento de al menos 20 metros entre huertas frutícolas y cuerpos de agua o vegetación natural.","s":"plantaciones de frutales"},"Fru07":{"d":"Prohibir la expansión de huertas frutícolas mediante el desmonte de vegetación forestal primaria o secundaria arbórea.","s":"plantaciones de frutales"},"Fru08":{"d":"Instalar sistemas de riego tecnificado (goteo o microaspersión) en huertas de nueva creación, priorizando la eficiencia hídrica.","s":"plantaciones de frutales"},"Fru09":{"d":"Disponer los envases vacíos de agroquímicos utilizados en huertas frutícolas en centros de acopio autorizados, quedando prohibido su reúso o quema a cielo abierto.","s":"plantaciones de frutales"},"Fru10":{"d":"Los proyectos de fruticultura identificados como una alternativa económica a las actividades agropecuarias que se realizan en la zona se podrán llevar a cabo solo en las UGA de Aprovechamiento sustentable","s":"plantaciones de frutales"},"Fru11":{"d":"La siembra de árboles frutales se llevará a cabo preferentemente para la reconversión productiva que permita la recuperación de masa forestal y de suelos a través de técnicas agrosilvícolas y/o la combinación con leguminosas arbóreas para favorecer la fijación de nitrógeno en el suelo.","s":"plantaciones de frutales"},"Fru12":{"d":"Las plantaciones de frutales que se establezcan, deberán elaborar un programa que indique cómo se mitigarán los efectos adversos para los ecosistemas acuáticos y/o terrestres.","s":"plantaciones de frutales"},"Fru13":{"d":"Para disminuir la pérdida de suelo por erosión en pendientes de 8 a 20% se recomienda establecer cultivos perennes y/o sistemas agroforestales.","s":"plantaciones de frutales"},"Fru14":{"d":"Para reducir la erosión, en las áreas destinadas a siembra de frutales se establecerán cultivos de cobertera de ciclo largo entre las hileras de árboles, preferentemente de especies coberteras forrajeras o abonos verdes que no interfieran con las especies frutales.","s":"plantaciones de frutales"},"Pal01":{"d":"Se implementarán de manera permanente las mejores prácticas agrícolas y operativas disponibles para garantizar que la producción de palma de aceite se realice de tal forma que mantenga las funciones ecológicas y estructurales de los paisajes.","s":"Plantaciones de palmeras"},"Pal02":{"d":"Deforestación y quema cero para el establecimiento de plantaciones de palma de aceite. El desacato de este criterio en zonas de manglares, selvas, humedales, vegetación hidrófila, costeras y litorales, lacustres y palustres, turberas y sabanas, será sancionado en los términos que establezca la legislación ambiental vigente y requerirá de inmediato la remediación del daño ambiental","s":"Plantaciones de palmeras"},"Pal03":{"d":"La siembra de plantaciones de palma de aceite puede realizarse solo en terreno con pendiente menor a 10% y suelos profundos con buen drenaje que evite inundaciones","s":"Plantaciones de palmeras"},"Pal04":{"d":"Los agroquímicos se utilizarán solo cuando es estrictamente necesario y se emplean de forma controlada y dirigida, dando un énfasis en su aplicación en zonas con una distancia mayor a 30 metros de cualquier cuerpo de agua.","s":"Plantaciones de palmeras"},"Pal05":{"d":"Se priorizará la nutrición orgánica en las plantaciones de palma de aceite.","s":"Plantaciones de palmeras"},"Pal06":{"d":"La cacería de especies silvestres o de importancia ecológica no podrá ser realizada al interior de las plantaciones de palma de aceite.","s":"Plantaciones de palmeras"},"Pal07":{"d":"Las plagas, enfermedades, malezas y especies invasivas introducidas se manejarán eficazmente mediante técnicas apropiadas de Manejo Integrado de Plagas (MIP)","s":"Plantaciones de palmeras"},"Pal08":{"d":"Se implementará un plan de gestión de residuos para la reducción, el reciclaje, la reutilización y la disposición final en función de su toxicidad y sus características peligrosas.","s":"Plantaciones de palmeras"},"Pal09":{"d":"Se documentará e implementará un plan de gestión del agua para promover su uso eficiente, la disponibilidad continua de las fuentes de agua y evitar impactos negativos en otros usuarios de la cuenca a la que pertenece la UGA.","s":"Plantaciones de palmeras"},"Pal10":{"d":"La unidad de producción de palma de aceite no contribuirá a la contaminación del agua utilizada por las comunidades.","s":"Plantaciones de palmeras"},"Pal11":{"d":"Los cursos de agua y los humedales estarán protegidos, incluido el mantenimiento y la restauración de zonas ribereñas y la zonas de amortiguamiento de 30 metros desde cada margen. El efluente de la planta extractora tendrá un proceso de tratamiento para cumplir con las regulaciones nacionales. La calidad de la descarga del efluente de la planta extractora, especialmente la Demanda Bioquímica de Oxígeno (DBO), será monitoreado regularmente.","s":"Plantaciones de palmeras"},"Pal12":{"d":"Se implementará el monitoreo y reporte para mejorar la eficiencia del uso de combustibles fósiles y para optimizar la energía renovable.","s":"Plantaciones de palmeras"},"Pal13":{"d":"La superficie actual de producción de aceite de palma se restaura mediante su certificación a través de las siguientes directrices: detener la deforestación de bosques, selvas y manglares primarios y secundarios arbóreos, garantizar que no se dañen las especies de flora y fauna en peligro de extinción, impedir establecer nuevas plantaciones en zonas de humedales, reducir las emisiones de carbono y enfatizar la importancia de las zonas ribereñas en las plantaciones de palma aceitera limitando su uso en las zonas que se encuentran en las tierras bajas y los 300 m de altitud.","s":"Plantaciones de palmeras"},"Pal14":{"d":"Se implementan acciones para reducir la contaminación y las emisiones, como las de gases de efecto invernadero (GEI), y se diseñan nuevas técnicas para minimizar las emisiones de GEI derivadas de la producción y transformación de la palma de aceite.","s":"Plantaciones de palmeras"},"PGS01":{"d":"Los parques solares de escala media deberán ubicarse en terrenos previamente transformados o de baja sensibilidad ecológica, evitando zonas de recarga hídrica, corredores de biodiversidad y suelos con vegetación natural. Será obligatorio presentar un estudio de compatibilidad territorial, asegurar cercado permeable para fauna, diseñar con respeto a la vegetación existente, y prever medidas de manejo de escurrimientos y restauración del suelo tras la instalación. Se deberá demostrar la coexistencia posible con actividades agropecuarias o de conservación.","s":"Proyectos de generación de energía solar"},"PGS02":{"d":"Los parques solares de gran escala, localizados en terrenos con vegetación natural, zonas de valor escénico o ecológico, deberán ser objeto de una evaluación ambiental rigurosa, que incluya análisis de conectividad ecológica, fragmentación del hábitat, impacto acumulativo y medidas de compensación ambiental. Se exigirá un programa de monitoreo postoperativo, restauración progresiva y consulta social efectiva como condición para su instalación y operación.","s":"Proyectos de generación de energía solar"},"PGS03":{"d":"Se instalarán parques fotovoltaicos para el aprovechamiento de energía solar para pequeñas o medianas comunidades.","s":"Proyectos de generación de energía solar"},"PGS04":{"d":"Se instalarán líneas de distribución para la conducción de electricidad generada por celdas fotovoltaicas y serán incorporadas a la red de la Comisión Federal de Electricidad (CFE).","s":"Proyectos de generación de energía solar"},"PGS05":{"d":"Se realizarán de proyectos de generación de electricidad a partir de energías renovables, preferentemente para los propietarios o poseedores de los terrenos y los sujetos de derechos sobre los recursos naturales involucrados en dichos proyectos","s":"Proyectos de generación de energía solar"},"PGS06":{"d":"Se implementarán medidas de eficiencia energética, como el uso de electrodomésticos e iluminación eficiente, para reducir el consumo y los costos de energía.","s":"Proyectos de generación de energía solar"},"PGS07":{"d":"El manejo y la descarga de aguas residuales en el área del proyecto, zonas aledañas y cuerpos de agua, se realizará de acuerdo a la normatividad vigente en la materia","s":"Proyectos de generación de energía solar"},"PGS08":{"d":"El material producto de las excavaciones y despalme se empleará en rellenos y en actividades de restauración dentro o fuera de la instalación. En caso de ser desechadó, se considerará como residuo y deberá sujetarse a lo que defina la autoridad competente o en su caso el plan de manejo correspondiente.","s":"Proyectos de generación de energía solar"},"PGS09":{"d":"El proyecto de energía cumple con todas las normas y permisos pertinentes, como códigos de construcción, permisos ambientales y requisitos de interconexión.","s":"Proyectos de generación de energía solar"},"PGS10":{"d":"La propiedad y el control sobre el proyecto, será preferentemente a nivel local, por ejemplo, a través de la propiedad comunitaria de la infraestructura energética o mediante el establecimiento de una cooperativa comunitaria de energía.","s":"Proyectos de generación de energía solar"},"PGS11":{"d":"Las comunidades locales y los pueblos originarios participarán desde las primeras etapas del proyecto para garantizar que tengan voz en el diseño y la implementación del proyecto. Con el fin de que se proporcionen oportunidades y espacios para que los miembros de la comunidad expresen sus inquietudes y sugerencias.","s":"Proyectos de generación de energía solar"},"PGS12":{"d":"Las obras para los caminos, las plataformas y el campamento, son las únicas áreas que pueden ser ocupadas. El resto del terreno debe permanecer en su estado natural, por lo que no podrá ser ocupado bajo ningún concepto para circular o estacionar vehículos o acopiar materiales.","s":"Proyectos de generación de energía solar"},"PGS13":{"d":"Los estudios, medidas, obras y acciones a desarrollar durante la instalación de nuevos proyectos de infraestructura para energía, se difundirán a la ciudadanía.","s":"Proyectos de generación de energía solar"},"PGS14":{"d":"Los residuos vegetales generados por las actividades de desmonte serán triturados o picados, mezclados y esparcidos en la superficie del terreno que se destine para áreas verdes o ser enviados para un fin similar fuera de la instalación. En caso de ser desechados, se considerarán como residuos y se sujetarán a lo que defina la autoridad competente o en su caso el plan de manejo correspondiente.","s":"Proyectos de generación de energía solar"},"PGS15":{"d":"Para disminuir la erosión por la apertura de caminos de acceso y minimizar su incidencia, se realizarán las obras necesarias para mitigarla y prevenirla.","s":"Proyectos de generación de energía solar"},"PGS16":{"d":"Para restaurar o restablecer la vegetación se utilizarán las especies vegetales propias del lugar susceptibles de desarrollarse en el sitio, conforme a la descripción del ambiente elaborada y aprobada.","s":"Proyectos de generación de energía solar"},"PGS17":{"d":"Quienes solicitan el permiso para llevar a cabo cualquier proyecto energético, realizarán una evaluación integral de impacto ambiental y social para identificar posibles impactos negativos y desarrollar medidas de mitigación para minimizar estos impactos, esto con el fin de contar con elementos para su posible autorización y viabilidad.","s":"Proyectos de generación de energía solar"},"PGS18":{"d":"Se coadyuvará al cumplimiento de los compromisos internacionales en materia de generación y Aprovechamiento de Energías Limpias y el Aprovechamiento sustentable de la energía.","s":"Proyectos de generación de energía solar"},"PGS19":{"d":"Se identificarán, con apoyo de la Comisión Nacional para el Uso Eficiente de la Energía y empresas distribuidoras de energía, áreas de oportunidad y programas de eficiencia energética por sectores de uso final","s":"Proyectos de generación de energía solar"},"PGS20":{"d":"Se proporcionarán actualizaciones periódicas sobre el progreso del proyecto y se entablará un diálogo abierto con la comunidad para garantizar la transparencia en todos los aspectos del proyecto y rendir cuentas a la comunidad.","s":"Proyectos de generación de energía solar"},"PGS21":{"d":"Se toman en cuenta las prácticas culturales, los valores y las tradiciones para el diseño de los proyectos energéticos","s":"Proyectos de generación de energía solar"},"PGE01":{"d":"Los parques eólicos de escala media deberán ubicarse fuera de rutas migratorias de aves, zonas de alta biodiversidad, sierras y pendientes pronunciadas. Su diseño deberá contemplar estudios previos de avifauna y murciélagos, evitar la apertura innecesaria de caminos, emplear cimentaciones mínimas y planear corredores técnicos compartidos para reducir la fragmentación del paisaje. Además, deberán integrarse medidas de monitoreo de colisiones y planes de compensación por pérdida de hábitat.","s":"Proyectos de generación de energía eólica"},"PGE02":{"d":"Los parques eólicos industriales de gran escala ubicados en zonas de valor ecológico, corredores biológicos, sierras, áreas naturales protegidas o territorios indígenas deberán ser evaluados en términos de impacto acumulativo, fragmentación del hábitat, efectos sobre conectividad ecológica y conflictos sociales. Será indispensable incorporar pasos de fauna, monitoreo de largo plazo, rediseño de trazo si es necesario y mecanismos de consulta pública con las comunidades locales antes de su instalación.","s":"Proyectos de generación de energía eólica"},"PGE03":{"d":"Se realizarán de proyectos de generación de electricidad a partir de energías renovables, preferentemente para los propietarios o poseedores de los terrenos y los sujetos de derechos sobre los recursos naturales involucrados en dichos proyectos","s":"Proyectos de generación de energía eólica"},"PGE04":{"d":"Se implementarán medidas de eficiencia energética, como el uso de electrodomésticos e iluminación eficiente, para reducir el consumo y los costos de energía.","s":"Proyectos de generación de energía eólica"},"PGE05":{"d":"El manejo y la descarga de aguas residuales en el área del proyecto, zonas aledañas y cuerpos de agua, se realizará de acuerdo a la normatividad vigente en la materia","s":"Proyectos de generación de energía eólica"},"PGE06":{"d":"El material producto de las excavaciones y despalme se empleará en rellenos y en actividades de restauración dentro o fuera de la instalación. En caso de ser desechadó, se considerará como residuo y deberá sujetarse a lo que defina la autoridad competente o en su caso el plan de manejo correspondiente.","s":"Proyectos de generación de energía eólica"},"PGE07":{"d":"El proyecto de energía cumple con todas las normas y permisos pertinentes, como códigos de construcción, permisos ambientales y requisitos de interconexión.","s":"Proyectos de generación de energía eólica"},"PGE08":{"d":"La propiedad y el control sobre el proyecto, será preferentemente a nivel local, por ejemplo, a través de la propiedad comunitaria de la infraestructura energética o mediante el establecimiento de una cooperativa comunitaria de energía.","s":"Proyectos de generación de energía eólica"},"PGE09":{"d":"Las comunidades locales y los pueblos originarios participarán desde las primeras etapas del proyecto para garantizar que tengan voz en el diseño y la implementación del proyecto. Con el fin de que se proporcionen oportunidades y espacios para que los miembros de la comunidad expresen sus inquietudes y sugerencias.","s":"Proyectos de generación de energía eólica"},"PGE10":{"d":"Las obras para los caminos, las plataformas y el campamento, son las únicas áreas que pueden ser ocupadas. El resto del terreno debe permanecer en su estado natural, por lo que no podrá ser ocupado bajo ningún concepto para circular o estacionar vehículos o acopiar materiales.","s":"Proyectos de generación de energía eólica"},"PGE11":{"d":"Los estudios, medidas, obras y acciones a desarrollar durante la instalación de nuevos proyectos de infraestructura para energía, se difundirán a la ciudadanía.","s":"Proyectos de generación de energía eólica"},"PGE12":{"d":"Los residuos vegetales generados por las actividades de desmonte serán triturados o picados, mezclados y esparcidos en la superficie del terreno que se destine para áreas verdes o ser enviados para un fin similar fuera de la instalación. En caso de ser desechados, se considerarán como residuos y se sujetarán a lo que defina la autoridad competente o en su caso el plan de manejo correspondiente.","s":"Proyectos de generación de energía eólica"},"PGE13":{"d":"Para disminuir la erosión por la apertura de caminos de acceso y minimizar su incidencia, se realizarán las obras necesarias para mitigarla y prevenirla.","s":"Proyectos de generación de energía eólica"},"PGE14":{"d":"Para restaurar o restablecer la vegetación se utilizarán las especies vegetales propias del lugar susceptibles de desarrollarse en el sitio, conforme a la descripción del ambiente elaborada y aprobada.","s":"Proyectos de generación de energía eólica"},"PGE15":{"d":"Quienes solicitan el permiso para llevar a cabo cualquier proyecto energético, realizarán una evaluación integral de impacto ambiental y social para identificar posibles impactos negativos y desarrollar medidas de mitigación para minimizar estos impactos, esto con el fin de contar con elementos para su posible autorización y viabilidad.","s":"Proyectos de generación de energía eólica"},"PGE16":{"d":"Se coadyuvará al cumplimiento de los compromisos internacionales en materia de generación y Aprovechamiento de Energías Limpias y el Aprovechamiento sustentable de la energía.","s":"Proyectos de generación de energía eólica"},"PGE17":{"d":"Se identificarán, con apoyo de la Comisión Nacional para el Uso Eficiente de la Energía y empresas distribuidoras de energía, áreas de oportunidad y programas de eficiencia energética por sectores de uso final","s":"Proyectos de generación de energía eólica"},"PGE18":{"d":"Se proporcionarán actualizaciones periódicas sobre el progreso del proyecto y se entablará un diálogo abierto con la comunidad para garantizar la transparencia en todos los aspectos del proyecto y rendir cuentas a la comunidad.","s":"Proyectos de generación de energía eólica"},"PGE19":{"d":"Se toman en cuenta las prácticas culturales, los valores y las tradiciones para el diseño de los proyectos energéticos","s":"Proyectos de generación de energía eólica"},"MnM01":{"d":"Ubicar las actividades de minería no metálica únicamente dentro de polígonos previamente definidos por el POEL, fuera de zonas de conservación, barrancas, cuerpos de agua, áreas de recarga hídrica y sitios con pendiente mayor a 15%","s":"Minería no metálica"},"MnM02":{"d":"Delimitar las zonas autorizadas para extracción mediante coordenadas georreferenciadas y condiciones técnicas que incluyan estudio de impacto acumulativo y análisis de conectividad ecológica","s":"Minería no metálica"},"MnM03":{"d":"Excluir del otorgamiento de permisos para nuevas explotaciones a predios sin evaluación técnica de impactos sinérgicos o localizados en áreas con presencia de especies prioritarias para la conservación","s":"Minería no metálica"},"MnM04":{"d":"Ejecutar las actividades mineras con planes de manejo ambiental que incluyan restauración progresiva, cronogramas de compensación, tratamiento de escorrentías y reducción de partículas suspendidas","s":"Minería no metálica"},"MnM05":{"d":"Implementar sistemas de riego de caminos, barreras cortaviento, cobertura vegetal o humectación de frentes de explotación para mitigar emisiones de partículas PM10 y PM2","s":"Minería no metálica"},"MnM06":{"d":"Instalar plataformas de control de escurrimientos y barreras de retención de sedimentos en las zonas de explotación con exposición directa a laderas, cuerpos de agua o zonas agrícolas","s":"Minería no metálica"},"MnM07":{"d":"Revegetar las áreas intervenidas mediante especies nativas una vez concluida la extracción, con monitoreo obligatorio durante un periodo mínimo de 5 años tras el cierre técnico","s":"Minería no metálica"},"MnM08":{"d":"Disponer los residuos sólidos y peligrosos generados por la operación minera en sitios autorizados, manteniendo un registro mensual y entregándolo a la autoridad municipal ambiental","s":"Minería no metálica"},"MnM09":{"d":"Presentar una bitácora técnica y ambiental con registros mensuales de extracción, calidad del aire, cumplimiento de medidas ambientales y acciones de restauración","s":"Minería no metálica"},"MnM10":{"d":"Establecer una trazabilidad del material extraído mediante guías de transporte validadas por el municipio, que indiquen origen, volumen, destino y medidas de mitigación implementadas","s":"Minería no metálica"},"MnM11":{"d":"Los bancos de materiales deberán contar obligatoriamente con una zona de amortiguamiento perimetral de al menos 30 metros de ancho, medidos desde el límite exterior de la actividad extractiva. Esta franja tendrá como función mitigar los impactos ambientales negativos derivados de la extracción, tales como el ruido, la dispersión de partículas, la pérdida de cobertura vegetal, la alteración de hábitats y la fragmentación del paisaje. Dentro de esta zona de amortiguamiento se promoverá la conservación de vegetación natural o su restauración en caso de haber sido afectada, y se restringirá cualquier tipo de actividad que implique remoción de suelo, construcción, o tránsito de maquinaria pesada. Esta medida deberá incorporarse en los planes de manejo ambiental y en los estudios de impacto ambiental correspondientes, y será supervisada por la autoridad competente durante toda la vida útil del banco de materiales.","s":"Minería no metálica"},"MnM12":{"d":"En las zonas con pendiente media a alta (superior al 15%) donde se permita la minería no metálica (extracción de material pétreo, caliza, arena, tezontle, etc.), la extracción deberá realizarse de manera escalonada o en terrazas, conforme a un plan de explotación geotécnico y topográfico, elaborado por un perito acreditado, que asegure la estabilidad del talud y la seguridad estructural del terreno. Este plan deberá contener: • Diseño detallado de bancas o escalones de corte, con altura y profundidad determinadas en función de la pendiente, tipo de material y condiciones climáticas. • Análisis de estabilidad de taludes bajo escenarios de lluvia intensa, sismos o vibraciones por maquinaria. • Sistema de drenaje superficial y subterráneo que impida acumulación de agua en los cortes y reduzca la erosión. • Revestimiento vegetal o estructural en los bordes superiores y zonas de descanso del talud. • Plan de manejo y disposición segura del material extraído y estéril, evitando su acumulación inestable. La operación minera deberá contar con una bitácora técnica de seguridad geotécnica y someterse a inspecciones periódicas por parte de la autoridad ambiental o de protección civil municipal o estatal.","s":"Minería no metálica"},"MnM13":{"d":"Los predios sujetos a extracción deberán contar con un programa avalado por la autoridad competente de supervisión, vigilancia y seguimiento de las medidas de mitigación ambiental, compensación, restauración, así como de reducción del impacto paisajístico generado por la actividad extractiva definidas en el resolutivo de las manifestaciones de impacto ambiental.","s":"Minería no metálica"},"MnM14":{"d":"No se permitirá la apertura de nuevos bancos de materiales pétreos en la UGA, debiendo agotar las reservas de los bancos existentes. Para el caso del emplazamiento de infraestructura, solo se permitirá la apertura de bancos de préstamo que sean utilizados para el propio proyecto que se esté realizando y el sitio deberá ser regenerado en su totalidad al terminar la obra.","s":"Minería no metálica"},"MnM15":{"d":"En el área de explotación no se permitirá el almacenamiento permanente de chatarra o residuos originados por la maquinaria o la construcción de la infraestructura de la mina. En caso de que el titular pretenda darle un uso distinto al predio, deberá obtener previamente la autorización correspondiente en materia de impacto ambiental.","s":"Minería no metálica"},"MnM16":{"d":"Los bancos de materiales y préstamo que carezcan de la autorización actualizada por la autoridad competente deberán ser clausurados y regenerados, evitando dejar el suelo desnudo para minimizar la emisión de partículas PM 10. Aquellos particulares que no lleven a cabo la restauración de los predios al fin de su período de explotación no podrán realizar nuevos aprovechamientos en otros predios hasta que lleven a cabo un plan de restauración ecológica.","s":"Minería no metálica"},"MnM17":{"d":"Los sitios de extracción deberán respetar una franja de amortiguamiento de 20 metros como mínimo hacia el interior del predio en todo el perímetro. Esta franja deberá forestarse con especies arbóreas nativas de la región, estableciendo un programa de trabajo a fin de garantizar la supervivencia de los individuos plantados y remplazando aquellos que perezcan.","s":"Minería no metálica"},"MnM18":{"d":"Para la ampliación de la superficie de extracción en un proyecto activo se condicionará al cumplimiento anual de acciones de mitigación y restauración de por lo menos el 50 % de la superficie autorizada. No se permitirá la ampliación a aquellos particulares que incumplan con la restauración de zonas que se encuentran al final del período de explotación.","s":"Minería no metálica"},"Pes01":{"d":"Solo residentes de comunidades ribereñas pueden pescar para consumo doméstico","s":"Pesca ribereña"},"Pes02":{"d":"Solo residentes de comunidades ribereñas pueden pescar para consumo doméstico","s":"Pesca ribereña"},"Pes03":{"d":"Equipo limitado a línea con anzuelo/vara individual desde la orilla; prohibidas redes y artes de arrastre","s":"Pesca ribereña"},"Pes04":{"d":"Cuota máxima 2 kg/día de crustáceos, respetando tallas mínimas","s":"Pesca ribereña"},"Pes05":{"d":"Prohibición absoluta de chinchorros, trasmallos, fisgas, arpones, pesca eléctrica, explosivos y técnicas como \"apaleo\", \"arreo\", \"corraleo\", etc.","s":"Pesca ribereña"},"Pes06":{"d":"Respeto de épocas y zonas de veda","s":"Pesca ribereña"},"Pes07":{"d":"La infraestructura terrestre para actividades pesqueras (bodegas, embarcaderos, zonas de almacenamiento y procesamiento) deberá cumplir con la normativa ambiental vigente, incluyendo el manejo adecuado de residuos sólidos, aguas servidas y materiales peligrosos.","s":"Pesca ribereña"},"Pes08":{"d":"Distancia mínima de 250 m entre pesca deportivo-recreativa y comercial; no operar ambas en la misma embarcación","s":"Pesca ribereña"},"Pes09":{"d":"No alterar vegetación de ribera ni instalar infraestructura fija dentro de la franja de protección ribereña","s":"Pesca ribereña"},"Pes10":{"d":"Las actividades pesqueras como la limpieza de organismos, el mantenimiento de embarcaciones y la operación en atracaderos deberán realizarse en sitios adecuados, con señalética ambiental, medidas de seguridad y prevención de impactos.","s":"Pesca ribereña"},"Pes11":{"d":"Durante los periodos de veda establecidos por la autoridad competente, queda estrictamente prohibida la realización de actividades de pesca en cuerpos de agua superficiales del municipio, con el fin de permitir la reproducción, recuperación y conservación de las poblaciones acuáticas y mantener el equilibrio ecológico de los ecosistemas asociados.","s":"Pesca ribereña"},"Pes12":{"d":"Se prohíbe la contaminación genética de las poblaciones locales de fauna y flora derivada de la introducción de individuos con genes que no han sido seleccionados naturalmente.","s":"Pesca ribereña"},"Esc01":{"d":"La disposición de residuos de construcción y demolición deberá realizarse únicamente en sitios expresamente autorizados por el municipio o entidad estatal, preferentemente en áreas previamente degradadas o con vocación para la recuperación del suelo. Las escombreras deberán ubicarse fuera de zonas con valor ambiental, cuerpos de agua, zonas de recarga hídrica, cauces, áreas con pendientes mayores a 15%, y sitios con suelos frágiles o susceptibles a procesos de erosión.","s":"Escombreras"},"Esc02":{"d":"Será obligatorio el manejo selectivo del material, separación de residuos valorizables, control de escurrimientos y polvos, y rehabilitación progresiva del sitio para evitar impactos paisajísticos y ambientales a largo plazo.","s":"Escombreras"},"Esc03":{"d":"El proyecto deberá incluir estudios que demuestren que la actividad no afectará el equilibrio ecológico, ni inducirá riesgos por saturación del suelo, contaminación del subsuelo o deterioro de bienes comunes.","s":"Escombreras"},"Tal01":{"d":"Las actividades de turismo de naturaleza y ecoturismo se ubicarán exclusivamente en zonas previamente clasificadas como de conservación, restauración o vocación turística ambiental, fuera de centros de población, evitando proyectos de turismo convencional que impacten negativamente los ecosistemas, la biodiversidad y los recursos naturales. Todo proyecto deberá contar con una Autorización de Impacto Ambiental —sustentada, según su escala, en una ficha de compatibilidad territorial que incluya descripción del proyecto, estudio de conectividad ecológica, análisis de impacto paisajístico y plan de manejo ambiental, evaluada por la Dirección de Ecología Municipal y el Comité Técnico correspondiente— que considere las perturbaciones a los ecosistemas, el paisaje, la biodiversidad y los servicios ambientales, y que defina el límite de cambio aceptable de la UGA.","s":"Turismo alternativo"},"Tal02":{"d":"Todo proyecto turístico deberá respetar una franja de amortiguamiento mínima de 20 metros de vegetación nativa sin intervención hacia cuerpos de agua, barrancas, zonas arboladas o corredores biológicos identificados en el ordenamiento, sin fragmentar hábitats críticos ni interrumpir los flujos ecológicos entre polígonos de conservación.","s":"Turismo alternativo"},"Tal03":{"d":"La infraestructura ecoturística se limitará a espacios con acceso controlado y una superficie máxima de 2,500 m², sin fragmentar hábitats prioritarios ni corredores biológicos. Cuando el proyecto se desarrolle sobre un predio destinado a turismo alternativo, este deberá tener una superficie mínima de 5,000 m², con una ocupación máxima del 30% del terreno, conservación de al menos el 70% de la cobertura vegetal original, y altura máxima de dos niveles en las edificaciones.","s":"Turismo alternativo"},"Tal04":{"d":"Se autorizarán únicamente construcciones rústicas o ecológicas de bajo impacto (cabañas, bungalows, plataformas de campamento, miradores, senderos, módulos de interpretación, sanitarios ecológicos), empleando materiales locales y biodegradables, sistemas modulares, superficies permeables sin cimentaciones profundas, y vegetación nativa en las áreas verdes. Queda prohibida la construcción de vialidades secundarias o terciarias con materiales asfálticos o residuos de construcción; los senderos y caminos se rehabilitarán con materiales propios de la zona, autorizados por la autoridad ambiental competente. El equipamiento mínimo obligatorio incluirá señalética interpretativa ambiental, rutas peatonales delimitadas y puntos de recolección diferenciada de residuos.","s":"Turismo alternativo"},"Tal05":{"d":"Los proyectos turísticos contarán con un sistema de gestión ambiental para el manejo integral del agua, energía, áreas verdes y residuos sólidos (separados en orgánicos e inorgánicos, priorizando su valorización o biodegradación), quedando absolutamente prohibido destinar cualquier área del predio como basurero. Los espacios que superen las 50 visitas diarias integrarán sistemas de captación pluvial, biodigestores y baños secos; en todos los casos se dará prioridad a obtener al menos el 15% del agua requerida mediante captación de aguas pluviales y al menos el 25% de la energía mediante fuentes renovables.","s":"Turismo alternativo"},"Tal06":{"d":"Se evitará la apertura de senderos, cabañas o zonas de campamento en pendientes mayores al 15%, suelos frágiles o zonas propensas a incendios forestales; en las zonas más expuestas se integrarán cortafuegos naturales, bancos de agua y reforestación con especies resistentes a sequía. Todas las actividades turísticas contarán con estrictas medidas de prevención y mitigación de incendios forestales, siendo los promoventes responsables de compensar el daño ecológico causado por incendios derivados de su actividad.","s":"Turismo alternativo"},"Tal07":{"d":"Se aplicarán límites de capacidad de carga (visitantes por día o semana) definidos técnicamente para cada sitio, ajustables según las condiciones climáticas, la disponibilidad de agua y el estado de los ecosistemas, llevando una bitácora ambiental que registre el número de visitantes, las afectaciones observadas y las acciones correctivas implementadas, revisada semestralmente por el comité municipal de ordenamiento.","s":"Turismo alternativo"},"Tal08":{"d":"Las obras y actividades turísticas se realizarán sin afectar los ecosistemas, remover vegetación natural o alterar el paisaje y el patrimonio cultural local; los promoventes de proyectos en áreas ambiental o culturalmente sensibles deberán establecer una guía y lineamientos de comportamiento para los visitantes.","s":"Turismo alternativo"},"Tal09":{"d":"El desarrollo de proyectos turísticos incluirá procesos de participación ciudadana con las comunidades rurales involucradas, respetando sus tradiciones y costumbres. En los proyectos promovidos o financiados por instituciones del sector público se capacitará a la población local en el manejo de los recursos naturales, patrimoniales, financieros y socio-organizativos, dándole prioridad en la gestión y operación de los proyectos, y se fomentará el acompañamiento de personal acreditado, preferentemente local, en los recorridos interpretativos y actividades de observación.","s":"Turismo alternativo"},"Tal10":{"d":"El turismo de aventura y las actividades de naturaleza en sitios de alta sensibilidad ecológica (bosques primarios, barrancas, humedales, cuevas, dunas, zonas de anidación o recarga hídrica) se desarrollarán únicamente sobre rutas y zonas de descanso autorizadas, con señalización no invasiva, evitando la intervención en vegetación primaria, pendientes extremas, cauces activos o sitios con especies protegidas, así como la introducción de especies exóticas, el ruido y la iluminación artificial. Estas actividades requerirán un plan de manejo adaptativo con indicadores ecológicos y protocolos de cierre temporal o definitivo ante evidencia de deterioro. Cuando impliquen el uso de vehículos motorizados fuera de caminos establecidos (rutas 4x4, cuatrimotos, motocross) o la instalación de estructuras específicas (tirolesas, plataformas, puentes colgantes), deberá realizarse además un estudio de impacto acumulativo, con zonificación estricta, control de accesos y monitoreo continuo, integrándose a las estrategias locales de conservación con participación comunitaria en la supervisión y distribución de beneficios.","s":"Turismo alternativo"},"Tal11":{"d":"Limitar el tránsito motorizado dentro de las zonas ecoturísticas únicamente a vehículos de servicio autorizados, empleando senderos, bicicletas o transporte eléctrico como medios preferentes","s":"Turismo alternativo"},"Tal12":{"d":"Se privilegiarán las actividades de turismo alternativo que no requieran infraestructura y equipamiento permanente (por ejemplo, senderismo y observación de fauna silvestre); cuando el proyecto sí requiera infraestructura, esta deberá sujetarse a los criterios de construcciones rústicas de bajo impacto establecidos para el turismo de naturaleza. [Nota: se reformuló para no contradecir los criterios que sí permiten construcciones de bajo impacto (cabañas, miradores, senderos); antes decía que el turismo alternativo \"se limitará a\" actividades sin infraestructura, lo cual entraba en conflicto directo con esos criterios.]","s":"Turismo alternativo"},"Tur01":{"d":"El turismo convencional podrá desarrollarse preferentemente en zonas con vocación turística reconocida, conectividad vial existente y servicios urbanos suficientes. Las edificaciones deben considerar la capacidad de carga del entorno en cuanto a agua potable, tratamiento de aguas residuales, energía y residuos sólidos. Deberá priorizarse el uso de materiales locales, eficiencia energética, tecnologías de bajo consumo hídrico y estrategias de integración paisajística.","s":"Turismo convencional"},"Tur02":{"d":"El número de visitantes, la ocupación y el tipo de infraestructura deberán alinearse con los instrumentos de planeación ecológica y urbana, considerando los periodos de estacionalidad y los efectos acumulativos de otras actividades turísticas o urbanas en el área.","s":"Turismo convencional"},"Tur03":{"d":"Cuando el turismo convencional implique desarrollos a gran escala en zonas con fragilidad ecológica (playas vírgenes, dunas, humedales, barrancas, zonas forestales, cuerpos de agua, áreas de recarga hídrica, islas, zonas arqueológicas no urbanizadas), será necesario aplicar instrumentos de evaluación ambiental específicos. También aplica cuando se proyecta modificar el uso de suelo rural o de conservación para urbanización turística, apertura de vialidades, instalaciones costeras (muelles, marinas, malecones) o infraestructura de alto consumo.","s":"Turismo convencional"},"Tur04":{"d":"Los proyectos deberán contemplar estudios integrales sobre biodiversidad, riesgo climático, disponibilidad hídrica, vulnerabilidad social, movilidad y efectos acumulativos, así como planes de restauración, monitoreo ambiental y medidas de integración al paisaje natural y cultural","s":"Turismo convencional"},"Tur05":{"d":"Los proyectos o desarrollos turísticos que se promuevan en la UGA deberán desarrollarse evitando las zonas identificadas como de riesgo alto y muy alto, para lo que deberán contar con un dictamen positivo de la unidad de protección civil municipal. El dictamen se realizará a partir de un estudio de riesgos que deberá presentar cada promovente de acuerdo a los lineamientos mínimos establecidos para dicho estudio.","s":"Turismo convencional"},"Tur06":{"d":"No se permitirá la instalación de proyectos turísticos que generen impactos a la calidad de vida de las personas, la imagen urbana y el patrimonio histórico-cultural del centro de población.","s":"Turismo convencional"},"Tur07":{"d":"En los proyectos turísticos promovidos o financiados total o parcialmente por instituciones del sector público se deberán capacitar a la población local en el manejo de los recursos naturales, patrimoniales, financieros y socio-organizativos necesarios para el aprovechamiento sustentable.","s":"Turismo convencional"},"Tur08":{"d":"Para la gestión y operación de los proyectos de desarrollo turístico promovidos o financiado total o parcialmente por instituciones del sector público se deberá emplear mano de obra de las comunidades locales equivalente al porcentaje de participación pública.","s":"Turismo convencional"},"Tur09":{"d":"Las áreas verdes de los proyectos turísticos deberán emplear vegetación nativa en al menos un 80 % de su superficie.","s":"Turismo convencional"},"Tur10":{"d":"Las actividades turísticas deberán respetar las tradiciones y costumbres de la población local.","s":"Turismo convencional"},"Tur11":{"d":"Los proyectos turísticos que se promuevan en la UGA deberán contar con sistemas de tratamiento de sus aguas residuales y un manejo integral de residuos sólidos.","s":"Turismo convencional"},"Tur12":{"d":"El desarrollo de proyectos de turismo convencional estará condicionado a que se cuenten con los títulos de concesión, y permisos de descarga en su caso, y a un dictamen de factibilidad hídrica emitido por la autoridad competente.","s":"Turismo convencional"},"Tru01":{"d":"Las actividades de turismo rural deberán respetar los ciclos agrícolas y los saberes locales. Las instalaciones turísticas deberán ser de bajo impacto (cabañas, sanitarios secos, senderos de interpretación, comedores comunitarios), integradas al entorno y usando materiales locales. Se deberán implementar medidas de manejo responsable del agua, energía y residuos. Las rutas de acceso deberán aprovechar caminos existentes, evitando apertura de brechas o afectación de áreas de cultivo o vegetación natural. Los visitantes deberán ser sensibilizados sobre las prácticas y valores del territorio, y la afluencia debe ajustarse a la capacidad de carga socioambiental.","s":"Turismo rural o agroturismo"},"Tru02":{"d":"Cuando el turismo rural implique reconversión intensiva del suelo (como urbanización, construcción de hoteles, fraccionamientos rurales, vialidades de alto volumen o instalaciones de lujo no compatibles con el entorno), afecte zonas con valor ecológico (bosques secundarios, humedales, corredores biológicos), o genere desplazamiento de actividades tradicionales y presión sobre acuíferos o cuerpos de agua, deberá someterse a evaluación ambiental detallada. El proyecto deberá contemplar análisis de impacto social, manejo de residuos, consumo hídrico, residuos orgánicos y recuperación del paisaje.","s":"Turismo rural o agroturismo"},"Tru03":{"d":"Prohibir la demolición, modificación estructural o ampliación de haciendas y ranchos antiguos sin la evaluación previa de instituciones de patrimonio cultural (INAH o instancias estatales) y sin dictamen técnico sobre impacto ambiental y arquitectónico.","s":"Turismo rural o agroturismo"},"Tru04":{"d":"Preservar el trazo original y funcionalidad de caminos rurales históricos, evitando su pavimentación o rectificación sin estudios previos, ya que constituyen corredores de conectividad ecológica, cultural y agricola.","s":"Turismo rural o agroturismo"},"Tru05":{"d":"Establecer una zona de amortiguamiento de al menos 30 metros alrededor de haciendas y ranchos patrimoniales, en la que se restrinjan desarrollos urbanos, industrias, rellenos o bancos de materiales.","s":"Turismo rural o agroturismo"},"Tru06":{"d":"Fomentar el uso compatible de haciendas y ranchos como centros de producción agroecológica, educación ambiental, turismo rural o espacios comunitarios, priorizando su conservación activa.","s":"Turismo rural o agroturismo"},"Tru07":{"d":"Evitar la construcción de infraestructura (líneas eléctricas, caminos nuevos, tuberías o sistemas de riego presurizado) que altere la imagen del paisaje, cause fragmentación ecológica o afecte la estructura física de caminos y ranchos.","s":"Turismo rural o agroturismo"},"Tru08":{"d":"Incentivar la restauración arquitectónica y paisajística de haciendas y ranchos con materiales tradicionales y técnicas compatibles con su valor histórico, promoviendo el rescate de prácticas constructivas vernáculas.","s":"Turismo rural o agroturismo"},"Tru09":{"d":"Garantizar el acceso libre y seguro a caminos rurales comunales y de tránsito ejidal, evitando su privatización, obstrucción o desvío por intereses particulares o nuevos desarrollos.","s":"Turismo rural o agroturismo"},"Tru10":{"d":"Establecer rutas patrimoniales y corredores agroecológicos que conecten haciendas, ranchos, manantiales, capillas y caminos rurales con alto valor cultural y ecológico, integrándolos a propuestas de turismo responsable.","s":"Turismo rural o agroturismo"},"InfB01":{"d":"Los proyectos, estudios, dictámenes, medidas, acciones a desarrollar para la instalación de nuevas obras de infraestructura se publicarán en la Bitácora Ambiental para su consulta.","s":"Infraestructura de bajo impacto (general)"},"InfB02":{"d":"La construcción de caminos deberá prever al menos el 50% de materiales que permitan la infiltración del agua pluvial al subsuelo, los cuales deberán ser estables, consolidados y con drenes adecuados a la dinámica hidráulica natural.","s":"Infraestructura de bajo impacto (general)"},"InfB03":{"d":"Los taludes en caminos deberán estabilizarse y reforestarse con especies nativas de porte bajo.","s":"Infraestructura de bajo impacto (general)"},"InfB04":{"d":"En las zonas carentes de infraestructura sanitaria, de energía o con déficit en el servicio, se deberá implementar ecotecnias y energías renovables como primera opción.","s":"Infraestructura de bajo impacto (general)"},"InfB05":{"d":"En las áreas de dotación de infraestructura de proyectos habitacionales que se promuevan en la UGA deberán aplicar diseños y técnicas de tipo ecológico.","s":"Infraestructura de bajo impacto (general)"},"InfB06":{"d":"Se toman en cuenta las prácticas culturales, los valores y las tradiciones para el diseño de los proyectos de infraestructura","s":"Infraestructura de bajo impacto (general)"},"InfB07":{"d":"Los residuos vegetales generados por las actividades de desmonte serán triturados o picados, mezclados y esparcidos en la superficie del terreno que se destine para áreas verdes o ser enviados para un fin similar fuera de la instalación. En caso de ser desechados, se considerarán como residuos y se sujetarán a lo que defina la autoridad competente o en su caso el plan de manejo correspondiente.","s":"Infraestructura de bajo impacto (general)"},"InfB08":{"d":"Para restaurar o restablecer la vegetación se utilizarán las especies vegetales propias del lugar susceptibles de desarrollarse en el sitio, conforme a la descripción del ambiente elaborada y aprobada.","s":"Infraestructura de bajo impacto (general)"},"InfB09":{"d":"El acceso peatonal a las playas a través de las dunas costeras será por medio de andadores tipo armadura, de material degradable y prefabricado, piloteado y no cimentado. Los andadores y plataformas que se localicen sobre el sistema de dunas deben elevarse lo suficiente para permitir el crecimiento de la vegetación (al menos un metro de elevación) y el paso de sedimentos y de fauna.","s":"Infraestructura de bajo impacto (general)"},"InfB10":{"d":"Solo se permitirá la instalación de obras de infraestructura puntual indispensables para el desarrollo de las personas y que no tengan alternativa de desarrollarse en otro sitio. Las obras de infraestructura puntual no deberán generar efectos negativos que modifiquen la estructura o alteren las funciones de los ecosistemas o recursos naturales.","s":"Infraestructura de bajo impacto (general)"},"InfB11":{"d":"Las obras de infraestructura puntual deberán desarrollarse en zonas carentes de vegetación arbórea y arbustiva, y en casos excepcionales se permitirá la remoción de vegetación en una superficie no mayor de 100 m2.","s":"Infraestructura de bajo impacto (general)"},"InfB12":{"d":"No se permitirán obras de infraestructura puntual que generen impactos sobre rasgos patrimoniales (naturales identitarios, arqueológicos, históricos y/o culturales)","s":"Infraestructura de bajo impacto (general)"},"InfB13":{"d":"No se permitirá la remoción, ahuyentamiento, relocalización o trasplante de especies en riesgo derivado de la instalación de infraestructura puntual, de acuerdo con el listado de la NOM-059-SEMARNAT-2010 o su correspondiente actualización o modificación","s":"Infraestructura de bajo impacto (general)"},"InfB14":{"d":"Los estudios, medidas, obras y acciones a desarrollar durante la instalación de nuevos proyectos de infraestructura puntual deberán difundirse a las comunidades rurales o localidades involucradas según corresponda.","s":"Infraestructura de bajo impacto (general)"},"InfB15":{"d":"Se permitirá la instalación de infraestructura de disposición lineal para la dotación de servicios básicos a las comunidades como agua potable, alcantarillado o drenaje (el cual deberá incluir el tratamiento de agua residual) y energía eléctrica, con la reducción y mitigación de los impactos significativos. No se permitirá la infraestructura de área.","s":"Infraestructura de bajo impacto (general)"},"InfB16":{"d":"Los proyectos de infraestructura líneal que se promuevan en la UGA deberán desarrollarse evitando las zonas identificadas como prioritarias para la conservación de los ecosistemas y la biodiversidad, el mantenimiento de los bienes y servicios ambientales, de recarga y para la preservación del patrimonio histórico, arqueológico, paleontológico y cultural en el presente instrumento y por las autoridades competentes","s":"Infraestructura de bajo impacto (general)"},"InfB17":{"d":"La construcción de infraestructura líneal se realizará, de ser posible, sobre el derecho de vía de caminos ya construidos, con la finalidad de evitar la fragmentación de los ecosistemas presentes en el área y el cambio de uso de zona agrícola y forestal.","s":"Infraestructura de bajo impacto (general)"},"InfB18":{"d":"La instalación de infraestructura lineal deberá evitar impactos significativos sobre el uso de suelo agrícola.","s":"Infraestructura de bajo impacto (general)"},"InfB19":{"d":"No se permitirá la instalación de infraestructura líneal que genere impactos a la imagen urbana y el patrimonio histórico-cultural del centro de población.","s":"Infraestructura de bajo impacto (general)"},"InfB20":{"d":"Los proyectos de infraestructura líneal que se promuevan deberán considerar la incorporación de vegetación arbórea en las zonas de derecho de vía, camellones y banquetas. Las especies deberán ser nativas y acordes a los diferentes tipos de vialidades, para evitar cualquier tipo de riesgo, desde pérdida de visibilidad, hasta deterioro en las construcciones y banquetas, incluyendo la caída de ramas o derribo de árboles por efecto del viento.","s":"Infraestructura de bajo impacto (general)"},"InfB21":{"d":"En el desarrollo de nuevos proyectos de infraestructura lineal se deberá contemplar programas de rescate de fauna silvestre que serán sometidos a su validación por instituciones académicas y de investigación, así como por un comité colegiado ciudadano.","s":"Infraestructura de bajo impacto (general)"},"InfB22":{"d":"Los proyectos de infraestructura de área deberán considerar medidas en su diseño y funcionamiento para la captación de agua pluvial, la generación de energías limpias, el tratamiento de sus aguas residuales y manejo adecuado de sus residuos sólidos.","s":"Infraestructura de bajo impacto (general)"},"Cgral01":{"d":"Los proyectos, obras o actividades que hayan sido sometidos al procedimiento de evaluación de impacto ambiental con anterioridad a la publicación del Programa de Ordenamiento Ecológico Local conservarán la validez de su autorización siempre que se mantengan estrictamente dentro de las condiciones, alcances y características aprobadas en su resolución ambiental. Estos proyectos no serán considerados, para efectos del POEL, como generadores de afectación ambiental siempre que no presenten modificaciones, ampliaciones, cambios tecnológicos, incrementos de capacidad, alteraciones en la ocupación del suelo o cualquier otra variación que pudiera elevar los impactos originalmente evaluados. En caso de detectar cualquier desviación, incumplimiento o alteración respecto al proyecto autorizado, la autoridad ambiental competente podrá exigir la actualización de la evaluación de impacto ambiental y su adecuación a lo establecido por el POEL vigente. La dispensa de afectación ambiental no aplicará cuando el proyecto se encuentre en áreas de conservación, barrancas, ecosistemas sensibles o UGAs con política de protección o preservación, en cuyo caso la autoridad deberá verificar de manera prioritaria que las actividades no comprometan los servicios ecosistémicos ni generen riesgos adicionales al territorio. Bajo ninguna circunstancia este criterio podrá ser utilizado para justificar nuevas autorizaciones, ampliaciones encubiertas o regularizaciones posteriores que pretendan eludir las disposiciones del POEL. La autoridad estatal y municipal se reservarán el derecho de realizar inspecciones, solicitar información adicional o requerir medidas de mitigación adicionales cuando existan elementos que indiquen riesgos ambientales no previstos en la autorización original.","s":"Criterios generales"},"Cgral02":{"d":"Se promoverá la implantación dispersa y adaptada a la topografía, evitando cortes, rellenos y modificaciones significativas del relieve.","s":"Criterios generales"},"Cgral03":{"d":"Las actividades deberán integrarse al paisaje y minimizar impactos visuales, acústicos y ecológicos.","s":"Criterios generales"},"Cgral04":{"d":"El establecimiento, crecimiento o ampliación de asentamientos humanos se permitirá de manera condicionada a la obtención previa de dictámenes de factibilidad y estudios emitidos por Protección Civil, la Comisión Nacional del Agua (CONAGUA) y la Secretaría de Medio Ambiente estatal, esta última en atención a la conectividad ecológica y a la relevancia ambiental del área, especialmente cuando se trate de corredores biológicos o zonas de alto valor ambiental; se prohíbe su desarrollo en zonas de alto riesgo, particularmente donde confluyan riesgos de inundación y deslizamientos de ladera, debiendo priorizarse la prevención, la preservación de áreas de regulación hidrológica y la conectividad ambiental, así como, en su caso, la reubicación de población en situación de riesgo.","s":"Criterios generales"},"Cgral05":{"d":"Se restringirá el establecimiento de nuevos asentamientos humanos, infraestructura crítica o cambios de uso de suelo en zonas inundables y áreas de influencia de cauces.","s":"Criterios generales"},"Cgral06":{"d":"Se conservará o restaurará la vegetación ribereña como barrera natural de protección frente a inundaciones y procesos erosivos.","s":"Criterios generales"},"Cgral07":{"d":"Se priorizará la implementación de infraestructura verde (parques inundables, jardines de lluvia, humedales artificiales, zanjas de infiltración y pavimentos permeables) sobre obras de canalización rígida, cuando sea técnica y ambientalmente viable.","s":"Criterios generales"},"Cgral08":{"d":"Se promoverá la recuperación de planicies de inundación para favorecer el almacenamiento temporal de escurrimientos extraordinarios.","s":"Criterios generales"},"Cgral09":{"d":"Se evitará el relleno, estrechamiento o modificación de cauces naturales y zonas federales que incrementen el riesgo de inundación aguas arriba o aguas abajo.","s":"Criterios generales"},"Cgral10":{"d":"Se fomentará la reubicación gradual de asentamientos ubicados en zonas de muy alto riesgo, cuando los estudios técnicos determinen que las medidas de mitigación son insuficientes.","s":"Criterios generales"},"Cgral11":{"d":"Se prohíbe la expansión de los asentamientos humanos hacia zonas con alta y muy alta susceptibilidad a inundaciones, deslaves y derrumbes. En los asentamientos existentes se promoverá la reubicación gradual de la población, la vivienda y la infraestructura localizada en áreas de riesgo no mitigable, conforme a los instrumentos aplicables.","s":"Criterios generales"}},"est":{"ESa01":{"d":"Protección y conservación de ecosistemas estratégicos","s":"Sustentabilidad ambiental"},"ESa02":{"d":"Restauración ecológica y recuperación de ecosistemas degradados","s":"Sustentabilidad ambiental"},"ESa03":{"d":"Conservación, restauración y manejo sostenible del suelo","s":"Sustentabilidad ambiental"},"ESa04":{"d":"Conservación de la biodiversidad y de especies prioritarias","s":"Sustentabilidad ambiental"},"ESa05":{"d":"Conservación comunitaria de la biodiversidad y fortalecimiento de las UMAs","s":"Sustentabilidad ambiental"},"ESa06":{"d":"Investigación, monitoreo y cultura ambiental para la sustentabilidad","s":"Sustentabilidad ambiental"},"ESa07":{"d":"Gestión integral de cuencas y restauración de ríos y zonas ribereñas","s":"Sustentabilidad ambiental"},"ESa08":{"d":"Gestión integral del agua y saneamiento ambiental","s":"Sustentabilidad ambiental"},"ESa09":{"d":"Prevención y control de la contaminación ambiental por emisiones, quemas y agroquímicos","s":"Sustentabilidad ambiental"},"ESa10":{"d":"Gestión integral de residuos y economía circular comunitaria","s":"Sustentabilidad ambiental"},"ESa11":{"d":"Restauración y remediación de sitios contaminados","s":"Sustentabilidad ambiental"},"ESa12":{"d":"Acción climática para la mitigación y adaptación al cambio climático","s":"Sustentabilidad ambiental"},"ESa13":{"d":"Gestión integral del riesgo y resiliencia frente a desastres","s":"Sustentabilidad ambiental"},"ESa14":{"d":"Transición energética y energías renovables para el desarrollo local","s":"Sustentabilidad ambiental"},"ESa15":{"d":"Prevención, manejo y restauración de áreas afectadas por incendios forestales","s":"Sustentabilidad ambiental"},"ESa16":{"d":"Transición hacia sistemas productivos con manejo agroecológico","s":"Sustentabilidad ambiental"},"ESa17":{"d":"Aprovechamiento sostenible de los recursos pesqueros y de la biodiversidad","s":"Sustentabilidad ambiental"},"EDe01":{"d":"Agricultura sostenible, resiliente y climáticamente inteligente","s":"Desarrollo económico sostenible"},"EDe02":{"d":"Diversificación productiva y fortalecimiento de cadenas de valor rurales","s":"Desarrollo económico sostenible"},"EDe03":{"d":"Fortalecimiento de la cafeticultura sostenible y los sistemas agroforestales","s":"Desarrollo económico sostenible"},"EDe04":{"d":"Fortalecimiento de la producción sostenible de frutales tropicales","s":"Desarrollo económico sostenible"},"EDe05":{"d":"Ganadería sostenible y reconversión silvopastoril","s":"Desarrollo económico sostenible"},"EDe06":{"d":"Pesca ribereña y acuacultura sostenible","s":"Desarrollo económico sostenible"},"EDe07":{"d":"Apicultura sostenible y conservación de polinizadores nativos","s":"Desarrollo económico sostenible"},"EDe08":{"d":"Manejo forestal comunitario y aprovechamiento sostenible de recursos forestales","s":"Desarrollo económico sostenible"},"EDe09":{"d":"Fortalecimiento de la agroindustria rural y el valor agregado local","s":"Desarrollo económico sostenible"},"EDe10":{"d":"Pago por servicios ambientales y mecanismos de conservación productiva","s":"Desarrollo económico sostenible"},"EDe11":{"d":"Turismo de naturaleza y comunitario sostenible","s":"Desarrollo económico sostenible"},"EDe12":{"d":"Industria local sostenible y economía circular","s":"Desarrollo económico sostenible"},"EGo01":{"d":"Ordenamiento ecológico y gestión sostenible del territorio","s":"Gobernanza"},"EGo02":{"d":"Gobernanza ambiental, participación social y corresponsabilidad comunitaria","s":"Gobernanza"},"EGo03":{"d":"Fortalecimiento institucional para la gestión ambiental, territorial y del riesgo","s":"Gobernanza"}},"lin":{"LIN_18":"Impulsar el establecimiento y desarrollo de la industria únicamente en zonas con vocación industrial o de logistica delimitadas en los instrumentos de planeación territorial, asegurando la compatibilidad ambiental mediante la incorporación de infraestructura adecuada, el cumplimiento de la normatividad vigente y la adopción de practicas industriales sustentables.","LIN_12":"Aprovechar sustentablemente la minería no metálica, promoviendo la conservación de los recursos naturales y el bienestar de las comunidades locales, mediante la restauración y reforestación de áreas afectadas, prevenir la erosión y gestionar eficientemente el agua. Priorizar el reciclaje y la disposición correcta de los residuos, evitando la contaminación y estableciendo sistemas de monitoreo continúo a corto, mediano y largo plazo.","LIN_19":"Garantizar el funcionamiento ambientalmente responsable de la planta de tratamiento de aguas residuales mediante la operación eficiente de procesos de tratamiento primario, secundario y terciario, con el fin de asegurar que el efluente cumpla con los límites máximos permisibles establecidos por la normatividad vigente antes de su descarga o reúso. Se deberá priorizar el reúso del agua tratada en actividades agrícolas, industriales o de servicios, y la disposición final de los lodos residuales deberá realizarse con criterios de inocuidad y trazabilidad. La planta deberá contar con zonas de amortiguamiento arboladas de al menos 20 metros de ancho, sistemas de control de olores, y monitoreo continuo de calidad del agua, con énfasis en parámetros como DBO, DQO, sólidos suspendidos y patógenos. Además, se fomentará la participación comunitaria en el monitoreo ambiental y en los programas de restauración del entorno inmediato.","LIN_20":"Cumplir con las diferentes Normas Oficiales Mexicanas, que establecen los criterios para la elaboración de programas de manejo de residuos sólidos urbanos y de manejo especial, buscando la prevención y reducción de la generación de residuos, así como en la valorización de los mismos, promoviendo prácticas sustentables, reduciendo riesgos para la salud y el ambiente, y fomentando la participación ciudadana en la gestión de residuos. Este lineamiento se aplica a toda la superficie de la UGA.","LIN_16":"Aprovechamiento sustentable de las áreas tradicionales de agricultura y pastoreo y la consolidación del cultivo de café, promoviendo la recuperación de los suelos degradados, así como la creación de corredores biológicos y piedras de paso que favorezcan la conectividad entre diferentes ecosistemas.","LIN_01":"Aprovechar sustentablemente los recursos ambientales y paisajes del asentamiento humano rural, asegurando que disponga de las medidas mínimas que eviten la contaminación por residuos sólidos, descargas de aguas no tratadas y uso descontrolado del medio ambiente, en particular si la localidad aumenta su población más allá de su tasa de crecimiento natural. Este lineamiento se aplica a toda la superficie de la UGA .","LIN_02":"Aprovechar sustentablemente los recursos ambientales y paisajes del asentamiento urbano, garantizando que el Programa de Desarrollo Urbano sea compatible con el POEL, en el sentido de procurar una calidad ecológica y de vida adecuadas para los habitantes del asentamiento urbano, la zona de crecimiento y su área de influencia, considerando la inclusión urbana, el derecho a la ciudad, la accesibilidad universal a servicios, la igualdad de género, potenciando el desarrollo urbano mediante el impulso económico atendiendo a las particularidades sociales, culturales y ambientales. Este lineamiento se aplica a toda la superficie de la UGA .","LIN_21":"Impulsar el desarrollo de un corredor comercial planificado que concentre actividades de servicios, comercio y logística, garantizando la accesibilidad y la integración paisajística, así como el manejo adecuado de residuos y la eficiencia en el uso de recursos hídricos, energéticos y del suelo","LIN_08":"Preservar el área agrícola de alta productividad por su importante valor productivo y su importancia cultural regional; aprovechando su valor intrínseco por su ubicación particular, fomentando el usode técnicas sustentables de cultivo, favoreciendo proyectos de agricultura sostenible vinculados a desarrollos agroindutriales que brinden un valor agregado a los productos regionales, promoviendo laaplicación de una agricultura climáticamente inteligente.","LIN_15":"Mejorar el aprovechamiento sustentable de las áreas tradicionales de agricultura y ganadería extensiva mediante el impulso económico que aumente su productividad y reduzca las pérdidas en los predioscon vocación agropecuaria, aplicando paquetes tecnológicos que fomenten procesos de agricultura cimáticamente inteligente.","LIN_10":"Preservar la biodiversidad y las funciones ecológicas de los ecosistemas, mediante su adecuado manejo ambiental promoviendo actividades alternativas de bajo impacto de acuerdo con la vocación del suelo y los usos y costumbres de las comunidades locales y la consolidación del cultivo sustentable de café, para garantizar la preservación de la biodiversidad en el mediano y largo plazo","LIN_07":"Proteger el cauce de río y los relictos actuales de vegetación, mediante la implementación de medidas de conservación, restauración y gestión sostenible, promoviendo la declaratoria de un área natural protegida de carácter municipal, estatal o federal, para garantizar la conservación a largo plazo de los ecosistemas presentes en la UGA, en colaboración con comunidades locales, instituciones gubernamentales y organizaciones ambientales.","LIN_14":"Proteger los ecosistemas naturales y su biodiversidad promoviendo la declaratoria de un área natural protegida de carácter municipal que comprenda el territorio de la UGA.","LIN_11":"Proteger los ecosistemas naturales y su biodiversidad promoviendo la declaratoria de un área natural protegida de carácter municipal que comprenda el territorio de la UGA y consolidar el cultivo sustentable de café","LIN_03":"Proteger el ADVC con base en la estrategia de manejo comunitario establecida para la conservación activa de la flora y fauna, la recuperación de los ecosistemas que han sido degradados, la rehabilitación de suelos, la reintroducción de especies nativas, el fortalecimiento de la gobernanza territorial, la realización de actividades económicas sustentables, como la agricultura orgánica, el turismo ecológico, entre otros, promoviendo la adaptación de las comunidades locales al cambio climático y la formación de científicos comunitarios de manera permanente para que se constituyan en guardianes del territorio.","LIN_05":"Proteger el ANP, con base en el programa de manejo decretado, o en caso con lo establecido en el decreto federal correspondiente, mediante instrumentos ambientales que garanticen mantener la representatividad de los ecosistemas, la biodiversidad, la conectividad y la provisión de servicios ambientales, fomentando el buen vivir de las actuales y futuras generaciones con enfoque de inclusión, las actividades productivas que utilicen","LIN_17":"Proteger los ecosistemas naturales y su biodiversidad promoviendo la declaratoria de un área natural protegida de carácter estatal o federal que comprenda el territorio de la UGA.","LIN_04":"Restaurar las áreas del corredor ripario, promoviendo la recuperación de su vegetación ribereña, el control de escorrentías, la mejora de la calidad del agua y la conectividad ecológica entre fragmentos de hábitat, con el fin de restablecer su función como zona de amortiguamiento, refugio de biodiversidad y eje de conectividad biológica.","LIN_09":"Restaurar las áreas de producción agropecuaria, fomentando el aprovechamiento sustentable de las áreas tradicionales de agricultura y pastoreo y la consolidación del cultivo de café, promoviendo la recuperación de los suelos degradados, así como la creación de corredores biológicos y piedras de paso que favorezcan la conectividad entre diferentes ecosistemas.","LIN_13":"Recuperar la cobertura vegetal y funciones ecológicas de los ecosistemas originales, priorizando aquellas zonas deforestadas por actividades agropecuarias con vocación forestal, así como los territorios que mantengan ecosistemas degradados. Promover el impulso económico de actividades alternativas que procure la adecuada reconversión productiva según la vocación del suelo y los usos y costumbres de las comunidades locales.","LIN_06":"Establecer y conservar zonas de amortiguamiento entre los asentamientos humanos y los cauces, ríos y áreas con susceptibilidad a inundaciones, mediante la protección y restauración de la vegetación ribereña, la restricción de nuevos desarrollos urbanos en zonas de riesgo y la implementación de infraestructura verde que favorezca la infiltración, el almacenamiento temporal y el flujo natural del agua, con el fin de reducir la vulnerabilidad de la población y mantener los servicios ecosistémicos asociados a los sistemas fluviales."},"secs":["Agricultura de riego","Agricultura de temporal","Agroecosistemas de café bajo sombra","Agroecosistemas de cacao","Agroindustria","Apicultura","Acuícola","Asentamientos humanos rurales","Asentamientos humanos urbanos","Conservación","Comercio","Manejo forestal maderable","Manejo forestal no maderable","Ganadería extensiva","Ganadería intensiva","Industria de bajo impacto o industria ligera","Infraestructura azul","Infraestructura azul restringida","Infraestructura verde","Infraestructura vial","Infraestructura turística: miradores","Infraestructura eléctrica","Infraestructura turística: cabañas","Infraestructura de servicios (drenaje y agua potable)","Infraestructura de tratamiento de aguas residuales","Infraestructura de control de erosión","Infraestructura de señalética ecológica","Infraestructura de distribución y expendio de hidrocarburos","infraestructura de residuos sólidos urbanos","Infraestructura complementaria a asentamientos humanos","plantaciones de frutales","Plantaciones de palmeras","Proyectos de generación de energía solar","Proyectos de generación de energía eólica","Minería no metálica","Pesca ribereña","Escombreras","Turismo alternativo","Turismo convencional","Turismo rural o agroturismo","Infraestructura de bajo impacto (general)","Criterios generales"],"bounds":[[-100.53935447968732,17.059725140046897,-100.10669002807617,17.564409289890342]],"n_ugas":130,"sup_total":144896.8,"pob_total":60608};
